INSERT INTO public.bible_verses (book_no, book_abbr, book_name, chapter, verse, content, language, translation)
VALUES
  ('2', 'kel', 'Keluaran', 34, 12, 'Berawas-awaslah, janganlah kauadakan perjanjian dengan penduduk negeri yang kaudatangi itu, supaya jangan mereka menjadi jerat bagimu di tengah-tengahmu.', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 34, 13, 'Sebaliknya, mezbah-mezbah mereka haruslah kamu rubuhkan, tugu-tugu berhala mereka kamu remukkan, dan tiang-tiang berhala mereka kamu tebang.', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 34, 14, 'Sebab janganlah engkau sujud menyembah kepada allah lain, karena TUHAN, yang nama-Nya Cemburuan, adalah Allah yang cemburu.', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 34, 15, 'Janganlah engkau sampai mengadakan perjanjian dengan penduduk negeri itu; apabila mereka berzinah dengan mengikuti allah mereka dan mempersembahkan korban kepada allah mereka, maka mereka akan mengundang engkau dan engkau akan ikut makan korban sembelihan mereka.', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 34, 16, 'Apabila engkau mengambil anak-anak perempuan mereka menjadi isteri anak-anakmu dan anak-anak perempuan itu akan berzinah dengan mengikuti allah mereka, maka mereka akan membujuk juga anak-anakmu laki-laki untuk berzinah dengan mengikuti allah mereka.', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 34, 17, 'Janganlah kaubuat bagimu allah tuangan.', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 34, 18, 'Hari raya Roti Tidak Beragi haruslah kaupelihara; tujuh hari lamanya engkau harus makan roti yang tidak beragi, seperti yang Kuperintahkan kepadamu, pada waktu yang ditetapkan dalam bulan Abib, sebab dalam bulan Abib itulah engkau keluar dari Mesir.', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 34, 19, 'Segala apa yang lahir terdahulu dari kandungan, Akulah yang empunya, juga segala ternakmu yang jantan, anak yang lahir terdahulu dari lembu atau domba.', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 34, 20, 'Tetapi anak yang lahir terdahulu dari keledai haruslah kautebus dengan seekor domba; jika tidak kautebus, haruslah kaupatahkan batang lehernya. Setiap yang sulung dari antara anak-anakmu haruslah kautebus, dan janganlah orang menghadap ke hadirat-Ku dengan tangan hampa.', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 34, 21, 'Enam harilah lamanya engkau bekerja, tetapi pada hari yang ketujuh haruslah engkau berhenti, dan dalam musim membajak dan musim menuai haruslah engkau memelihara hari perhentian juga.', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 34, 22, 'Hari raya Tujuh Minggu, yakni hari raya buah bungaran dari penuaian gandum, haruslah kaurayakan, juga hari raya pengumpulan hasil pada pergantian tahun.', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 34, 23, 'Tiga kali setahun segala orangmu yang laki-laki harus menghadap ke hadirat Tuhanmu TUHAN, Allah Israel,', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 34, 24, 'sebab Aku akan menghalau bangsa-bangsa dari depanmu dan meluaskan daerahmu; dan tiada seorangpun yang akan mengingini negerimu, apabila engkau pergi untuk menghadap ke hadirat TUHAN, Allahmu, tiga kali setahun.', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 34, 25, 'Janganlah darah korban sembelihan yang kepada-Ku kaupersembahkan beserta sesuatu yang beragi, dan janganlah ada dari korban sembelihan pada hari raya Paskah bermalam sampai pagi.', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 34, 26, 'Yang terbaik dari buah bungaran hasil tanahmu haruslah kaubawa ke dalam rumah TUHAN, Allahmu. Janganlah engkau masak anak kambing dalam susu induknya."', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 34, 27, 'Berfirmanlah TUHAN kepada Musa: "Tuliskanlah segala firman ini, sebab berdasarkan firman ini telah Kuadakan perjanjian dengan engkau dan dengan Israel."', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 34, 28, 'Dan Musa ada di sana bersama-sama dengan TUHAN empat puluh hari empat puluh malam lamanya, tidak makan roti dan tidak minum air, dan ia menuliskan pada loh itu segala perkataan perjanjian, yakni Kesepuluh Firman.', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 34, 29, 'Ketika Musa turun dari gunung Sinai?kedua loh hukum Allah ada di tangan Musa ketika ia turun dari gunung itu?tidaklah ia tahu, bahwa kulit mukanya bercahaya oleh karena ia telah berbicara dengan TUHAN.', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 34, 30, 'Ketika Harun dan segala orang Israel melihat Musa, tampak kulit mukanya bercahaya, maka takutlah mereka mendekati dia.', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 34, 31, 'Tetapi Musa memanggil mereka, maka Harun dan segala pemimpin jemaah itu berbalik kepadanya dan Musa berbicara kepada mereka.', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 34, 32, 'Sesudah itu mendekatlah segala orang Israel, lalu disampaikannyalah kepada mereka segala perintah yang diucapkan TUHAN kepadanya di atas gunung Sinai.', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 34, 33, 'Setelah Musa selesai berbicara dengan mereka, diselubunginyalah mukanya.', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 34, 34, 'Tetapi apabila Musa masuk menghadap TUHAN untuk berbicara dengan Dia, ditanggalkannyalah selubung itu sampai ia keluar; dan apabila ia keluar dikatakannyalah kepada orang Israel apa yang diperintahkan kepadanya.', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 34, 35, 'Apabila orang Israel melihat muka Musa, bahwa kulit muka Musa bercahaya, maka Musa menyelubungi mukanya kembali sampai ia masuk menghadap untuk berbicara dengan TUHAN.', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 35, 1, 'Lalu Musa menyuruh berkumpul segenap jemaah Israel dan berkata kepada mereka: "Inilah firman yang diperintahkan TUHAN untuk dilakukan.', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 35, 2, 'Enam hari lamanya boleh dilakukan pekerjaan, tetapi pada hari yang ketujuh haruslah ada perhentian kudus bagimu, yakni sabat, hari perhentian penuh bagi TUHAN; setiap orang yang melakukan pekerjaan pada hari itu, haruslah dihukum mati.', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 35, 3, 'Janganlah kamu memasang api di manapun dalam tempat kediamanmu pada hari Sabat."', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 35, 4, 'Berkatalah Musa kepada segenap jemaah Israel: "Inilah firman yang diperintahkan TUHAN, bunyinya:', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 35, 5, 'Ambillah bagi TUHAN persembahan khusus dari barang kepunyaanmu; setiap orang yang terdorong hatinya harus membawanya sebagai persembahan khusus kepada TUHAN: emas, perak, tembaga,', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 35, 6, 'kain ungu tua, kain ungu muda, kain kirmizi, lenan halus, bulu kambing;', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 35, 7, 'kulit domba jantan yang diwarnai merah, kulit-kulit lumba-lumba, kayu penaga,', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 35, 8, 'minyak untuk penerangan, rempah-rempah untuk minyak urapan dan untuk ukupan dari wangi-wangian,', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 35, 9, 'permata krisopras dan permata tatahan untuk baju efod dan untuk tutup dada.', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 35, 10, 'Segala orang yang ahli di antara kamu haruslah datang untuk membuat segala yang diperintahkan TUHAN,', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 35, 11, 'yakni Kemah Suci, atap kemahnya dan tudungnya, kaitannya, dan papannya, kayu lintangnya, tiangnya dan alasnya;', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 35, 12, 'tabut dengan kayu pengusungnya, tutup pendamaian dan tabir penudung;', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 35, 13, 'meja dengan kayu pengusungnya, segala perkakasnya dan roti sajian;', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 35, 14, 'kandil untuk penerangan dengan perkakasnya, lampunya dan minyak untuk penerangan;', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 35, 15, 'mezbah pembakaran ukupan dengan kayu pengusungnya, minyak urapan dan ukupan dari wangi-wangian; tirai pintu untuk pintu Kemah Suci;', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 35, 16, 'mezbah korban bakaran dengan kisi-kisi tembaganya, kayu pengusungnya dan segala perkakasnya, bejana pembasuhan dengan alasnya;', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 35, 17, 'layar pelataran, tiangnya, alasnya dan tirai pintu gerbang pelataran itu;', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 35, 18, 'patok Kemah Suci dan patok pelataran dan talinya;', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 35, 19, 'pakaian jabatan untuk menyelenggarakan kebaktian di tempat kudus, dan pakaian kudus bagi imam Harun, dan pakaian anak-anaknya untuk memegang jabatan imam."', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 35, 20, 'Lalu pergilah segenap jemaah Israel dari depan Musa.', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 35, 21, 'Sesudah itu datanglah setiap orang yang tergerak hatinya, setiap orang yang terdorong jiwanya, membawa persembahan khusus kepada TUHAN untuk pekerjaan melengkapi Kemah Pertemuan dan untuk segala ibadah di dalamnya dan untuk pakaian kudus itu.', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 35, 22, 'Maka datanglah mereka, baik laki-laki maupun perempuan, setiap orang yang terdorong hatinya, dengan membawa anting-anting hidung, anting-anting telinga, cincin meterai dan kerongsang, segala macam barang emas; demikian juga setiap orang yang mempersembahkan persembahan unjukan dari emas bagi TUHAN.', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 35, 23, 'Juga setiap orang yang mempunyai kain ungu tua, kain ungu muda, kain kirmizi, lenan halus, bulu kambing, kulit domba jantan yang diwarnai merah dan kulit lumba-lumba, datang membawanya.', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 35, 24, 'Setiap orang yang hendak mempersembahkan persembahan khusus dari perak atau tembaga, membawa persembahan khusus yang kepada TUHAN itu, dan setiap orang yang mempunyai kayu penaga membawanya juga untuk segala pekerjaan mendirikan itu.', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 35, 25, 'Setiap perempuan yang ahli, memintal dengan tangannya sendiri dan membawa yang dipintalnya itu, yakni kain ungu tua, kain ungu muda, kain kirmizi dan lenan halus.', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 35, 26, 'Semua perempuan yang tergerak hatinya oleh karena ia berkeahlian, memintal bulu kambing.', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 35, 27, 'Pemimpin-pemimpin membawa permata krisopras dan permata tatahan untuk baju efod dan untuk tutup dada,', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 35, 28, 'rempah-rempah dan minyak untuk penerangan, untuk minyak urapan dan untuk ukupan dari wangi-wangian.', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 35, 29, 'Semua laki-laki dan perempuan, yang terdorong hatinya akan membawa sesuatu untuk segala pekerjaan yang diperintahkan TUHAN dengan perantaraan Musa untuk dilakukan?mereka itu, yakni orang Israel, membawanya sebagai pemberian sukarela bagi TUHAN.', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 35, 30, 'Berkatalah Musa kepada orang Israel: "Lihatlah, TUHAN telah menunjuk Bezaleel bin Uri bin Hur, dari suku Yehuda,', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 35, 31, 'dan telah memenuhinya dengan Roh Allah, dengan keahlian, pengertian dan pengetahuan, dalam segala macam pekerjaan,', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 35, 32, 'yakni untuk membuat berbagai rancangan supaya dikerjakan dari emas, perak dan tembaga;', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 35, 33, 'untuk mengasah batu permata supaya ditatah; untuk mengukir kayu dan untuk bekerja dalam segala macam pekerjaan yang dirancang itu.', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 35, 34, 'Dan TUHAN menanam dalam hatinya, dan dalam hati Aholiab bin Ahisamakh dari suku Dan, kepandaian untuk mengajar.', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 35, 35, 'Ia telah memenuhi mereka dengan keahlian, untuk membuat segala macam pekerjaan seorang tukang, pekerjaan seorang ahli, pekerjaan seorang yang membuat tenunan yang berwarna-warna dari kain ungu tua, kain ungu muda, kain kirmizi dan lenan halus, dan pekerjaan seorang tukang tenun, yakni sebagai pelaksana segala macam pekerjaan dan perancang segala sesuatu.', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 36, 1, 'Demikianlah harus bekerja Bezaleel dan Aholiab, dan setiap orang yang ahli, yang telah dikaruniai TUHAN keahlian dan pengertian, sehingga ia tahu melakukan segala macam pekerjaan untuk mendirikan tempat kudus, tepat menurut yang diperintahkan TUHAN."', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 36, 2, 'Lalu Musa memanggil Bezaleel dan Aholiab dan setiap orang yang ahli, yang dalam hatinya telah ditanam TUHAN keahlian, setiap orang yang tergerak hatinya untuk datang melakukan pekerjaan itu.', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 36, 3, 'Mereka menerima dari pada Musa seluruh persembahan khusus, yang telah dibawa oleh orang Israel untuk melaksanakan pekerjaan mendirikan tempat kudus. Tetapi orang Israel itu masih terus membawa pemberian sukarela kepada Musa tiap-tiap pagi.', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 36, 4, 'Dan segala orang ahli yang melakukan seluruh pekerjaan untuk tempat kudus itu, datanglah masing-masing dari pekerjaan yang dilakukannya,', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 36, 5, 'dan berkata kepada Musa: "Rakyat membawa lebih banyak dari yang diperlukan untuk mengerjakan pekerjaan yang diperintahkan TUHAN untuk dilakukan."', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 36, 6, 'Lalu Musa memerintahkan, supaya dimaklumkan di mana-mana di perkemahan itu, demikian: "Tidak usah lagi ada orang laki-laki atau perempuan yang membuat sesuatu menjadi persembahan khusus bagi tempat kudus." Demikianlah rakyat itu dicegah membawa persembahan lagi.', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 36, 7, 'Sebab bahan yang diperlukan mereka telah cukup untuk melakukan segala pekerjaan itu, bahkan berlebih.', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 36, 8, 'Lalu semua ahli di antara tukang-tukang itu membuat Kemah Suci dari sepuluh tenda dari lenan halus yang dipintal benangnya dan dari kain ungu tua, kain ungu muda dan kain kirmizi; dengan ada kerubnya, buatan ahli tenun, dibuat orang semuanya itu.', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 36, 9, 'Panjang tiap-tiap tenda dua puluh delapan hasta dan lebar tiap-tiap tenda empat hasta: semua tenda itu sama ukurannya.', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 36, 10, 'Lima dari tenda itu dirangkap menjadi satu, dan yang lima lagi juga dirangkap menjadi satu.', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 36, 11, 'Pada rangkapan yang pertama, di tepi satu tenda yang di ujung, dibuatlah sosok-sosok kain ungu tua dan demikian juga di tepi satu tenda yang paling ujung pada rangkapan yang kedua.', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 36, 12, 'Lima puluh sosok dibuat orang pada tenda yang pertama dan lima puluh sosok pada tenda yang di ujung pada rangkapan yang kedua, sehingga sosok-sosok itu tepat berhadapan satu sama lain.', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 36, 13, 'Dibuatlah lima puluh kaitan emas dan disambunglah tenda-tenda Kemah Suci, yang satu dengan yang lain, dengan memakai kaitan itu, sehingga menjadi satu.', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 36, 14, 'Dibuatlah tenda-tenda dari bulu kambing menjadi atap kemah yang menudungi Kemah Suci, sebelas tenda dibuat orang.', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 36, 15, 'Panjang tiap-tiap tenda tiga puluh hasta dan empat hasta lebarnya tiap-tiap tenda: yang sebelas tenda itu sama ukurannya.', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 36, 16, 'Disambunglah lima dari tenda itu dengan tersendiri dan enam dari tenda itu dengan tersendiri.', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 36, 17, 'Dibuatlah lima puluh sosok pada rangkapan yang pertama di tepi satu tenda yang di ujung, dan dibuat lima puluh sosok di tepi satu tenda pada rangkapan yang kedua.', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 36, 18, 'Dibuat oranglah lima puluh kaitan tembaga untuk menyambung tenda-tenda kemah itu, sehingga menjadi satu.', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 36, 19, 'Juga dibuatlah untuk kemah itu tudung dari kulit domba jantan yang diwarnai merah, dan tudung dari kulit lumba-lumba di atasnya lagi.', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 36, 20, 'Dibuat oranglah untuk Kemah Suci itu papan dari kayu penaga yang berdiri tegak,', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 36, 21, 'sepuluh hasta panjangnya satu papan dan satu setengah hasta lebarnya tiap-tiap papan.', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 36, 22, 'Tiap-tiap papan ada dua pasaknya yang disengkang satu sama lain; demikianlah diperbuat dengan segala papan Kemah Suci.', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 36, 23, 'Dibuat oranglah papan-papan untuk Kemah Suci, dua puluh papan pada sebelah selatan.', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 36, 24, 'Dan empat puluh alas perak dibuat orang di bawah kedua puluh papan itu, dua alas di bawah satu papan untuk kedua pasaknya, dan seterusnya dua alas di bawah setiap papan untuk kedua pasaknya.', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 36, 25, 'Juga dibuat orang untuk sisi yang kedua dari Kemah Suci, pada sebelah utara, dua puluh papan', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 36, 26, 'dengan empat puluh alas peraknya: dua alas di bawah satu papan dan seterusnya dua alas di bawah setiap papan.', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 36, 27, 'Untuk sisi belakang Kemah Suci, pada sebelah barat, dibuat oranglah enam papan.', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 36, 28, 'Dua papan dibuat orang untuk sudut Kemah Suci, di sisi belakang.', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 36, 29, 'Kedua papan itu kembar pasaknya di sebelah bawah dan seperti itu juga kembar pasaknya di sebelah atas, di dekat gelang yang satu itu, demikianlah dibuat orang dengan kedua papan yang untuk kedua sudutnya itu.', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 36, 30, 'Jadi ada delapan papan dengan alas peraknya: enam belas alas; dua-dua alas di bawah satu papan.', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 36, 31, 'Dibuatlah juga kayu lintang dari kayu penaga: lima untuk papan-papan pada sisi yang satu dari Kemah Suci,', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 36, 32, 'lima kayu lintang untuk papan-papan pada sisi yang kedua dari Kemah Suci, dan lima kayu lintang untuk papan-papan Kemah Suci yang merupakan sisi belakangnya, pada sebelah barat.', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 36, 33, 'Dibuat oranglah kayu lintang yang di tengah menjadi melintang terus di tengah-tengah papan-papan itu dari ujung ke ujung.', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 36, 34, 'Papan-papan itu disalut dengan emas, gelang-gelang itu dibuat dari emas sebagai tempat memasukkan kayu-kayu lintang itu, dan kayu-kayu lintang itu disalut dengan emas.', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 36, 35, 'Dibuatlah tabir itu dari kain ungu tua, dan kain ungu muda, kain kirmizi dan lenan halus yang dipintal benangnya; dibuat dengan ada kerubnya, buatan ahli tenun.', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 36, 36, 'Dibuat oranglah untuk itu empat tiang dari kayu penaga dan disalutlah itu dengan emas, dengan ada kaitannya dari emas, lagi dituanglah empat alas perak untuk tiang itu.', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 36, 37, 'Juga dibuat oranglah tirai untuk pintu kemah itu dari kain ungu tua, kain ungu muda, kain kirmizi dan lenan halus yang dipintal benangnya: tenunan yang berwarna-warna;', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 36, 38, 'dan kelima tiangnya dengan kaitan untuk tiang itu; disalutlah ujungnya dan penyambung-penyambungnya dengan emas, dan kelima alasnya itu adalah dari tembaga.', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 37, 1, 'Bezaleel membuat tabut itu dari kayu penaga, dua setengah hasta panjangnya, satu setengah hasta lebarnya, dan satu setengah hasta tingginya.', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 37, 2, 'Disalutnyalah itu dengan emas murni, dari dalam dan dari luar, dan dibuatnyalah bingkai emas sekelilingnya.', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 37, 3, 'Dituangnyalah empat gelang emas untuk tabut itu, pada keempat penjurunya, yaitu dua gelang pada rusuknya yang satu dan dua gelang pada rusuknya yang kedua.', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 37, 4, 'Dibuatnyalah kayu pengusung dari kayu penaga dan disalutnyalah itu dengan emas.', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 37, 5, 'Dan dimasukkannyalah kayu pengusung itu ke dalam gelang yang pada rusuk tabut itu, supaya tabut dapat diangkut.', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 37, 6, 'Dibuatnyalah tutup pendamaian dari emas murni, dua setengah hasta panjangnya dan satu setengah hasta lebarnya.', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 37, 7, 'Dibuatnyalah dua kerub dari emas, dari emas tempaan dibuatnya itu, pada kedua ujung tutup pendamaian itu,', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 37, 8, 'satu kerub pada ujung sebelah sini dan satu kerub pada ujung sebelah sana; seiras dengan tutup pendamaian itu dibuatnya kerub itu pada kedua ujungnya.', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 37, 9, 'Kerub-kerub itu mengembangkan kedua sayapnya ke atas, sayap-sayapnya menudungi tutup pendamaian itu dan mukanya menghadap kepada masing-masing; kepada tutup pendamaian itulah menghadap muka kerub-kerub itu.', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 37, 10, 'Dibuatnyalah meja itu dari kayu penaga, dua hasta panjangnya, sehasta lebarnya dan satu setengah hasta tingginya.', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 37, 11, 'Disalutnyalah itu dengan emas murni dan dibuatnya bingkai emas sekelilingnya.', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 37, 12, 'Dibuatnyalah sekelilingnya jalur pinggir yang setapak tangan lebarnya dan dibuatnya bingkai emas sekeliling jalur pinggirnya itu.', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 37, 13, 'Dituangnyalah untuk meja itu empat gelang emas dan dipasangnyalah gelang-gelang itu di keempat penjurunya, pada keempat kakinya.', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 37, 14, 'Dekat ke jalur pinggirnyalah gelang itu, yakni tempat memasukkan kayu pengusung, supaya meja itu dapat diangkut.', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 37, 15, 'Dibuatnyalah kayu pengusung itu dari kayu penaga dan disalutnya dengan emas, yaitu supaya meja itu dapat diangkut.', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 37, 16, 'Dan dibuatnyalah perkakas yang di atas meja itu, yakni pinggannya, cawannya, piala dan kendinya, yang dipakai untuk persembahan curahan, semuanya dari emas murni.', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 37, 17, 'Dibuatnyalah kandil itu dari emas murni; dari emas tempaan dibuatnya kandil itu, baik kakinya baik batangnya; kelopaknya?dengan tombolnya dan kembangnya?dibuat seiras dengan kandil itu.', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 37, 18, 'Ada enam cabang timbul dari sisinya: tiga cabang kandil itu dari sisi yang satu dan tiga cabang dari sisi yang lain.', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 37, 19, 'Tiga kelopak yang berupa bunga badam pada cabang yang satu?dengan tombol dan kembangnya?dan tiga kelopak yang serupa pada cabang yang lain?dengan tombol dan kembangnya?;demikian juga dibuat keenam cabang yang timbul dari kandil itu.', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 37, 20, 'Pada kandil itu sendiri ada empat kelopak berupa bunga badam?dengan tombolnya dan kembangnya.', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 37, 21, 'Juga ada satu tombol di bawah sepasang cabang yang pertama yang timbul dari kandil itu, dan satu tombol di bawah yang kedua, dan satu tombol di bawah yang ketiga; demikianlah juga dibuat keenam cabang yang timbul dari situ.', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 37, 22, 'Tombol dan cabang itu timbul dari kandil itu, dan semuanya itu dibuat dari sepotong emas tempaan yang murni.', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 37, 23, 'Dibuatnyalah pada kandil itu tujuh lampu dengan sepitnya dan penadahnya dari emas murni.', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 37, 24, 'Dari satu talenta emas murni dibuatnyalah kandil itu dengan segala perkakasnya.', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 37, 25, 'Dibuatnyalah mezbah pembakaran ukupan itu dari kayu penaga, sehasta panjangnya dan sehasta lebarnya, empat persegi, tetapi dua hasta tingginya; tanduk-tanduknya seiras dengan mezbah itu.', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 37, 26, 'Disalutnyalah itu dengan emas murni, bidang atasnya dan bidang-bidang sisinya sekelilingnya, serta tanduk-tanduknya. Dibuatnyalah bingkai emas sekelilingnya.', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 37, 27, 'Dibuatnyalah dua gelang emas untuk mezbah itu di bawah bingkainya, pada kedua rusuknya, pada kedua bidang sisinya, sebagai tempat memasukkan kayu pengusung, supaya dengan itu mezbah dapat diangkut.', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 37, 28, 'Dan dibuatnyalah kayu pengusung itu dari kayu penaga dan disalutnya dengan emas.', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 37, 29, 'Dan dibuatnyalah minyak urapan yang kudus itu dan ukupan murni dari wangi-wangian, seperti buatan seorang tukang campur rempah-rempah.', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 38, 1, 'Dibuatnyalah mezbah korban bakaran itu dari kayu penaga, lima hasta panjangnya dan lima hasta lebarnya, empat persegi, tetapi tiga hasta tingginya.', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 38, 2, 'Dibuatnyalah tanduk-tanduknya pada keempat sudutnya; tanduk-tanduknya itu dibuat seiras dengan mezbah itu dan disalutnya dengan tembaga.', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 38, 3, 'Dibuatnyalah segala perkakas mezbah itu, yakni kuali-kuali, sodok-sodok, bokor-bokor penyiraman, garpu-garpu dan perbaraan-perbaraan, semua perkakasnya itu dibuatnya dari tembaga.', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 38, 4, 'Dibuatnyalah untuk mezbah itu kisi-kisi, yakni jala-jala tembaga, di bawah jalur, mulai dari sebelah bawah sampai setengah tingginya.', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 38, 5, 'Dituangnyalah empat gelang pada keempat ujung kisi-kisi tembaga itu, yakni tempat memasukkan kayu pengusung.', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 38, 6, 'Dibuatnyalah kayu-kayu pengusung itu dari kayu penaga dan disalutnya dengan tembaga.', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 38, 7, 'Dan dimasukkannyalah kayu-kayu pengusung itu ke dalam gelang-gelang yang pada rusuk mezbah itu, supaya dengan itu mezbah dapat diangkut. Mezbah itu dibuatnya berongga dan dari papan.', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 38, 8, 'Dibuatnyalah bejana pembasuhan dan juga alasnya dari tembaga, dari cermin-cermin para pelayan perempuan yang melayani di depan pintu Kemah Pertemuan.', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 38, 9, 'Dibuatnyalah pelataran itu; pada sebelah selatan: layar pelataran itu dari lenan halus yang dipintal benangnya, seratus hasta panjangnya;', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 38, 10, 'kedua puluh tiang layar itu dengan kedua puluh alas tiang itu dari tembaga, tetapi kaitan-kaitan tiang itu dan penyambung-penyambungnya dari perak.', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 38, 11, 'Pada sebelah utara: seratus hasta; kedua puluh tiang layar itu dengan kedua puluh alas tiang itu dari tembaga, tetapi kaitan-kaitan tiang itu dan penyambung-penyambungnya dari perak.', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 38, 12, 'Pada sebelah barat: layar lima puluh hasta; dengan sepuluh tiangnya dan sepuluh alas tiang itu, dan kaitan-kaitan tiang itu serta penyambung-penyambungnya dari perak.', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 38, 13, 'Dan pada sebelah timur: lima puluh hasta,', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 38, 14, 'yakni layar lima belas hasta untuk sisi yang satu di samping pintu gerbang itu, dengan tiga tiangnya dan tiga alas tiang itu;', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 38, 15, 'dan juga untuk sisi yang kedua di samping pintu gerbang itu?sebelah-menyebelah pintu gerbang pelataran itu ada layar?lima belas hasta, dengan tiga tiangnya dan tiga alas tiang itu.', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 38, 16, 'Segala layar yang mengelilingi pelataran, adalah dari lenan halus yang dipintal benangnya.', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 38, 17, 'Alas-alas untuk tiang-tiang itu adalah dari tembaga, tetapi kaitan-kaitan tiang itu dan penyambung-penyambungnya dari perak, juga salut kepalanya dari perak. Dihubungkanlah dengan penyambung-penyambung dari perak segala tiang-tiang pelataran itu.', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 38, 18, 'Tirai pintu gerbang pelataran itu tenunan yang berwarna-warna dari kain ungu tua, kain ungu muda, kain kirmizi dan dari lenan halus yang dipintal benangnya; dua puluh hasta panjangnya, tetapi tingginya?yang juga lebar kain itu?adalah lima hasta, sama dengan tinggi layar pelataran itu.', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 38, 19, 'Keempat tiangnya dan keempat alas tiang itu dari tembaga; tetapi kaitan-kaitannya dari perak, dan juga salut kepalanya, serta penyambung-penyambungnya dari perak.', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 38, 20, 'Segala patok untuk Kemah Suci dan untuk pelataran itu, sekelilingnya, adalah dari tembaga.', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 38, 21, 'Inilah daftar biaya untuk mendirikan Kemah Suci, yakni Kemah Suci, tempat hukum Allah, yang disusun atas perintah Musa, oleh orang Lewi di bawah pimpinan Itamar, anak imam Harun.', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 38, 22, 'Bezaleel bin Uri bin Hur, dari suku Yehuda, membuat segala yang diperintahkan TUHAN kepada Musa,', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 38, 23, 'dan bersama-sama dengan dia turut Aholiab, anak Ahisamakh, dari suku Dan, seorang tukang dan ahli, seorang yang membuat tenunan yang berwarna-warna dari kain ungu tua, dari kain ungu muda, dari kain kirmizi dan dari lenan halus. ?', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 38, 24, 'Segala emas yang dipakai untuk segala pekerjaan mendirikan tempat kudus itu, yakni emas dari persembahan unjukan, ada dua puluh sembilan talenta dan tujuh ratus tiga puluh syikal, ditimbang menurut syikal kudus.', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 38, 25, 'Perak persembahan mereka yang didaftarkan dari antara jemaah itu ada seratus talenta dan seribu tujuh ratus tujuh puluh lima syikal, ditimbang menurut syikal kudus:', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 38, 26, 'sebeka seorang, yaitu setengah syikal, ditimbang menurut syikal kudus, untuk setiap orang yang termasuk orang-orang yang terdaftar, yang berumur dua puluh tahun ke atas, sejumlah enam ratus tiga ribu lima ratus lima puluh orang.', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 38, 27, 'Seratus talenta perak dipakai untuk menuang alas-alas tempat kudus dan alas-alas tiang tabir itu, seratus alas sesuai dengan seratus talenta itu, jadi satu talenta untuk satu alas.', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 38, 28, 'Dari yang seribu tujuh ratus tujuh puluh lima syikal itu dibuatnyalah kaitan-kaitan untuk tiang-tiang itu, disalutnyalah kepala tiang itu dan dihubungkannya tiang-tiang itu dengan penyambung-penyambun', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 38, 29, 'Tembaga dari persembahan unjukan itu ada tujuh puluh talenta dan dua ribu empat ratus syikal.', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 38, 30, 'Dari padanya dibuatnyalah alas-alas pintu Kemah Pertemuan, dan mezbah tembaga dengan kisi-kisi tembaganya, segala perkakas mezbah itu,', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 38, 31, 'alas-alas pelataran sekelilingnya, alas-alas pintu gerbang pelataran itu, segala patok Kemah Suci dan segala patok pelataran sekelilingnya.', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 39, 1, 'Dari kain ungu tua, kain ungu muda dan kain kirmizi dibuat merekalah pakaian jabatan yang dipakai apabila diselenggarakan kebaktian di tempat kudus; juga dibuat mereka pakaian-pakaian kudus untuk Harun, seperti yang diperintahkan TUHAN kepada Musa.', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 39, 2, 'Dibuatnyalah baju efod dari emas, kain ungu tua dan kain ungu muda, kain kirmizi dan lenan halus yang dipintal benangnya.', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 39, 3, 'Mereka menempa emas papan dan dipotong-potongnyalah itu menjadi benang emas, untuk dipakankan pada kain ungu tua, pada kain ungu muda, pada kain kirmizi dan pada lenan halus: buatan seorang ahli.', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 39, 4, 'Dibuat merekalah tutup bahu pada baju efod itu, yang disambung kepadanya, dikedua ujungnyalah baju efod itu disambung.', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 39, 5, 'Sabuk pengikat yang ada pada baju efod itu adalah seiras dan sama buatannya dengan baju efod itu, yakni dari emas, kain ungu tua, kain ungu muda, kain kirmizi dan lenan halus yang dipintal benangnya, seperti yang diperintahkan TUHAN kepada Musa.', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 39, 6, 'Dikerjakan merekalah permata krisopras, yakni dililit dengan ikat emas, diukirkan padanya nama para anak Israel, yang diukirkan seperti meterai.', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 39, 7, 'Ditaruhnyalah itu pada kedua tutup bahu baju efod sebagai permata peringatan untuk mengingat orang Israel, seperti yang diperintahkan TUHAN kepada Musa.', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 39, 8, 'Dibuatnyalah tutup dada, buatan seorang ahli. Buatannya sama dengan baju efod, yakni dari emas, kain ungu tua, kain ungu muda, kain kirmizi dan lenan halus yang dipintal benangnya.', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 39, 9, 'Empat persegi dibuatnya itu; lipat dua dibuat mereka tutup dada itu, sejengkal panjangnya dan sejengkal lebarnya.', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 39, 10, 'Ditatah merekalah itu dengan empat jajar permata: permata yaspis merah, krisolit, malakit, itulah jajar yang pertama;', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 39, 11, 'jajar yang kedua: permata batu darah, lazurit, yaspis hijau;', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 39, 12, 'jajar yang ketiga: permata ambar, akik, kecubung;', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 39, 13, 'jajar yang keempat: permata pirus, krisopras dan nefrit. Dililit dengan ikat emas, demikianlah permata-permata itu dalam tatahannya.', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 39, 14, 'Sesuai dengan nama para anak Israel, permata itu adalah dua belas banyaknya; dan pada tiap-tiap permata ada diukirkan seperti meterai, nama salah satu suku dari yang dua belas itu.', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 39, 15, 'Juga dibuat merekalah untuk tutup dada itu untai berpilin, yang buatannya sebagai tali berjalin, dari emas murni.', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 39, 16, 'Dibuat merekalah dua ikat emas dan dua gelang emas dan kedua gelang itu dipasang pada kedua ujung tutup dada.', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 39, 17, 'Dipasang merekalah kedua untai emas yang berjalin itu pada kedua gelang itu di ujung tutup dada.', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 39, 18, 'Kedua ujung lain dari kedua untai berjalin itu dipasang merekalah pada kedua ikat emas itu, demikianlah dipasang pada tutup bahu baju efod, di sebelah depannya.', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 39, 19, 'Dibuat merekalah dua gelang emas dan dibubuh pada kedua ujung tutup dada itu, pada pinggirnya yang sebelah dalam, yang berhadapan dengan baju efod.', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 39, 20, 'Juga dibuat merekalah dua gelang emas dan dipasang pada kedua tutup bahu baju efod, di sebelah bawah pada bagian depan, dekat ke tempat persambungannya, di sebelah atas sabuk baju efod.', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 39, 21, 'Kemudian diikatkan merekalah tutup dada itu dengan gelangnya kepada gelang baju efod dengan memakai tali ungu tua, sehingga tetap di atas sabuk baju efod, dan tutup dada itu tidak dapat bergeser dari baju efod?seperti yang diperintahkan TUHAN kepada Musa.', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 39, 22, 'Dibuatnyalah gamis baju efod, buatan tukang tenun, dari kain ungu tua seluruhnya.', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 39, 23, 'Leher gamis itu di tengah-tengahnya seperti leher baju zirah, lehernya itu mempunyai pinggir sekelilingnya, supaya jangan koyak.', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 39, 24, 'Dibuat merekalah pada ujung gamis itu buah delima dari kain ungu tua, kain ungu muda dan kain kirmizi, yang dipintal benangnya.', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 39, 25, 'Dibuat merekalah giring-giring dari emas murni dan ditaruhlah giring-giring itu di antara buah delima, pada ujung gamis itu, berselang-seling di antara buah delima itu,', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 39, 26, 'sehingga satu giring-giring dan satu buah delima selalu berselang-seling, pada sekeliling ujung gamis, yang dipakai apabila diselenggarakan kebaktian seperti yang diperintahkan TUHAN kepada Musa.', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 39, 27, 'Dibuat merekalah kemeja dari lenan halus, buatan tukang tenun, untuk Harun dan anak-anaknya,', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 39, 28, 'serban dari lenan halus, destar yang indah dari lenan halus, celana lenan dari lenan halus yang dipintal benangnya,', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 39, 29, 'dan ikat pinggang dari lenan halus yang dipintal benangnya, kain ungu tua, kain ungu muda dan kain kirmizi, dari tenunan yang berwarna-warna?seperti yang diperintahkan TUHAN kepada Musa.', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 39, 30, 'Dibuat merekalah patam, jamang yang kudus dari emas murni, dan pada jamang itu dituliskan tulisan, diukirkan seperti meterai: Kudus bagi TUHAN.', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 39, 31, 'Dipasang merekalah pada patam itu tali ungu tua untuk mengikatkan patam itu pada serbannya, di sebelah atas?seperti yang diperintahkan TUHAN kepada Musa.', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 39, 32, 'Demikianlah diselesaikan segala pekerjaan melengkapi Kemah Suci, yakni Kemah Pertemuan itu. Orang Israel telah melakukannya tepat seperti yang diperintahkan TUHAN kepada Musa, demikianlah mereka melakukannya.', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 39, 33, 'Dibawa merekalah Kemah Suci itu kepada Musa, yakni kemah dengan segala perabotannya: kaitannya, papannya, kayu lintangnya, tiangnya dan alasnya,', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 39, 34, 'tudung dari kulit domba jantan yang diwarnai merah, tudung dari kulit lumba-lumba, tabir penudung,', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 39, 35, 'tabut hukum Allah dengan kayu-kayu pengusungnya dan tutup pendamaian,', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 39, 36, 'meja, segala perkakasnya dan roti sajian,', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 39, 37, 'kandil dari emas murni, lampu-lampunya?lampu yang harus teratur di atasnya?dan segala perkakasnya, minyak untuk penerangan,', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 39, 38, 'mezbah dari emas, minyak urapan, ukupan dari wangi-wangian, tirai pintu kemah,', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 39, 39, 'mezbah tembaga dengan kisi-kisi tembaganya, kayu-kayu pengusungnya dan segala perkakasnya, bejana pembasuhan dengan alasnya,', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 39, 40, 'layar pelataran, tiangnya dan alasnya, dan tirai untuk pintu gerbang pelataran, talinya dan patoknya, segala perkakas untuk pekerjaan mendirikan Kemah Suci, yakni Kemah Pertemuan itu;', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 39, 41, 'pakaian jabatan yang dipakai apabila diselenggarakan kebaktian di tempat kudus, pakaian kudus untuk imam Harun, dan pakaian anak-anaknya untuk memegang jabatan imam.', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 39, 42, 'Tepat seperti yang diperintahkan TUHAN kepada Musa, demikianlah dilakukan orang Israel segala pekerjaan melengkapi itu.', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 39, 43, 'Dan Musa melihat segala pekerjaan itu, dan sesungguhnyalah, mereka telah melakukannya seperti yang diperintahkan TUHAN, demikianlah mereka melakukannya. Lalu Musa memberkati mereka.', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 40, 1, 'Berfirmanlah TUHAN kepada Musa:', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 40, 2, '"Pada hari yang pertama dari bulan yang pertama haruslah engkau mendirikan Kemah Suci, yakni Kemah Pertemuan itu.', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 40, 3, 'Kautempatkanlah di dalamnya tabut hukum dan kaupasanglah tabir sebagai penudung di depan tabut itu.', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 40, 4, 'Kaubawalah ke dalamnya meja dan taruhlah di atasnya perkakas menurut susunannya; kaubawalah ke dalamnya kandil dan kaupasang lampu-lampunya di atasnya.', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 40, 5, 'Kautaruhlah mezbah emas untuk membakar ukupan di depan tabut hukum. Kaugantungkanlah tirai pintu Kemah Suci.', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 40, 6, 'Kautaruhlah mezbah korban bakaran di depan pintu Kemah Suci, yakni Kemah Pertemuan itu.', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 40, 7, 'Kautaruhlah bejana pembasuhan di antara Kemah Pertemuan dan mezbah itu, lalu kautaruhlah air ke dalamnya.', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 40, 8, 'Haruslah kaubuat pelataran keliling dan kaugantungkanlah tirai pintu gerbang pelataran itu.', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 40, 9, 'Kemudian kauambillah minyak urapan dan kauurapilah Kemah Suci dengan segala yang ada di dalamnya; demikianlah harus engkau menguduskannya, dengan segala perabotannya, sehingga menjadi kudus.', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 40, 10, 'Juga kauurapilah mezbah korban bakaran itu dengan segala perkakasnya; demikianlah engkau harus menguduskan mezbah itu, sehingga mezbah itu maha kudus.', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 40, 11, 'Juga kauurapilah bejana pembasuhan itu dengan alasnya, dan demikianlah engkau harus menguduskannya.', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 40, 12, 'Kemudian kausuruhlah Harun dan anak-anaknya datang ke pintu Kemah Pertemuan dan kaubasuhlah mereka dengan air.', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 40, 13, 'Kaukenakanlah pakaian yang kudus kepada Harun, kauurapi dan kaukuduskanlah dia supaya ia memegang jabatan imam bagi-Ku.', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 40, 14, 'Juga anak-anaknya kausuruhlah mendekat dan kaukenakanlah kemeja kepada mereka.', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 40, 15, 'Urapilah mereka, seperti engkau mengurapi ayah mereka, supaya mereka memegang jabatan imam bagi-Ku; dan ini terjadi, supaya berdasarkan pengurapan itu mereka memegang jabatan imam untuk selama-lamanya turun-temurun."', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 40, 16, 'Dan Musa melakukan semuanya itu tepat seperti yang diperintahkan TUHAN kepadanya, demikianlah dilakukannya.', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 40, 17, 'Dan terjadilah dalam bulan yang pertama tahun yang kedua, pada tanggal satu bulan itu, maka didirikanlah Kemah Suci.', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 40, 18, 'Musa mendirikan Kemah Suci itu, dipasangnyalah alas-alasnya, ditaruhnya papan-papannya, dipasangnya kayu-kayu lintangnya dan didirikannya tiang-tiangnya.', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 40, 19, 'Dikembangkannyalah atap kemah yang menudungi Kemah Suci dan diletakkannyalah tudung kemah di atasnya?seperti yang diperintahkan TUHAN kepada Musa.', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 40, 20, 'Diambilnyalah loh hukum Allah dan ditaruhnya ke dalam tabut, dikenakannyalah kayu pengusung pada tabut itu dan diletakkannya tutup pendamaian di atas tabut itu.', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 40, 21, 'Dibawanyalah tabut itu ke dalam Kemah Suci, digantungkannyalah tabir penudung dan dipasangnya sebagai penudung di depan tabut hukum Allah?seperti yang diperintahkan TUHAN kepada Musa.', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 40, 22, 'Ditaruhnyalah meja di dalam Kemah Pertemuan pada sisi Kemah Suci sebelah utara, di depan tabir itu.', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 40, 23, 'Diletakkannyalah di atasnya roti sajian menurut susunannya, di hadapan TUHAN?seperti yang diperintahkan TUHAN kepada Musa.', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 40, 24, 'Ditempatkannyalah kandil di dalam Kemah Pertemuan berhadapan dengan meja itu, pada sisi Kemah Suci sebelah selatan.', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 40, 25, 'Dipasangnyalah lampu-lampu di atasnya di hadapan TUHAN?seperti yang diperintahkan TUHAN kepada Musa.', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 40, 26, 'Ditempatkannyalah mezbah emas di dalam Kemah Pertemuan di depan tabir itu.', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 40, 27, 'Dibakarnyalah di atasnya ukupan dari wangi-wangian seperti yang diperintahkan TUHAN kepada Musa.', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 40, 28, 'Digantungkannyalah tirai pintu Kemah Suci.', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 40, 29, 'Mezbah korban bakaran ditempatkannyalah di depan pintu Kemah Suci, yakni Kemah Pertemuan itu, dan dipersembahkannyalah di atasnya korban bakaran dan korban sajian?seperti yang diperintahkan TUHAN kepada Musa.', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 40, 30, 'Ditempatkannyalah bejana pembasuhan di antara Kemah Pertemuan dan mezbah itu, lalu ditaruhnyalah air ke dalamnya untuk pembasuhan.', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 40, 31, 'Musa dan Harun serta anak-anaknya membasuh tangan dan kaki mereka dengan air dari dalamnya.', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 40, 32, 'Apabila mereka masuk ke dalam Kemah Pertemuan dan apabila mereka datang mendekat kepada mezbah itu, maka mereka membasuh kaki dan tangan?seperti yang diperintahkan TUHAN kepada Musa.', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 40, 33, 'Didirikannyalah tiang-tiang pelataran sekeliling Kemah Suci dan mezbah itu, dan digantungkannyalah tirai pintu gerbang pelataran itu. Demikianlah diselesaikan Musa pekerjaan itu.', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 40, 34, 'Lalu awan itu menutupi Kemah Pertemuan, dan kemuliaan TUHAN memenuhi Kemah Suci,', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 40, 35, 'sehingga Musa tidak dapat memasuki Kemah Pertemuan, sebab awan itu hinggap di atas kemah itu, dan kemuliaan TUHAN memenuhi Kemah Suci.', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 40, 36, 'Apabila awan itu naik dari atas Kemah Suci, berangkatlah orang Israel dari setiap tempat mereka berkemah.', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 40, 37, 'Tetapi jika awan itu tidak naik, maka merekapun tidak berangkat sampai hari awan itu naik.', 'id', 'TB'),
  ('2', 'kel', 'Keluaran', 40, 38, 'Sebab awan TUHAN itu ada di atas Kemah Suci pada siang hari, dan pada malam hari ada api di dalamnya, di depan mata seluruh umat Israel pada setiap tempat mereka berkemah.', 'id', 'TB'),
  ('3', 'im', 'Imamat', 1, 1, 'TUHAN memanggil Musa dan berfirman kepadanya dari dalam Kemah Pertemuan:', 'id', 'TB'),
  ('3', 'im', 'Imamat', 1, 2, '"Berbicaralah kepada orang Israel dan katakan kepada mereka: Apabila seseorang di antaramu hendak mempersembahkan persembahan kepada TUHAN, haruslah persembahanmu yang kamu persembahkan itu dari ternak, yakni dari lembu sapi atau dari kambing domba.', 'id', 'TB'),
  ('3', 'im', 'Imamat', 1, 3, 'Jikalau persembahannya merupakan korban bakaran dari lembu, haruslah ia mempersembahkan seekor jantan yang tidak bercela. Ia harus membawanya ke pintu Kemah Pertemuan, supaya TUHAN berkenan akan dia.', 'id', 'TB'),
  ('3', 'im', 'Imamat', 1, 4, 'Lalu ia harus meletakkan tangannya ke atas kepala korban bakaran itu, sehingga baginya persembahan itu diperkenan untuk mengadakan pendamaian baginya.', 'id', 'TB'),
  ('3', 'im', 'Imamat', 1, 5, 'Kemudian haruslah ia menyembelih lembu itu di hadapan TUHAN, dan anak-anak Harun, imam-imam itu, harus mempersembahkan darah lembu itu dan menyiramkannya pada sekeliling mezbah yang di depan pintu Kemah Pertemuan.', 'id', 'TB'),
  ('3', 'im', 'Imamat', 1, 6, 'Kemudian haruslah ia menguliti korban bakaran itu dan memotong-motongnya menurut bagian-bagian tertentu.', 'id', 'TB'),
  ('3', 'im', 'Imamat', 1, 7, 'Anak-anak imam Harun haruslah menaruh api di atas mezbah dan menyusun kayu di atas api itu.', 'id', 'TB'),
  ('3', 'im', 'Imamat', 1, 8, 'Dan mereka harus mengatur potongan-potongan korban itu dan kepala serta lemaknya di atas kayu yang sedang menyala di atas mezbah.', 'id', 'TB'),
  ('3', 'im', 'Imamat', 1, 9, 'Tetapi isi perutnya dan betisnya haruslah dibasuh dengan air dan seluruhnya itu harus dibakar oleh imam di atas mezbah sebagai korban bakaran, sebagai korban api-apian yang baunya menyenangkan bagi TUHAN.', 'id', 'TB'),
  ('3', 'im', 'Imamat', 1, 10, 'Jikalau persembahannya untuk korban bakaran adalah dari kambing domba, baik dari domba, maupun dari kambing, haruslah ia mempersembahkan seekor jantan yang tidak bercela.', 'id', 'TB'),
  ('3', 'im', 'Imamat', 1, 11, 'Haruslah ia menyembelihnya pada sisi mezbah sebelah utara di hadapan TUHAN, lalu haruslah anak-anak Harun, imam-imam itu, menyiramkan darahnya pada mezbah sekelilingnya.', 'id', 'TB'),
  ('3', 'im', 'Imamat', 1, 12, 'Kemudian haruslah ia memotong-motongnya menurut bagian-bagian tertentu, dan bersama-sama kepalanya dan lemaknya diaturlah semuanya itu oleh imam di atas kayu yang sedang menyala di atas mezbah.', 'id', 'TB'),
  ('3', 'im', 'Imamat', 1, 13, 'Isi perut dan betisnya haruslah dibasuhnya dengan air, dan seluruhnya itu haruslah dipersembahkan oleh imam dan dibakar di atas mezbah: itulah korban bakaran, suatu korban api-apian yang baunya menyenangkan bagi TUHAN.', 'id', 'TB'),
  ('3', 'im', 'Imamat', 1, 14, 'Jikalau persembahannya kepada TUHAN merupakan korban bakaran dari burung, haruslah ia mempersembahkan korbannya itu dari burung tekukur atau dari anak burung merpati.', 'id', 'TB'),
  ('3', 'im', 'Imamat', 1, 15, 'Imam harus membawanya ke mezbah, lalu memulas kepalanya dan membakarnya di atas mezbah. Darahnya harus ditekan ke luar pada dinding mezbah.', 'id', 'TB'),
  ('3', 'im', 'Imamat', 1, 16, 'Temboloknya serta dengan bulunya haruslah disisihkan dan dibuang ke samping mezbah sebelah timur, ke tempat abu.', 'id', 'TB'),
  ('3', 'im', 'Imamat', 1, 17, 'Dan ia harus mencabik burung itu pada pangkal sayapnya, tetapi tidak sampai terpisah; lalu imam harus membakarnya di atas mezbah, di atas kayu yang sedang terbakar; itulah korban bakaran, suatu korban api-apian yang baunya menyenangkan bagi TUHAN."', 'id', 'TB'),
  ('3', 'im', 'Imamat', 2, 1, '"Apabila seseorang hendak mempersembahkan persembahan berupa korban sajian kepada TUHAN, hendaklah persembahannya itu tepung yang terbaik dan ia harus menuangkan minyak serta membubuhkan kemenyan ke atasnya.', 'id', 'TB'),
  ('3', 'im', 'Imamat', 2, 2, 'Lalu korban itu harus dibawanya kepada anak-anak Harun, imam-imam itu. Setelah diambil dari korban itu tepung segenggam dengan minyak beserta seluruh kemenyannya, maka imam haruslah membakar semuanya itu di atas mezbah sebagai bagian ingat-ingatan korban itu, sebagai korban api-apian yang baunya menyenangkan bagi TUHAN.', 'id', 'TB'),
  ('3', 'im', 'Imamat', 2, 3, 'Korban sajian selebihnya adalah teruntuk bagi Harun dan anak-anaknya, yakni bagian maha kudus dari segala korban api-apian TUHAN.', 'id', 'TB'),
  ('3', 'im', 'Imamat', 2, 4, 'Apabila engkau hendak mempersembahkan persembahan berupa korban sajian dari apa yang dibakar di dalam pembakaran roti, haruslah itu dari tepung yang terbaik, berupa roti bundar yang tidak beragi, yang diolah dengan minyak, atau roti tipis yang tidak beragi, yang diolesi dengan minyak.', 'id', 'TB'),
  ('3', 'im', 'Imamat', 2, 5, 'Jikalau persembahanmu merupakan korban sajian dari yang dipanggang di atas panggangan, haruslah itu dari tepung yang terbaik, diolah dengan minyak, berupa roti yang tidak beragi.', 'id', 'TB'),
  ('3', 'im', 'Imamat', 2, 6, 'Korban itu harus dipotong-potong, lalu kautuangkanlah minyak ke atasnya; itulah korban sajian.', 'id', 'TB'),
  ('3', 'im', 'Imamat', 2, 7, 'Jikalau persembahanmu merupakan korban sajian dari yang dimasak di dalam wajan, haruslah itu diolah dari tepung yang terbaik bersama-sama minyak.', 'id', 'TB'),
  ('3', 'im', 'Imamat', 2, 8, 'Maka korban sajian yang diolah menurut salah satu cara itu haruslah kaupersembahkan kepada TUHAN, yakni harus disampaikan kepada imam, yang membawanya ke mezbah.', 'id', 'TB'),
  ('3', 'im', 'Imamat', 2, 9, 'Kemudian imam harus mengkhususkan dari korban sajian itu bagian ingat-ingatannya lalu membakarnya di atas mezbah sebagai korban api-apian yang baunya menyenangkan bagi TUHAN.', 'id', 'TB'),
  ('3', 'im', 'Imamat', 2, 10, 'Korban sajian selebihnya adalah bagian Harun dan anak-anaknya, yakni bagian maha kudus dari segala korban api-apian TUHAN!', 'id', 'TB'),
  ('3', 'im', 'Imamat', 2, 11, 'Suatu korban sajian yang kamu persembahkan kepada TUHAN janganlah diolah beragi, karena dari ragi atau dari madu tidak boleh kamu membakar sesuatupun sebagai korban api-apian bagi TUHAN.', 'id', 'TB'),
  ('3', 'im', 'Imamat', 2, 12, 'Tetapi sebagai persembahan dari hasil pertama boleh kamu mempersembahkanny kepada TUHAN, hanya janganlah dibawa ke atas mezbah menjadi bau yang menyenangkan.', 'id', 'TB'),
  ('3', 'im', 'Imamat', 2, 13, 'Dan tiap-tiap persembahanmu yang berupa korban sajian haruslah kaububuhi garam, janganlah kaulalaikan garam perjanjian Allahmu dari korban sajianmu; beserta segala persembahanmu haruslah kaupersembahkan garam.', 'id', 'TB'),
  ('3', 'im', 'Imamat', 2, 14, 'Jikalau engkau hendak mempersembahkan korban sajian dari hulu hasil kepada TUHAN, haruslah engkau mempersembahkan bulir gandum yang dipanggang di atas api, emping gandum baru, sebagai korban sajian dari hulu hasil gandummu.', 'id', 'TB'),
  ('3', 'im', 'Imamat', 2, 15, 'Haruslah kaububuh minyak dan kautaruh kemenyan ke atasnya; itulah korban sajian.', 'id', 'TB'),
  ('3', 'im', 'Imamat', 2, 16, 'Haruslah imam membakar sebagai ingat-ingatannya, sebagian dari emping gandumnya dan minyaknya beserta seluruh kemenyannya sebagai korban api-apian bagi TUHAN."', 'id', 'TB'),
  ('3', 'im', 'Imamat', 3, 1, '"Jikalau persembahannya merupakan korban keselamatan, maka jikalau yang dipersembahkannya itu dari lembu, seekor jantan atau seekor betina, haruslah ia membawa yang tidak bercela ke hadapan TUHAN.', 'id', 'TB'),
  ('3', 'im', 'Imamat', 3, 2, 'Lalu ia harus meletakkan tangannya di atas kepala persembahannya itu, dan menyembelihnya di depan pintu Kemah Pertemuan, lalu anak-anak Harun, imam-imam itu haruslah menyiramkan darahnya pada mezbah sekelilingnya.', 'id', 'TB'),
  ('3', 'im', 'Imamat', 3, 3, 'Kemudian dari korban keselamatan itu ia harus mempersembahkan lemak yang menyelubungi isi perut, dan segala lemak yang melekat pada isi perut itu sebagai korban api-apian bagi TUHAN,', 'id', 'TB'),
  ('3', 'im', 'Imamat', 3, 4, 'dan lagi kedua buah pinggang dan lemak yang melekat padanya, yang ada pada pinggang dan umbai hati yang harus dipisahkannya beserta buah pinggang itu.', 'id', 'TB'),
  ('3', 'im', 'Imamat', 3, 5, 'Anak-anak Harun harus membakarnya di atas mezbah, yakni di atas korban bakaran yang sedang dibakar di atas api, sebagai korban api-apian yang baunya menyenangkan bagi TUHAN.', 'id', 'TB'),
  ('3', 'im', 'Imamat', 3, 6, 'Jikalau persembahannya untuk korban keselamatan bagi TUHAN adalah dari kambing domba, seekor jantan atau seekor betina, haruslah ia mempersembahkan yang tidak bercela.', 'id', 'TB'),
  ('3', 'im', 'Imamat', 3, 7, 'Jikalau ia mempersembahkan seekor domba sebagai persembahannya, ia harus membawanya ke hadapan TUHAN.', 'id', 'TB'),
  ('3', 'im', 'Imamat', 3, 8, 'Lalu ia harus meletakkan tangannya ke atas kepala persembahannya itu dan menyembelihnya di depan Kemah Pertemuan, lalu anak-anak Harun harus menyiramkan darahnya pada mezbah sekelilingnya.', 'id', 'TB'),
  ('3', 'im', 'Imamat', 3, 9, 'Kemudian dari korban keselamatan itu ia harus mempersembahkan lemaknya sebagai korban api-apian bagi TUHAN, yakni segenap ekornya yang berlemak yang harus dipotong dekat pada tulang belakang, dan lemak yang menyelubungi isi perut, dan segala lemak yang melekat pada isi perut itu,', 'id', 'TB'),
  ('3', 'im', 'Imamat', 3, 10, 'dan lagi kedua buah pinggang dan lemak yang melekat padanya, yang ada pada pinggang, dan umbai hati yang harus dipisahkannya beserta buah pinggang itu.', 'id', 'TB'),
  ('3', 'im', 'Imamat', 3, 11, 'Imam harus membakarnya di atas mezbah sebagai santapan berupa korban api-apian bagi TUHAN.', 'id', 'TB'),
  ('3', 'im', 'Imamat', 3, 12, 'Jikalau persembahannya seekor kambing, ia harus membawanya ke hadapan TUHAN.', 'id', 'TB'),
  ('3', 'im', 'Imamat', 3, 13, 'Lalu ia harus meletakkan tangannya di atas kepala kambing itu dan menyembelihnya di depan Kemah Pertemuan, lalu anak-anak Harun harus menyiramkan darahnya pada mezbah sekelilingnya.', 'id', 'TB'),
  ('3', 'im', 'Imamat', 3, 14, 'Kemudian dari kambing itu ia harus mempersembahkan lemak yang menyelubungi isi perut, dan segala lemak yang melekat pada isi perut itu sebagai persembahannya berupa korban api-apian bagi TUHAN,', 'id', 'TB'),
  ('3', 'im', 'Imamat', 3, 15, 'dan lagi kedua buah pinggang dan lemak yang melekat padanya, yang ada pada pinggang dan umbai hati yang harus dipisahkannya beserta buah pinggang itu.', 'id', 'TB'),
  ('3', 'im', 'Imamat', 3, 16, 'Imam harus membakar semuanya itu di atas mezbah sebagai santapan berupa korban api-apian menjadi bau yang menyenangkan. Segala lemak adalah kepunyaan TUHAN.', 'id', 'TB'),
  ('3', 'im', 'Imamat', 5, 13, 'Dengan demikian imam mengadakan pendamaian bagi orang itu karena dosanya dalam salah satu perkara itu, sehingga ia menerima pengampunan. Selebihnya adalah bagian imam, sama seperti korban sajian."', 'id', 'TB'),
  ('3', 'im', 'Imamat', 5, 14, 'TUHAN berfirman kepada Musa:', 'id', 'TB'),
  ('3', 'im', 'Imamat', 5, 15, '"Apabila seseorang berubah setia dan tidak sengaja berbuat dosa dalam sesuatu hal kudus yang dipersembahkan kepada TUHAN, maka haruslah ia mempersembahkan kepada TUHAN sebagai tebusan salahnya seekor domba jantan yang tidak bercela dari kambing domba, dinilai menurut syikal perak, yakni menurut syikal kudus, menjadi korban penebus salah.', 'id', 'TB'),
  ('3', 'im', 'Imamat', 5, 16, 'Hal kudus yang menyebabkan orang itu berdosa, haruslah dibayar gantinya dengan menambah seperlima, lalu menyerahkannya kepada imam. Imam harus mengadakan pendamaian bagi orang itu dengan domba jantan korban penebus salah itu, sehingga ia menerima pengampunan.', 'id', 'TB'),
  ('3', 'im', 'Imamat', 5, 17, 'Jikalau seseorang berbuat dosa dengan melakukan salah satu hal yang dilarang TUHAN tanpa mengetahuinya, maka ia bersalah dan harus menanggung kesalahannya sendiri.', 'id', 'TB'),
  ('3', 'im', 'Imamat', 5, 18, 'Haruslah ia membawa kepada imam seekor domba jantan yang tidak bercela dari kambing domba, yang sudah dinilai, sebagai korban penebus salah. Imam itu haruslah mengadakan pendamaian bagi orang itu karena perbuatan yang tidak disengajanya dan yang tidak diketahuinya itu, sehingga ia menerima pengampunan.', 'id', 'TB'),
  ('3', 'im', 'Imamat', 6, 7, 'Imam harus mengadakan pendamaian bagi orang itu di hadapan TUHAN, sehingga ia menerima pengampunan atas perkara apapun yang diperbuatnya sehingga ia bersalah."', 'id', 'TB'),
  ('3', 'im', 'Imamat', 6, 8, 'TUHAN berfirman kepada Musa:', 'id', 'TB'),
  ('3', 'im', 'Imamat', 6, 9, '"Perintahkanlah kepada Harun dan anak-anaknya: Inilah hukum tentang korban bakaran. Korban bakaran itu haruslah tinggal di atas perapian di atas mezbah semalam-malaman sampai pagi, dan api mezbah haruslah dipelihara menyala di atasnya.', 'id', 'TB'),
  ('3', 'im', 'Imamat', 6, 10, 'Imam haruslah mengenakan pakaian lenannya, dan mengenakan celana lenan untuk menutup auratnya. Lalu ia harus mengangkat abu yang ada di atas mezbah sesudah korban bakaran habis dimakan api, dan haruslah ia membuangnya di samping mezbah.', 'id', 'TB'),
  ('3', 'im', 'Imamat', 6, 11, 'Kemudian haruslah ia menanggalkan pakaiannya dan mengenakan pakaian lain, lalu membawa abu itu ke luar perkemahan ke suatu tempat yang tahir.', 'id', 'TB'),
  ('3', 'im', 'Imamat', 6, 12, 'Api yang di atas mezbah itu harus dijaga supaya terus menyala, jangan dibiarkan padam. Tiap-tiap pagi imam harus menaruh kayu di atas mezbah, mengatur korban bakaran di atasnya dan membakar segala lemak korban keselamatan di sana.', 'id', 'TB'),
  ('3', 'im', 'Imamat', 6, 18, 'Setiap laki-laki di antara anak-anak Harun haruslah memakannya; itulah suatu ketetapan untuk selamanya bagi kamu turun-temurun; itulah bagianmu dari segala korban api-apian TUHAN. Setiap orang yang kena kepada korban-korban itu menjadi kudus."', 'id', 'TB'),
  ('3', 'im', 'Imamat', 6, 19, 'TUHAN berfirman kepada Musa:', 'id', 'TB'),
  ('3', 'im', 'Imamat', 6, 20, '"Inilah persembahan Harun dan anak-anaknya, yang harus dipersembahkan oleh mereka kepada TUHAN pada hari ia diurapi: sepersepuluh efa tepung yang terbaik sebagai korban sajian yang tetap, setengahnya pada waktu pagi dan setengahnya pada waktu petang.', 'id', 'TB'),
  ('3', 'im', 'Imamat', 6, 21, 'Haruslah itu diolah di atas panggangan bersama-sama minyak, setelah teraduk haruslah engkau membawanya dan mempersembahkannya sebagai korban sajian, sesudah dibakar dan berpotong-potong sebagai bau yang menyenangkan bagi TUHAN.', 'id', 'TB'),
  ('3', 'im', 'Imamat', 6, 22, 'Dan imam dari antara anak-anaknya yang diurapi sebagai penggantinya, haruslah mengolahnya; itulah suatu ketetapan untuk selamanya. Seluruhnya haruslah dibakar bagi TUHAN.', 'id', 'TB'),
  ('3', 'im', 'Imamat', 6, 23, 'Tiap-tiap korban sajian dari seorang imam itu haruslah menjadi korban yang terbakar seluruhnya, janganlah dimakan."', 'id', 'TB'),
  ('3', 'im', 'Imamat', 6, 24, 'TUHAN berfirman kepada Musa, demikian:', 'id', 'TB'),
  ('3', 'im', 'Imamat', 6, 25, '"Katakanlah kepada Harun dan anak-anaknya: Inilah hukum tentang korban penghapus dosa. Di tempat korban bakaran disembelih, di situlah harus disembelih korban penghapus dosa di hadapan TUHAN. Itulah persembahan maha kudus.', 'id', 'TB'),
  ('3', 'im', 'Imamat', 6, 26, 'Imam yang mempersembahkan korban penghapus dosa itulah yang harus memakannya; haruslah itu dimakan di suatu tempat yang kudus, di pelataran Kemah Pertemuan.', 'id', 'TB'),
  ('3', 'im', 'Imamat', 6, 27, 'Setiap orang yang kena kepada daging korban itu menjadi kudus, dan bila darahnya ada yang tepercik kepada sesuatu pakaian, haruslah engkau mencuci pakaian itu di suatu tempat yang kudus.', 'id', 'TB'),
  ('3', 'im', 'Imamat', 6, 28, 'Dan belanga tanah, tempat korban itu dimasak, haruslah dipecahkan, dan jikalau dimasak di dalam belanga tembaga, haruslah belanga itu digosok dan dibasuh dengan air.', 'id', 'TB'),
  ('3', 'im', 'Imamat', 6, 29, 'Setiap laki-laki di antara para imam haruslah memakannya; itulah persembahan maha kudus.', 'id', 'TB'),
  ('3', 'im', 'Imamat', 6, 30, 'Tetapi setiap korban penghapus dosa, yang dari darahnya dibawa sebagian ke dalam Kemah Pertemuan untuk mengadakan pendamaian di dalam tempat kudus, janganlah dimakan, melainkan dibakar habis dengan api."', 'id', 'TB'),
  ('3', 'im', 'Imamat', 7, 1, '"Inilah hukum tentang korban penebus salah. Korban itu ialah persembahan maha kudus.', 'id', 'TB'),
  ('3', 'im', 'Imamat', 7, 2, 'Di tempat orang menyembelih korban bakaran, di situlah harus disembelih korban penebus salah, dan darahnya haruslah disiramkan pada mezbah itu sekelilingnya.', 'id', 'TB'),
  ('3', 'im', 'Imamat', 7, 3, 'Segala lemak dari korban itu haruslah dipersembahkan, yakni ekornya yang berlemak dan lemak yang menutupi isi perut,', 'id', 'TB'),
  ('3', 'im', 'Imamat', 7, 4, 'dan lagi kedua buah pinggang dan lemak yang melekat padanya, yang ada pada pinggang, dan umbai hati yang harus dipisahkan beserta buah pinggang itu.', 'id', 'TB'),
  ('3', 'im', 'Imamat', 7, 5, 'Haruslah imam membakar semuanya itu di atas mezbah sebagai korban api-apian bagi TUHAN; itulah korban penebus salah.', 'id', 'TB'),
  ('3', 'im', 'Imamat', 7, 6, 'Setiap laki-laki di antara para imam haruslah memakannya; haruslah itu dimakan di suatu tempat yang kudus; itulah bagian maha kudus.', 'id', 'TB'),
  ('3', 'im', 'Imamat', 7, 7, 'Seperti halnya dengan korban penghapus dosa, demikian juga halnya dengan korban penebus salah; satu hukum berlaku atas keduanya: imam yang mengadakan pendamaian dengan korban itu, bagi dialah korban itu.', 'id', 'TB'),
  ('3', 'im', 'Imamat', 7, 8, 'Imam yang mempersembahkan korban bakaran seseorang, bagi dia juga kulit korban bakaran yang dipersembahkannya itu.', 'id', 'TB'),
  ('3', 'im', 'Imamat', 7, 9, 'Tiap-tiap korban sajian yang dibakar di dalam pembakaran roti, dan segala yang diolah di dalam wajan dan di atas panggangan adalah bagi imam yang mempersembahkannya.', 'id', 'TB'),
  ('3', 'im', 'Imamat', 7, 10, 'Tiap-tiap korban sajian yang diolah dengan minyak atau yang kering adalah bagi semua anak-anak Harun, semuanya dapat bagian."', 'id', 'TB'),
  ('3', 'im', 'Imamat', 7, 11, '"Inilah hukum tentang korban keselamatan, yang harus dipersembahkan orang kepada TUHAN.', 'id', 'TB'),
  ('3', 'im', 'Imamat', 7, 12, 'Jikalau ia mempersembahkannya untuk memberi syukur, haruslah beserta korban syukur itu dipersembahkannya roti bundar yang tidak beragi yang diolah dengan minyak, dan roti tipis yang tidak beragi yang diolesi dengan minyak, serta roti bundar dari tepung yang terbaik yang teraduk, yang diolah dengan minyak.', 'id', 'TB'),
  ('3', 'im', 'Imamat', 7, 13, 'Ia harus mempersembahkan persembahannya itu beserta dengan roti bundar yang beragi, di samping korban syukur yang menjadi korban keselamatannya.', 'id', 'TB'),
  ('3', 'im', 'Imamat', 7, 14, 'Dan dari padanya, yakni dari setiap bagian persembahan itu haruslah dipersembahkannya satu roti sebagai persembahan khusus bagi TUHAN. Persembahan itu adalah bagian imam yang menyiramkan darah korban keselamatan.', 'id', 'TB'),
  ('3', 'im', 'Imamat', 7, 15, 'Dan daging korban syukur yang menjadi korban keselamatannya itu haruslah dimakan pada hari dipersembahkannya itu. Sedikitpun dari padanya janganlah ditinggalkan sampai pagi.', 'id', 'TB'),
  ('3', 'im', 'Imamat', 7, 16, 'Jikalau korban sembelihan yang dipersembahkan itu merupakan korban nazar atau korban sukarela, haruslah itu dimakan pada hari mempersembahkannya dan yang selebihnya boleh juga dimakan pada keesokan harinya.', 'id', 'TB'),
  ('3', 'im', 'Imamat', 7, 17, 'Tetapi apa yang masih tinggal dari daging korban sembelihan itu sampai hari yang ketiga, haruslah dibakar habis dengan api.', 'id', 'TB'),
  ('3', 'im', 'Imamat', 7, 18, 'Karena jikalau pada hari yang ketiga masih dimakan dari daging korban keselamatan itu, maka TUHAN tidak berkenan akan orang yang mempersembahkannya dan korban itu dianggap batal baginya, bahkan menjadi sesuatu yang jijik, dan orang yang memakannya harus menanggung kesalahannya sendiri.', 'id', 'TB'),
  ('3', 'im', 'Imamat', 7, 19, 'Bila daging itu kena kepada sesuatu yang najis, janganlah dimakan, tetapi haruslah dibakar habis dengan api. Tiap-tiap orang yang tahir boleh memakan dari daging korban itu.', 'id', 'TB'),
  ('3', 'im', 'Imamat', 7, 20, 'Tetapi seseorang yang memakan daging dari korban keselamatan yang untuk TUHAN, sedang ia dalam keadaan najis, haruslah nyawa orang itu dilenyapkan dari antara bangsanya.', 'id', 'TB'),
  ('3', 'im', 'Imamat', 7, 21, 'Dan apabila seseorang kena kepada sesuatu yang najis, yakni kepada kenajisan berasal dari manusia, atau kepada hewan yang najis atau kepada setiap binatang yang merayap yang najis, lalu memakan dari pada daging korban keselamatan yang untuk TUHAN, maka haruslah nyawa orang itu dilenyapkan dari antara bangsanya."', 'id', 'TB'),
  ('3', 'im', 'Imamat', 7, 22, 'TUHAN berfirman kepada Musa:', 'id', 'TB'),
  ('3', 'im', 'Imamat', 7, 23, '"Katakanlah kepada orang Israel: Segala lemak dari lembu, domba ataupun kambing janganlah kamu makan.', 'id', 'TB'),
  ('3', 'im', 'Imamat', 7, 24, 'Lemak bangkai atau lemak binatang yang mati diterkam boleh dipergunakan untuk segala keperluan, tetapi jangan sekali-kali kamu memakannya.', 'id', 'TB'),
  ('3', 'im', 'Imamat', 7, 25, 'Karena setiap orang yang memakan lemak dari hewan yang dipergunakan untuk mempersembahkan korban api-apian bagi TUHAN, nyawa orang yang memakan itu, haruslah dilenyapkan dari antara bangsanya.', 'id', 'TB'),
  ('3', 'im', 'Imamat', 7, 26, 'Demikian juga janganlah kamu memakan darah apapun di segala tempat kediamanmu, baik darah burung-burung ataupun darah hewan.', 'id', 'TB'),
  ('3', 'im', 'Imamat', 7, 27, 'Setiap orang yang memakan darah apapun, nyawa orang itu haruslah dilenyapkan dari antara bangsanya."', 'id', 'TB'),
  ('3', 'im', 'Imamat', 7, 28, 'TUHAN berfirman kepada Musa, demikian:', 'id', 'TB'),
  ('3', 'im', 'Imamat', 7, 29, '"Katakanlah kepada orang Israel: Orang yang mempersembahkan korban keselamatannya kepada TUHAN, haruslah membawa kepada TUHAN sebagian dari korban keselamatannya itu sebagai persembahannya.', 'id', 'TB'),
  ('3', 'im', 'Imamat', 7, 30, 'Dengan tangannya sendirilah harus ia membawa segala korban api-apian TUHAN; adapun lemaknya, haruslah dibawanya beserta dadanya, supaya dadanya itu diunjukkan sebagai persembahan unjukan di hadapan TUHAN.', 'id', 'TB'),
  ('3', 'im', 'Imamat', 7, 31, 'Lalu haruslah imam membakar lemaknya di atas mezbah, tetapi dadanya itu adalah bagian Harun dan anak-anaknya.', 'id', 'TB'),
  ('3', 'im', 'Imamat', 7, 32, 'Paha kanannya harus kamu serahkan kepada imam sebagai persembahan khusus dari segala korban keselamatanmu.', 'id', 'TB'),
  ('3', 'im', 'Imamat', 7, 33, 'Siapa dari antara anak-anak Harun yang mempersembahkan darah dan lemak korban keselamatan, maka dialah yang harus mendapat paha kanan itu sebagai bagiannya.', 'id', 'TB'),
  ('3', 'im', 'Imamat', 7, 34, 'Karena dada persembahan unjukan dan paha persembahan khusus telah Kuambil dari orang Israel dari segala korban keselamatan mereka dan telah Kuberikan kepada imam Harun, dan kepada anak-anaknya; itulah suatu ketetapan yang berlaku bagi orang Israel untuk selamanya."', 'id', 'TB'),
  ('3', 'im', 'Imamat', 7, 35, 'Itulah bagian Harun dan bagian anak-anaknya dari segala korban api-apian TUHAN pada hari mereka itu disuruh datang untuk memegang jabatan imam bagi TUHAN;', 'id', 'TB'),
  ('3', 'im', 'Imamat', 7, 36, 'itulah yang harus diserahkan menurut perintah TUHAN dari pihak Israel kepada mereka pada hari mereka itu diurapi-Nya; itulah suatu ketetapan untuk selamanya bagi mereka turun-temurun.', 'id', 'TB'),
  ('3', 'im', 'Imamat', 7, 37, 'Itulah hukum tentang korban bakaran, korban sajian, korban penghapus dosa, korban penebus salah, persembahan pentahbisan dan korban keselamatan,', 'id', 'TB'),
  ('3', 'im', 'Imamat', 7, 38, 'yang diperintahkan TUHAN kepada Musa di atas gunung Sinai pada hari TUHAN memerintahkan kepada orang Israel mempersembahkan persembahan mereka kepada TUHAN di padang gurun Sinai.', 'id', 'TB'),
  ('3', 'im', 'Imamat', 8, 1, 'TUHAN berfirman kepada Musa:', 'id', 'TB'),
  ('3', 'im', 'Imamat', 8, 2, '"Panggillah Harun dan anak-anaknya bersama-sama dengan dia, dan ambillah pakaian-pakaian, minyak urapan, dan lembu jantan korban penghapus dosa, dua domba jantan dan bakul berisi roti yang tidak beragi,', 'id', 'TB'),
  ('3', 'im', 'Imamat', 8, 3, 'lalu suruhlah berkumpul segenap umat ke depan pintu Kemah Pertemuan."', 'id', 'TB'),
  ('3', 'im', 'Imamat', 8, 4, 'Musa melakukan seperti yang diperintahkan TUHAN kepadanya, lalu berkumpullah umat itu di depan Kemah Pertemuan.', 'id', 'TB'),
  ('3', 'im', 'Imamat', 8, 5, 'Berkatalah Musa kepada umat itu: "Inilah firman yang diperintahkan TUHAN untuk dilakukan."', 'id', 'TB'),
  ('3', 'im', 'Imamat', 8, 6, 'Lalu Musa menyuruh Harun dan anak-anaknya mendekat, dan dibasuhnyalah mereka dengan air.', 'id', 'TB'),
  ('3', 'im', 'Imamat', 8, 7, 'Sesudah itu dikenakannyalah kemeja kepadanya, diikatkannya ikat pinggang, dikenakannya gamis, dikenakannya baju efod, diikatkannya sabuk baju efod dan dikebatkannya sabuk itu kepadanya.', 'id', 'TB'),
  ('3', 'im', 'Imamat', 8, 8, 'Dikenakannyalah tutup dada kepadanya dan dibubuhnya di dalam tutup dada itu Urim dan Tumim.', 'id', 'TB'),
  ('3', 'im', 'Imamat', 8, 9, 'Kemudian ditaruhnyalah serban di kepalanya, dan di atas serban itu di sebelah depan ditaruhnyalah patam emas, yakni jamang yang kudus, seperti yang diperintahkan TUHAN kepada Musa.', 'id', 'TB'),
  ('3', 'im', 'Imamat', 8, 10, 'Musa mengambil minyak urapan, lalu diurapinyalah Kemah Suci serta segala yang ada di dalamnya dan dikuduskannya semuanya itu.', 'id', 'TB'),
  ('3', 'im', 'Imamat', 8, 11, 'Dipercikkannyalah sedikit dari minyak itu ke mezbah tujuh kali dan diurapinya mezbah itu serta segala perkakasnya, dan juga bejana pembasuhan serta alasnya untuk menguduskannya.', 'id', 'TB'),
  ('3', 'im', 'Imamat', 8, 12, 'Kemudian dituangkannya sedikit dari minyak urapan itu ke atas kepala Harun dan diurapinyalah dia untuk menguduskannya.', 'id', 'TB'),
  ('3', 'im', 'Imamat', 8, 13, 'Musa menyuruh anak-anak Harun mendekat, lalu dikenakannyalah kemeja kepada mereka, diikatkannya ikat pinggang dan dililitkannya destar, seperti yang diperintahkan TUHAN kepada Musa.', 'id', 'TB'),
  ('3', 'im', 'Imamat', 8, 14, 'Disuruhnyalah membawa lembu jantan korban penghapus dosa, lalu Harun dan anak-anaknya meletakkan tangannya ke atas kepala lembu jantan korban penghapus dosa itu.', 'id', 'TB'),
  ('3', 'im', 'Imamat', 8, 15, 'Lembu itu disembelih, lalu Musa mengambil darahnya, kemudian dengan jarinya dibubuhnyalah darah itu pada tanduk-tanduk mezbah sekelilingnya, dan dengan demikian disucikannyalah mezbah itu dari dosa; darah selebihnya dituangkannya pada bagian bawah mezbah. Dengan demikian dikuduskannya mezbah itu dan diadakannya pendamaian baginya.', 'id', 'TB'),
  ('3', 'im', 'Imamat', 8, 16, 'Diambillah segala lemak yang melekat pada isi perut, umbai hati, kedua buah pinggang serta lemaknya, lalu Musa membakarnya di atas mezbah.', 'id', 'TB'),
  ('3', 'im', 'Imamat', 8, 17, 'Tetapi lembu jantan itu dengan kulit, daging dan kotorannya dibakarnya habis di luar perkemahan, seperti yang diperintahkan TUHAN kepada Musa.', 'id', 'TB'),
  ('3', 'im', 'Imamat', 8, 18, 'Kemudian disuruhnya membawa domba jantan korban bakaran, lalu Harun dan anak-anaknya meletakkan tangannya ke atas kepala domba jantan itu.', 'id', 'TB'),
  ('3', 'im', 'Imamat', 8, 19, 'Domba itu disembelih, lalu Musa menyiramkan darahnya pada mezbah sekelilingnya.', 'id', 'TB'),
  ('3', 'im', 'Imamat', 8, 20, 'Domba itu dipotong-potong menurut bagian-bagian tertentu, lalu Musa membakar kepalanya dan bagian-bagiannya dan lemaknya.', 'id', 'TB'),
  ('3', 'im', 'Imamat', 8, 21, 'Tetapi isi perut dan betisnya dibasuh dengan air, lalu Musa membakar seluruh domba jantan itu di atas mezbah. Itulah korban bakaran, yang baunya menyenangkan; yakni suatu korban api-apian bagi TUHAN, seperti yang diperintahkan TUHAN kepada Musa.', 'id', 'TB'),
  ('3', 'im', 'Imamat', 8, 22, 'Kemudian disuruhnya membawa domba jantan yang lain, yakni domba persembahan pentahbisan, lalu Harun dan anak-anaknya meletakkan tangannya ke atas kepala domba jantan itu.', 'id', 'TB'),
  ('3', 'im', 'Imamat', 8, 23, 'Domba jantan itu disembelih, lalu Musa mengambil sedikit dari darahnya dan membubuhnya pada cuping telinga kanan Harun, pada ibu jari tangan kanan dan pada ibu jari kaki kanannya.', 'id', 'TB'),
  ('3', 'im', 'Imamat', 8, 24, 'Musa menyuruh anak-anak Harun mendekat, lalu membubuh sedikit dari darah itu pada cuping telinga kanan mereka, pada ibu jari tangan kanan dan pada ibu jari kaki kanan mereka, lalu Musa menyiramkan darah selebihnya pada mezbah sekelilingnya.', 'id', 'TB'),
  ('3', 'im', 'Imamat', 8, 25, 'Diambilnyalah lemaknya, ekornya yang berlemak, segala lemaknya yang melekat pada isi perut, umbai hatinya, kedua buah pinggang serta lemaknya dan paha kanannya.', 'id', 'TB'),
  ('3', 'im', 'Imamat', 8, 26, 'Dan dari dalam bakul berisi roti yang tidak beragi, yang ada di hadapan TUHAN, diambilnyalah satu roti bundar yang tidak beragi, satu roti bundar yang diolah dengan minyak dan satu roti tipis, lalu diletakkannya di atas segala lemak dan di atas paha kanan itu,', 'id', 'TB'),
  ('3', 'im', 'Imamat', 8, 27, 'dan ditaruhnya seluruhnya di telapak tangan Harun dan di telapak tangan anak-anaknya, dan dipersembahkannya semuanya sebagai persembahan unjukan di hadapan TUHAN.', 'id', 'TB'),
  ('3', 'im', 'Imamat', 8, 28, 'Kemudian Musa mengambil semuanya dari telapak tangan mereka, lalu dibakarnya di atas mezbah, yaitu di atas korban bakaran. Itulah persembahan pentahbisan untuk menjadi bau yang menyenangkan; itulah suatu korban api-apian bagi TUHAN.', 'id', 'TB'),
  ('3', 'im', 'Imamat', 8, 29, 'Musa mengambil dada domba itu, dan mempersembahkannya sebagai persembahan unjukan di hadapan TUHAN. Itulah yang didapat Musa sebagai bagiannya dari domba jantan persembahan pentahbisan itu, seperti yang diperintahkan TUHAN kepada Musa.', 'id', 'TB'),
  ('3', 'im', 'Imamat', 8, 30, 'Dan lagi Musa mengambil sedikit dari minyak urapan dan dari darah yang di atas mezbah itu, lalu dipercikkannya kepada Harun, ke pakaiannya, dan juga kepada anak-anaknya dan ke pakaian anak-anaknya. Dengan demikian ditahbiskannyalah Harun, pakaiannya, dan juga anak-anaknya dan pakaian anak-anaknya.', 'id', 'TB'),
  ('3', 'im', 'Imamat', 8, 31, 'Berkatalah Musa kepada Harun dan kepada anak-anaknya: "Masaklah daging itu di depan pintu Kemah Pertemuan; di sanalah harus kamu memakannya dengan roti yang ada di dalam bakul untuk persembahan pentahbisan, seperti yang telah kuperintahkan dengan berkata: Harun dan anak-anaknya haruslah memakannya.', 'id', 'TB'),
  ('3', 'im', 'Imamat', 8, 32, 'Dan apa yang tinggal dari daging dan roti itu haruslah kamu bakar habis dengan api.', 'id', 'TB'),
  ('3', 'im', 'Imamat', 8, 33, 'Janganlah kamu pergi dari depan pintu Kemah Pertemuan selama tujuh hari, sampai kepada genapnya perayaan pentahbisan, karena perayaan pentahbisan akan berlangsung tujuh hari lamanya.', 'id', 'TB'),
  ('3', 'im', 'Imamat', 8, 34, 'Seperti yang diperbuat pada hari ini, demikian juga diperintahkan TUHAN kamu perbuat kelak untuk mengadakan pendamaian bagimu.', 'id', 'TB'),
  ('3', 'im', 'Imamat', 8, 35, 'Di depan pintu Kemah Pertemuan haruslah kamu tinggal siang malam tujuh hari lamanya, dan kamu harus lakukan kewajibanmu terhadap TUHAN dengan setia, supaya janganlah kamu mati, karena demikianlah diperintahkan kepadaku."', 'id', 'TB'),
  ('3', 'im', 'Imamat', 8, 36, 'Maka Harun dan anak-anaknya melakukan segala firman yang diperintahkan TUHAN dengan perantaraan Musa.', 'id', 'TB'),
  ('3', 'im', 'Imamat', 9, 1, 'Pada hari yang kedelapan Musa memanggil Harun serta anak-anaknya dan para tua-tua Israel,', 'id', 'TB'),
  ('3', 'im', 'Imamat', 9, 2, 'lalu berkatalah ia kepada Harun: "Ambillah bagimu sendiri seekor lembu muda, untuk korban penghapus dosa, dan seekor domba jantan untuk korban bakaran, kedua-duanya yang tidak bercela, kemudian persembahkanlah itu di hadapan TUHAN.', 'id', 'TB'),
  ('3', 'im', 'Imamat', 9, 3, 'Dan kepada orang Israel haruslah engkau berkata, begini: Ambillah seekor kambing jantan untuk korban penghapus dosa, dan seekor anak lembu dan seekor domba, masing-masing berumur setahun dan yang tidak bercela, untuk korban bakaran.', 'id', 'TB'),
  ('3', 'im', 'Imamat', 9, 4, 'Dan lagi seekor lembu dan seekor domba jantan untuk korban keselamatan, supaya dikorbankan di hadapan TUHAN, dan korban sajian yang diolah dengan minyak, karena pada hari ini TUHAN akan menampakkan diri kepadamu."', 'id', 'TB'),
  ('3', 'im', 'Imamat', 9, 5, 'Kemudian dibawa merekalah apa yang diperintahkan Musa ke Kemah Pertemuan, lalu mendekatlah segenap umat itu dan berdiri di hadapan TUHAN.', 'id', 'TB'),
  ('3', 'im', 'Imamat', 9, 6, 'Kata Musa: "Inilah firman yang diperintahkan TUHAN kamu perbuat, agar kemuliaan TUHAN tampak kepadamu."', 'id', 'TB'),
  ('3', 'im', 'Imamat', 9, 7, 'Kata Musa kepada Harun: "Datanglah mendekat kepada mezbah, olahlah korban penghapus dosa dan korban bakaranmu, dan adakanlah pendamaian bagimu sendiri dan bagi bangsa itu; sesudah itu olahlah persembahan bangsa itu dan adakanlah pendamaian bagi mereka, seperti yang diperintahkan TUHAN."', 'id', 'TB'),
  ('3', 'im', 'Imamat', 9, 8, 'Maka mendekatlah Harun kepada mezbah, dan disembelihnyalah anak lembu yang akan menjadi korban penghapus dosa baginya sendiri.', 'id', 'TB'),
  ('3', 'im', 'Imamat', 9, 9, 'Anak-anak Harun menyampaikan darah lembu itu kepadanya, dan Harun mencelupkan jarinya ke dalam darah itu dan membubuhnya pada tanduk-tanduk mezbah. Darah selebihnya dituangkannya pada bagian bawah mezbah.', 'id', 'TB'),
  ('3', 'im', 'Imamat', 9, 10, 'Lemak, buah pinggang dan umbai hati dari korban penghapus dosa itu dibakarnya di atas mezbah, seperti yang diperintahkan TUHAN kepada Musa.', 'id', 'TB'),
  ('3', 'im', 'Imamat', 9, 11, 'Tetapi daging dan kulitnya dibakarnya habis di luar perkemahan.', 'id', 'TB'),
  ('3', 'im', 'Imamat', 9, 12, 'Kemudian ia menyembelih korban bakaran, lalu anak-anak Harun menyerahkan darah korban itu kepadanya, maka Harun menyiramkannya pada mezbah sekelilingnya.', 'id', 'TB'),
  ('3', 'im', 'Imamat', 9, 13, 'Juga diserahkan merekalah kepadanya korban bakaran itu menurut bagian-bagian tertentu beserta dengan kepalanya, lalu dibakarnya di atas mezbah.', 'id', 'TB'),
  ('3', 'im', 'Imamat', 9, 14, 'Isi perut dan betisnya dibasuhnya dan dibakarnya dengan korban bakaran di atas mezbah.', 'id', 'TB'),
  ('3', 'im', 'Imamat', 9, 15, 'Sesudah itu dibawanya persembahan bangsa ke mezbah; diambilnyalah kambing jantan yang akan menjadi korban penghapus dosa yang bagi bangsa itu, lalu disembelihnya dan dipersembahkannya sebagai korban penghapus dosa seperti yang pertama.', 'id', 'TB'),
  ('3', 'im', 'Imamat', 9, 16, 'Kemudian dibawanyalah korban bakaran ke mezbah, dan diolahnya sesuai dengan peraturan.', 'id', 'TB'),
  ('3', 'im', 'Imamat', 9, 17, 'Selanjutnya dibawanyalah korban sajian dan diambilnya segenggam dari padanya, lalu dibakarnya di atas mezbah, di samping korban bakaran pada waktu pagi.', 'id', 'TB'),
  ('3', 'im', 'Imamat', 9, 18, 'Ia menyembelih juga lembu dan domba jantan yang akan menjadi korban keselamatan bagi bangsa itu, lalu anak-anak Harun menyerahkan darah korban itu kepadanya, maka Harun menyiramkannya pada mezbah sekelilingnya.', 'id', 'TB'),
  ('3', 'im', 'Imamat', 9, 19, 'Tetapi segala lemak dari lembu dan dari domba jantan itu, yakni ekor yang berlemak, lemak yang menutupi isi perut, buah pinggang dan umbai hati,', 'id', 'TB'),
  ('3', 'im', 'Imamat', 9, 20, 'segala lemak itu diletakkan mereka di atas dada kedua korban itu, lalu Harun membakar segala lemak itu di atas mezbah.', 'id', 'TB'),
  ('3', 'im', 'Imamat', 9, 21, 'Dada dan paha kanan itu dipersembahkan Harun sebagai persembahan unjukan di hadapan TUHAN, seperti yang diperintahkan Musa.', 'id', 'TB'),
  ('3', 'im', 'Imamat', 9, 22, 'Harun mengangkat kedua tangannya atas bangsa itu, lalu memberkati mereka, kemudian turunlah ia, setelah mempersembahkan korban penghapus dosa, korban bakaran dan korban keselamatan.', 'id', 'TB'),
  ('3', 'im', 'Imamat', 9, 23, 'Masuklah Musa dan Harun ke dalam Kemah Pertemuan. Setelah keluar, mereka memberkati bangsa itu, lalu tampaklah kemuliaan TUHAN kepada segenap bangsa itu.', 'id', 'TB'),
  ('3', 'im', 'Imamat', 9, 24, 'Dan keluarlah api dari hadapan TUHAN, lalu menghanguskan korban bakaran dan segala lemak di atas mezbah. Tatkala seluruh bangsa itu melihatnya, bersorak-sorailah mereka, lalu sujud menyembah.', 'id', 'TB'),
  ('3', 'im', 'Imamat', 10, 1, 'Kemudian anak-anak Harun, Nadab dan Abihu, masing-masing mengambil perbaraannya, membubuh api ke dalamnya serta menaruh ukupan di atas api itu. Dengan demikian mereka mempersembahkan ke hadapan TUHAN api yang asing yang tidak diperintahkan-Nya kepada mereka.', 'id', 'TB'),
  ('3', 'im', 'Imamat', 10, 2, 'Maka keluarlah api dari hadapan TUHAN, lalu menghanguskan keduanya, sehingga mati di hadapan TUHAN.', 'id', 'TB'),
  ('3', 'im', 'Imamat', 10, 3, 'Berkatalah Musa kepada Harun: "Inilah yang difirmankan TUHAN: Kepada orang yang karib kepada-Ku Kunyatakan kekudusan-Ku, dan di muka seluruh bangsa itu akan Kuperlihatkan kemuliaan-Ku." Dan Harun berdiam diri.', 'id', 'TB'),
  ('3', 'im', 'Imamat', 10, 4, 'Kemudian Musa memanggil Misael dan Elsafan, anak-anak Uziel, paman Harun, lalu berkatalah ia kepada mereka: "Datang ke mari, angkatlah saudara-saudaramu ini dari depan tempat kudus ke luar perkemahan."', 'id', 'TB'),
  ('3', 'im', 'Imamat', 10, 5, 'Mereka datang, dan mengangkat mayat keduanya, masih berpakaian kemeja, ke luar perkemahan, seperti yang dikatakan Musa.', 'id', 'TB'),
  ('3', 'im', 'Imamat', 10, 6, 'Kemudian berkatalah Musa kepada Harun dan kepada Eleazar dan Itamar, anak-anak Harun: "Janganlah kamu berkabung dan janganlah kamu berdukacita, supaya jangan kamu mati dan jangan TUHAN memurkai segenap umat ini, tetapi saudara-saudaramu, yaitu seluruh bangsa Israel, merekalah yang harus menangis karena api yang dinyalakan TUHAN itu.', 'id', 'TB'),
  ('3', 'im', 'Imamat', 10, 7, 'Janganlah kamu pergi dari depan pintu Kemah Pertemuan, supaya jangan kamu mati, karena minyak urapan TUHAN ada di atasmu." Mereka melakukan sesuai dengan perkataan Musa.', 'id', 'TB'),
  ('3', 'im', 'Imamat', 10, 8, 'TUHAN berfirman kepada Harun:', 'id', 'TB'),
  ('3', 'im', 'Imamat', 10, 9, '"Janganlah engkau minum anggur atau minuman keras, engkau serta anak-anakmu, bila kamu masuk ke dalam Kemah Pertemuan, supaya jangan kamu mati. Itulah suatu ketetapan untuk selamanya bagi kamu turun-temurun.', 'id', 'TB'),
  ('3', 'im', 'Imamat', 10, 10, 'Haruslah kamu dapat membedakan antara yang kudus dengan yang tidak kudus, antara yang najis dengan yang tidak najis,', 'id', 'TB'),
  ('3', 'im', 'Imamat', 10, 11, 'dan haruslah kamu dapat mengajarkan kepada orang Israel segala ketetapan yang telah difirmankan TUHAN kepada mereka dengan perantaraan Musa."', 'id', 'TB'),
  ('3', 'im', 'Imamat', 10, 12, 'Kemudian berkatalah Musa kepada Harun dan kepada Eleazar dan Itamar, anak-anak Harun yang tinggal itu: "Ambillah korban sajian yang tinggal dari segala korban api-apian TUHAN, dan makanlah itu sebagai roti yang tidak beragi di samping mezbah, karena itulah bagian maha kudus.', 'id', 'TB'),
  ('3', 'im', 'Imamat', 10, 13, 'Haruslah kamu memakannya di suatu tempat yang kudus, karena itulah ketetapan bagimu dan anak-anakmu dari segala korban api-apian TUHAN, sebab demikianlah diperintahkan kepadaku.', 'id', 'TB'),
  ('3', 'im', 'Imamat', 10, 14, 'Dada persembahan unjukan dan paha persembahan khusus itu haruslah kamu makan di suatu tempat yang tahir, engkau ini serta anak-anakmu laki-laki dan perempuan, karena semuanya diberikan sebagai ketetapan bagimu dan anak-anakmu dari segala korban keselamatan orang Israel.', 'id', 'TB'),
  ('3', 'im', 'Imamat', 10, 15, 'Paha persembahan khusus dan dada persembahan unjukan itu haruslah dibawa mereka ke tempat segala korban api-apian yang dari lemak itu, supaya dipersembahkan sebagai persembahan unjukan di hadapan TUHAN. Itulah suatu ketetapan untuk selamanya bagimu serta bagi anak-anakmu seperti yang diperintahkan TUHAN."', 'id', 'TB'),
  ('3', 'im', 'Imamat', 10, 16, 'Kemudian Musa mencari dengan teliti kambing jantan korban penghapus dosa itu, tetapi ternyata kambing itu sudah habis dibakar. Sebab itu dimarahinyalah Eleazar dan Itamar, anak-anak Harun yang tinggal itu, katanya:', 'id', 'TB'),
  ('3', 'im', 'Imamat', 10, 17, '"Mengapa tidak kamu makan korban penghapus dosa itu di tempat yang kudus? Bukankah itu sesuatu bagian maha kudus dan TUHAN memberikannya kepadamu, supaya kamu mengangkut kesalahan umat itu dan mengadakan pendamaian bagi mereka di hadapan TUHAN?', 'id', 'TB'),
  ('3', 'im', 'Imamat', 10, 18, 'Lihat, darahnya itu tidak dibawa masuk ke dalam tempat kudus; bukankah seharusnya kamu memakannya di tempat kudus, seperti yang telah kuperintahkan?"', 'id', 'TB'),
  ('3', 'im', 'Imamat', 10, 19, 'Lalu berkatalah Harun kepada Musa: "Memang benar, pada hari ini mereka telah mempersembahkan korban penghapus dosa dan korban bakaran mereka ke hadapan TUHAN, tetapi hal-hal seperti tadilah yang kualami. Jikalau pada hari ini aku memakan juga korban penghapus dosa, mungkinkah hal itu disetujui oleh TUHAN?"', 'id', 'TB'),
  ('3', 'im', 'Imamat', 10, 20, 'Ketika Musa mendengar itu, ia menyetujuinya.', 'id', 'TB'),
  ('3', 'im', 'Imamat', 11, 1, 'Lalu TUHAN berfirman kepada Musa dan Harun, kata-Nya kepada mereka:', 'id', 'TB'),
  ('3', 'im', 'Imamat', 11, 2, '"Katakanlah kepada orang Israel, begini: Inilah binatang-binatang yang boleh kamu makan dari segala binatang berkaki empat yang ada di atas bumi:', 'id', 'TB'),
  ('3', 'im', 'Imamat', 11, 3, 'setiap binatang yang berkuku belah, yaitu yang kukunya bersela panjang, dan yang memamah biak boleh kamu makan.', 'id', 'TB'),
  ('3', 'im', 'Imamat', 11, 4, 'Tetapi inilah yang tidak boleh kamu makan dari yang memamah biak atau dari yang berkuku belah: unta, karena memang memamah biak, tetapi tidak berkuku belah; haram itu bagimu.', 'id', 'TB'),
  ('3', 'im', 'Imamat', 11, 5, 'Juga pelanduk, karena memang memamah biak, tetapi tidak berkuku belah; haram itu bagimu.', 'id', 'TB'),
  ('3', 'im', 'Imamat', 11, 6, 'Juga kelinci, karena memang memamah biak, tetapi tidak berkuku belah, haram itu bagimu.', 'id', 'TB'),
  ('3', 'im', 'Imamat', 11, 7, 'Demikian juga babi hutan, karena memang berkuku belah, yaitu kukunya bersela panjang, tetapi tidak memamah biak; haram itu bagimu.', 'id', 'TB'),
  ('3', 'im', 'Imamat', 11, 8, 'Daging binatang-binatang itu janganlah kamu makan dan bangkainya janganlah kamu sentuh; haram semuanya itu bagimu.', 'id', 'TB'),
  ('3', 'im', 'Imamat', 11, 9, 'Inilah yang boleh kamu makan dari segala yang hidup di dalam air: segala yang bersirip dan bersisik di dalam air, di dalam lautan, dan di dalam sungai, itulah semuanya yang boleh kamu makan.', 'id', 'TB'),
  ('3', 'im', 'Imamat', 11, 10, 'Tetapi segala yang tidak bersirip atau bersisik di dalam lautan dan di dalam sungai, dari segala yang berkeriapan di dalam air dan dari segala makhluk hidup yang ada di dalam air, semuanya itu kejijikan bagimu.', 'id', 'TB'),
  ('3', 'im', 'Imamat', 11, 11, 'Sesungguhnya haruslah semuanya itu kejijikan bagimu; dagingnya janganlah kamu makan, dan bangkainya haruslah kamu jijikkan.', 'id', 'TB'),
  ('3', 'im', 'Imamat', 11, 12, 'Segala yang tidak bersirip dan tidak bersisik di dalam air, adalah kejijikan bagimu.', 'id', 'TB'),
  ('3', 'im', 'Imamat', 11, 13, 'Inilah yang harus kamu jijikkan dari burung-burung, janganlah dimakan, karena semuanya itu adalah kejijikan: burung rajawali, ering janggut dan elang laut;', 'id', 'TB'),
  ('3', 'im', 'Imamat', 11, 14, 'elang merah dan elang hitam menurut jenisnya;', 'id', 'TB'),
  ('3', 'im', 'Imamat', 11, 15, 'setiap burung gagak menurut jenisnya;', 'id', 'TB'),
  ('3', 'im', 'Imamat', 11, 16, 'burung unta, burung hantu, camar dan elang sikap menurut jenisnya;', 'id', 'TB'),
  ('3', 'im', 'Imamat', 11, 17, 'burung pungguk, burung dendang air dan burung hantu besar;', 'id', 'TB'),
  ('3', 'im', 'Imamat', 11, 18, 'burung hantu putih, burung undan, burung ering;', 'id', 'TB'),
  ('3', 'im', 'Imamat', 11, 19, 'burung ranggung, bangau menurut jenisnya, meragai dan kelelawar.', 'id', 'TB'),
  ('3', 'im', 'Imamat', 11, 20, 'Segala binatang yang merayap dan bersayap dan berjalan dengan keempat kakinya adalah kejijikan bagimu.', 'id', 'TB'),
  ('3', 'im', 'Imamat', 11, 21, 'Tetapi inilah yang boleh kamu makan dari segala binatang yang merayap dan bersayap dan yang berjalan dengan keempat kakinya, yaitu yang mempunyai paha di sebelah atas kakinya untuk melompat di atas tanah.', 'id', 'TB'),
  ('3', 'im', 'Imamat', 11, 22, 'Inilah yang boleh kamu makan dari antaranya: belalang-belalang menurut jenisnya, yaitu belalang-belalang gambar menurut jenisnya, belalang-belalang kunyit menurut jenisnya, dan belalang-belalang padi menurut jenisnya.', 'id', 'TB'),
  ('3', 'im', 'Imamat', 11, 23, 'Selainnya segala binatang yang merayap dan bersayap dan yang berkaki empat adalah kejijikan bagimu.', 'id', 'TB'),
  ('3', 'im', 'Imamat', 11, 24, 'Semua yang berikut akan menajiskan kamu?setiap orang yang kena kepada bangkainya, menjadi najis sampai matahari terbenam,', 'id', 'TB'),
  ('3', 'im', 'Imamat', 11, 25, 'dan setiap orang yang ada membawa dari bangkainya haruslah mencuci pakaiannya, dan ia menjadi najis sampai matahari terbenam?,', 'id', 'TB'),
  ('3', 'im', 'Imamat', 11, 26, 'yakni segala binatang yang berkuku belah, tetapi tidak bersela panjang, dan yang tidak memamah biak; haram semuanya itu bagimu dan setiap orang yang kena kepadanya, menjadi najis.', 'id', 'TB'),
  ('3', 'im', 'Imamat', 11, 27, 'Demikian juga segala yang berjalan dengan telapak kakinya di antara segala binatang yang berjalan dengan keempat kakinya, semuanya itu haram bagimu; setiap orang yang kena kepada bangkainya, menjadi najis sampai matahari terbenam.', 'id', 'TB'),
  ('3', 'im', 'Imamat', 11, 28, 'Dan siapa yang membawa bangkainya, haruslah mencuci pakaiannya dan ia menjadi najis sampai matahari terbenam. Haram semuanya itu bagimu.', 'id', 'TB'),
  ('3', 'im', 'Imamat', 11, 29, 'Inilah yang haram bagimu di antara segala binatang yang merayap dan berkeriapan di atas bumi: tikus buta, tikus, dan katak menurut jenisnya', 'id', 'TB'),
  ('3', 'im', 'Imamat', 11, 30, 'dan landak, biawak, dan bengkarung, siput dan bunglon.', 'id', 'TB'),
  ('3', 'im', 'Imamat', 11, 31, 'Itulah semuanya yang haram bagimu di antara segala binatang yang mengeriap. Setiap orang yang kena kepada binatang-binatang itu sesudah binatang-binatang itu mati, menjadi najis sampai matahari terbenam.', 'id', 'TB'),
  ('3', 'im', 'Imamat', 11, 32, 'Dan segala sesuatu menjadi najis, kalau seekor yang mati dari binatang-binatang itu jatuh ke atasnya: perkakas kayu apa saja atau pakaian atau kulit atau karung, setiap barang yang dipergunakan untuk sesuatu apapun, haruslah dimasukkan ke dalam air dan menjadi najis sampai matahari terbenam, kemudian menjadi tahir pula.', 'id', 'TB'),
  ('3', 'im', 'Imamat', 11, 33, 'Kalau seekor dari binatang-binatang itu jatuh ke dalam sesuatu belanga tanah, maka segala yang ada di dalamnya menjadi najis dan belanga itu harus kamu pecahkan.', 'id', 'TB'),
  ('3', 'im', 'Imamat', 11, 34, 'Dalam hal itu segala makanan yang boleh dimakan, kalau kena air dari belanga itu, menjadi najis, dan segala minuman yang boleh diminum dalam belanga seperti itu, menjadi najis.', 'id', 'TB'),
  ('3', 'im', 'Imamat', 11, 35, 'Kalau bangkai seekor dari binatang-binatang itu jatuh ke atas sesuatu benda, itu menjadi najis; pembakaran roti dan anglo haruslah diremukkan, karena semuanya itu najis dan haruslah najis juga bagimu;', 'id', 'TB'),
  ('3', 'im', 'Imamat', 11, 36, 'tetapi mata air atau sumur yang memuat air, tetap tahir, sedangkan siapa yang kena kepada bangkai binatang-binatang itu menjadi najis.', 'id', 'TB'),
  ('3', 'im', 'Imamat', 11, 37, 'Apabila bangkai seekor dari binatang-binatang itu jatuh ke atas benih apapun yang akan ditaburkan, maka benih itu tetap tahir.', 'id', 'TB'),
  ('3', 'im', 'Imamat', 11, 38, 'Tetapi apabila benih itu telah dibubuhi air, lalu ke atasnya jatuh bangkai seekor dari binatang-binatang itu, maka najislah benih itu bagimu.', 'id', 'TB'),
  ('3', 'im', 'Imamat', 11, 39, 'Apabila mati salah seekor binatang yang menjadi makanan bagimu, maka siapa yang kena kepada bangkainya menjadi najis sampai matahari terbenam.', 'id', 'TB'),
  ('3', 'im', 'Imamat', 11, 40, 'Dan siapa yang makan dari bangkainya itu, haruslah mencuci pakaiannya, dan ia menjadi najis sampai matahari terbenam; demikian juga siapa yang membawa bangkainya haruslah mencuci pakaiannya, dan ia menjadi najis sampai matahari terbenam.', 'id', 'TB'),
  ('3', 'im', 'Imamat', 11, 41, 'Segala binatang yang merayap dan berkeriapan di atas bumi, adalah kejijikan, janganlah dimakan.', 'id', 'TB'),
  ('3', 'im', 'Imamat', 11, 42, 'Segala yang merayap dengan perutnya dan segala yang berjalan dengan keempat kakinya, atau segala yang berkaki banyak, semua yang termasuk binatang yang merayap dan berkeriapan di atas bumi, janganlah kamu makan, karena semuanya itu adalah kejijikan.', 'id', 'TB'),
  ('3', 'im', 'Imamat', 11, 43, 'Janganlah kamu membuat dirimu jijik oleh setiap binatang yang merayap dan berkeriapan dan janganlah kamu menajiskan dirimu dengan semuanya itu, sehingga kamu menjadi najis karenanya.', 'id', 'TB'),
  ('3', 'im', 'Imamat', 11, 44, 'Sebab Akulah TUHAN, Allahmu, maka haruslah kamu menguduskan dirimu dan haruslah kamu kudus, sebab Aku ini kudus, dan janganlah kamu menajiskan dirimu dengan setiap binatang yang mengeriap dan merayap di atas bumi.', 'id', 'TB'),
  ('3', 'im', 'Imamat', 11, 45, 'Sebab Akulah TUHAN yang telah menuntun kamu keluar dari tanah Mesir, supaya menjadi Allahmu; jadilah kudus, sebab Aku ini kudus.', 'id', 'TB'),
  ('3', 'im', 'Imamat', 11, 46, 'Itulah hukum tentang binatang berkaki empat, burung-burung dan segala makhluk hidup yang bergerak di dalam air dan segala makhluk yang mengeriap di atas bumi,', 'id', 'TB'),
  ('3', 'im', 'Imamat', 11, 47, 'yakni untuk membedakan antara yang najis dengan yang tahir, antara binatang yang boleh dimakan dengan binatang yang tidak boleh dimakan."', 'id', 'TB'),
  ('3', 'im', 'Imamat', 12, 1, 'TUHAN berfirman kepada Musa, demikian:', 'id', 'TB'),
  ('3', 'im', 'Imamat', 12, 2, '"Katakanlah kepada orang Israel: Apabila seorang perempuan bersalin dan melahirkan anak laki-laki, maka najislah ia selama tujuh hari. Sama seperti pada hari-hari ia bercemar kain ia najis.', 'id', 'TB'),
  ('3', 'im', 'Imamat', 12, 3, 'Dan pada hari yang kedelapan haruslah dikerat daging kulit khatan anak itu.', 'id', 'TB'),
  ('3', 'im', 'Imamat', 12, 4, 'Selanjutnya tiga puluh tiga hari lamanya perempuan itu harus tinggal menantikan pentahiran dari darah nifas, tidak boleh ia kena kepada sesuatu apapun yang kudus dan tidak boleh ia masuk ke tempat kudus, sampai sudah genap hari-hari pentahirannya.', 'id', 'TB'),
  ('3', 'im', 'Imamat', 12, 5, 'Tetapi jikalau ia melahirkan anak perempuan, maka najislah ia selama dua minggu, sama seperti pada waktu ia bercemar kain; selanjutnya enam puluh enam hari lamanya ia harus tinggal menantikan pentahiran dari darah nifas.', 'id', 'TB'),
  ('3', 'im', 'Imamat', 12, 6, 'Bila sudah genap hari-hari pentahirannya, maka untuk anak laki-laki atau anak perempuan haruslah dibawanya seekor domba berumur setahun sebagai korban bakaran dan seekor anak burung merpati atau burung tekukur sebagai korban penghapus dosa ke pintu Kemah Pertemuan, dengan menyerahkannya kepada imam.', 'id', 'TB'),
  ('3', 'im', 'Imamat', 12, 7, 'Imam itu harus mempersembahkannya ke hadapan TUHAN dan mengadakan pendamaian bagi perempuan itu. Demikianlah perempuan itu ditahirkan dari leleran darahnya. Itulah hukum tentang perempuan yang melahirkan anak laki-laki atau anak perempuan.', 'id', 'TB'),
  ('3', 'im', 'Imamat', 12, 8, 'Tetapi jikalau ia tidak mampu untuk menyediakan seekor kambing atau domba, maka haruslah ia mengambil dua ekor burung tekukur atau dua ekor anak burung merpati, yang seekor sebagai korban bakaran dan yang seekor lagi sebagai korban penghapus dosa, dan imam itu harus mengadakan pendamaian bagi perempuan itu, maka tahirlah ia."', 'id', 'TB'),
  ('3', 'im', 'Imamat', 13, 1, 'TUHAN berfirman kepada Musa dan Harun:', 'id', 'TB'),
  ('3', 'im', 'Imamat', 13, 2, '"Apabila pada kulit badan seseorang ada bengkak atau bintil-bintil atau panau, yang mungkin menjadi penyakit kusta pada kulitnya, ia harus dibawa kepada imam Harun, atau kepada salah seorang dari antara anak-anaknya, imam-imam itu.', 'id', 'TB'),
  ('3', 'im', 'Imamat', 13, 3, 'Imam haruslah memeriksa penyakit pada kulit itu, dan kalau bulu di tempat penyakit itu sudah berubah menjadi putih, dan penyakit itu kelihatan lebih dalam dari kulit, maka itu penyakit kusta; kalau imam melihat hal itu, haruslah ia menyatakan orang itu najis.', 'id', 'TB'),
  ('3', 'im', 'Imamat', 13, 4, 'Tetapi jikalau yang ada pada kulitnya itu hanya panau putih dan tidak kelihatan lebih dalam dari kulit, dan bulunya tidak berubah menjadi putih, imam harus mengurung orang itu tujuh hari lamanya.', 'id', 'TB'),
  ('3', 'im', 'Imamat', 13, 5, 'Pada hari yang ketujuh haruslah imam memeriksa dia; bila menurut penglihatannya penyakit itu masih tetap dan tidak meluas pada kulit, imam harus mengurung dia tujuh hari lagi untuk kedua kalinya.', 'id', 'TB'),
  ('3', 'im', 'Imamat', 13, 6, 'Kemudian pada hari yang ketujuh haruslah imam memeriksa dia untuk kedua kalinya; bila penyakit itu menjadi pudar dan tidak meluas pada kulit, imam harus menyatakan dia tahir; itu hanya bintil-bintil. Orang itu harus mencuci pakaiannya dan ia menjadi tahir.', 'id', 'TB'),
  ('3', 'im', 'Imamat', 13, 7, 'Tetapi jikalau bintil-bintil itu memang meluas pada kulit, sesudah ia minta diperiksa oleh imam untuk dinyatakan tahir, haruslah ia minta diperiksa untuk kedua kalinya.', 'id', 'TB'),
  ('3', 'im', 'Imamat', 13, 8, 'Kalau menurut pemeriksaan imam bintil-bintil itu meluas pada kulit, imam harus menyatakan dia najis; itu penyakit kusta.', 'id', 'TB'),
  ('3', 'im', 'Imamat', 13, 9, 'Apabila seseorang kena kusta, ia harus dibawa kepada imam.', 'id', 'TB'),
  ('3', 'im', 'Imamat', 13, 10, 'Kalau menurut pemeriksaan imam pada kulitnya ada bengkak yang putih, yang mengubah bulunya menjadi putih, dan ada daging liar timbul pada bengkak itu,', 'id', 'TB'),
  ('3', 'im', 'Imamat', 13, 11, 'maka kusta idapanlah yang ada pada kulitnya. Imam harus menyatakan dia najis dengan tidak usah mengurung dia, karena orang itu memang sudah najis.', 'id', 'TB'),
  ('3', 'im', 'Imamat', 13, 12, 'Jikalau kusta itu timbul di mana-mana pada kulit, sehingga menutupi seluruh kulit orang sakit itu, dari kepala sampai kakinya, seberapa dapat dilihat oleh imam,', 'id', 'TB'),
  ('3', 'im', 'Imamat', 13, 13, 'dan kalau menurut pemeriksaannya kusta itu menutupi seluruh tubuh orang itu, maka ia harus dinyatakan tahir oleh imam; ia seluruhnya telah berubah menjadi putih, jadi ia tahir.', 'id', 'TB'),
  ('3', 'im', 'Imamat', 13, 14, 'Tetapi pada waktu ada tampak daging liar padanya, najislah ia.', 'id', 'TB'),
  ('3', 'im', 'Imamat', 13, 15, 'Kalau daging liar itu dilihat oleh imam, ia harus menyatakan orang itu najis, karena daging liar itu najis, dan itu penyakit kusta.', 'id', 'TB'),
  ('3', 'im', 'Imamat', 13, 16, 'Atau apabila daging liar itu susut dan berubah menjadi putih, haruslah orang itu datang kepada imam.', 'id', 'TB'),
  ('3', 'im', 'Imamat', 13, 17, 'Kalau menurut pemeriksaannya penyakit itu telah berubah menjadi putih, haruslah imam menyatakan orang itu tahir; memang ia tahir.', 'id', 'TB'),
  ('3', 'im', 'Imamat', 13, 18, 'Apabila pada kulit seseorang ada barah yang telah sembuh,', 'id', 'TB'),
  ('3', 'im', 'Imamat', 13, 19, 'tetapi di tempat barah itu timbul bengkak yang putih atau panau yang putih kemerah-merahan, haruslah orang itu minta diperiksa oleh imam.', 'id', 'TB'),
  ('3', 'im', 'Imamat', 13, 20, 'Kalau menurut pemeriksaannya panau itu kelihatan lebih dalam dari pada kulit dan bulunya telah berubah menjadi putih, maka imam harus menyatakan orang itu najis, karena penyakit kustalah yang timbul di dalam barah itu.', 'id', 'TB'),
  ('3', 'im', 'Imamat', 13, 21, 'Tetapi jikalau panau itu diperiksa oleh imam dan ternyata tidak ada bulu yang putih padanya, dan tidak lebih dalam dari pada kulit, malahan pudar, imam harus mengurung orang itu tujuh hari lamanya.', 'id', 'TB'),
  ('3', 'im', 'Imamat', 13, 22, 'Dan jikalau panau itu memang meluas pada kulit, imam harus menyatakan dia najis; itu penyakit kusta.', 'id', 'TB'),
  ('3', 'im', 'Imamat', 13, 23, 'Tetapi jikalau panau itu masih tetap dan tidak meluas, maka itu bekas barah, dan imam harus menyatakan orang itu tahir.', 'id', 'TB'),
  ('3', 'im', 'Imamat', 13, 24, 'Atau apabila pada kulit seseorang ada lecur karena api dan daging liar yang timbul pada lecur itu menjadi panau yang putih kemerah-merahan atau putih,', 'id', 'TB'),
  ('3', 'im', 'Imamat', 13, 25, 'maka imam harus memeriksa panau itu; bila ternyata bulu pada panau itu berubah menjadi putih dan panau itu kelihatan lebih dalam dari kulit, maka yang timbul di dalam lecur itu adalah penyakit kusta, dan imam harus menyatakan orang itu najis; itu penyakit kusta.', 'id', 'TB'),
  ('3', 'im', 'Imamat', 13, 26, 'Tetapi jikalau menurut pemeriksaannya tidak ada pada panau itu bulu yang putih dan panau itu tidak lebih dalam dari pada kulit, malahan pudar, imam harus mengurung orang itu tujuh hari lamanya.', 'id', 'TB'),
  ('3', 'im', 'Imamat', 13, 27, 'Pada hari yang ketujuh imam harus memeriksa lagi dia; jikalau panau itu memang meluas pada kulit, maka haruslah imam menyatakan dia najis, itu penyakit kusta.', 'id', 'TB'),
  ('3', 'im', 'Imamat', 13, 28, 'Tetapi jikalau panau itu masih tetap dan tidak meluas pada kulit, malahan pudar, maka itu bengkak lecur dan imam harus menyatakan dia tahir, sebab itu bekas lecur.', 'id', 'TB'),
  ('3', 'im', 'Imamat', 13, 29, 'Apabila seorang laki-laki atau perempuan mendapat penyakit pada kepala atau pada janggut,', 'id', 'TB'),
  ('3', 'im', 'Imamat', 13, 30, 'imam harus memeriksa penyakit itu; bila itu kelihatan lebih dalam dari kulit, dan ada padanya rambut halus yang kuning, maka imam harus menyatakan orang itu najis, karena itu kudis kepala, yakni kusta kepala atau kusta janggut.', 'id', 'TB'),
  ('3', 'im', 'Imamat', 13, 31, 'Dan apabila menurut pemeriksaannya penyakit kudis itu tidak kelihatan lebih dalam dari kulit dan tidak ada padanya rambut yang hitam, maka imam harus mengurung orang yang kena penyakit kudis itu tujuh hari lamanya.', 'id', 'TB'),
  ('3', 'im', 'Imamat', 13, 32, 'Pada hari yang ketujuh imam harus memeriksa penyakit itu; bila ternyata kudis itu tidak meluas dan tidak ada rambut yang kuning padanya, dan kudis itu tidak kelihatan lebih dalam dari kulit,', 'id', 'TB'),
  ('3', 'im', 'Imamat', 13, 33, 'maka orang itu harus bercukur, hanya tempat kudis itu tidak boleh dicukurnya. Lalu imam harus mengurung orang yang kena kudis itu untuk kedua kalinya tujuh hari lagi.', 'id', 'TB'),
  ('3', 'im', 'Imamat', 13, 34, 'Kemudian pada hari yang ketujuh imam harus memeriksa lagi kudis itu; bila ternyata, kudis itu tidak meluas pada kulit, dan tidak kelihatan lebih dalam dari kulit, maka imam harus menyatakan orang itu tahir, dan ia harus mencuci pakaiannya dan ia menjadi tahir.', 'id', 'TB'),
  ('3', 'im', 'Imamat', 13, 35, 'Tetapi jikalau kudis itu memang meluas pada kulit, sesudah ia dinyatakan tahir,', 'id', 'TB'),
  ('3', 'im', 'Imamat', 13, 36, 'dan menurut pemeriksaan imam kudis itu meluas pada kulit, maka imam tidak usah lagi mencari rambut yang kuning, memang orang itu najis.', 'id', 'TB'),
  ('3', 'im', 'Imamat', 13, 37, 'Tetapi jikalau menurut penglihatan imam kudis itu masih tetap, dan ada rambut hitam tumbuh pada kudis itu, maka kudis itu sudah sembuh, dan orang itu tahir, dan imam harus menyatakan dia tahir.', 'id', 'TB'),
  ('3', 'im', 'Imamat', 13, 38, 'Apabila pada kulit seorang laki-laki atau perempuan ada panau-panau, yakni panau-panau yang putih,', 'id', 'TB'),
  ('3', 'im', 'Imamat', 13, 39, 'imam harus melakukan pemeriksaan; bila ternyata pada kulitnya ada panau-panau pudar dan putih, maka hanya kuraplah yang timbul pada kulitnya dan orang itu tahir.', 'id', 'TB'),
  ('3', 'im', 'Imamat', 13, 40, 'Apabila rambut kepala seorang laki-laki meluruh, dan ia hanya menjadi botak, ia tahir.', 'id', 'TB'),
  ('3', 'im', 'Imamat', 13, 41, 'Jikalau rambutnya meluruh pada sebelah mukanya, dan ia menjadi botak sebelah depan, ia tahir.', 'id', 'TB'),
  ('3', 'im', 'Imamat', 13, 42, 'Tetapi apabila pada kepala yang botak itu, sebelah atas atau sebelah depan, ada penyakit yang putih kemerah-merahan, maka penyakit kustalah yang timbul pada bagian kepala yang botak itu.', 'id', 'TB'),
  ('3', 'im', 'Imamat', 13, 43, 'Lalu imam harus memeriksa dia; bila ternyata bahwa bengkak pada bagian kepala yang botak itu putih kemerah-merahan, dan kelihatannya seperti kusta pada kulit,', 'id', 'TB'),
  ('3', 'im', 'Imamat', 13, 44, 'maka orang itu sakit kusta, dan ia najis, dan imam harus menyatakan dia najis, karena penyakit yang di kepalanya itu.', 'id', 'TB'),
  ('3', 'im', 'Imamat', 13, 45, 'Orang yang sakit kusta harus berpakaian yang cabik-cabik, rambutnya terurai dan lagi ia harus menutupi mukanya sambil berseru-seru: Najis! Najis!', 'id', 'TB'),
  ('3', 'im', 'Imamat', 13, 46, 'Selama ia kena penyakit itu, ia tetap najis; memang ia najis; ia harus tinggal terasing, di luar perkemahan itulah tempat kediamannya.', 'id', 'TB'),
  ('3', 'im', 'Imamat', 13, 47, 'Apabila pada pakaian ada tanda kusta, pada pakaian bulu domba atau pakaian lenan,', 'id', 'TB'),
  ('3', 'im', 'Imamat', 13, 48, 'entah pada benang lungsin atau benang pakannya, entah pada kulit atau sesuatu barang kulit,', 'id', 'TB'),
  ('3', 'im', 'Imamat', 13, 49, '?kalau tanda pada barang-barang itu sudah kemerah-merahan warnanya, maka itu kusta?hal itu harus diperiksakan kepada imam.', 'id', 'TB'),
  ('3', 'im', 'Imamat', 13, 50, 'Kalau tanda itu telah diperiksa oleh imam, ia harus mengasingkan yang mempunyai tanda itu tujuh hari lamanya.', 'id', 'TB'),
  ('3', 'im', 'Imamat', 13, 51, 'Pada hari yang ketujuh ia harus memeriksa tanda itu lagi; apabila tanda itu meluas pada pakaian atau benang lungsin atau benang pakan atau pada kulit, entah untuk barang apapun kulit itu dipakai, maka itu adalah kusta yang jahat sekali, dan barang itu najis.', 'id', 'TB'),
  ('3', 'im', 'Imamat', 13, 52, 'Ia harus membakar barang-barang yang mempunyai tanda itu, karena itu kusta yang jahat sekali; barang-barang itu harus dibakar habis.', 'id', 'TB'),
  ('3', 'im', 'Imamat', 13, 53, 'Tetapi jikalau menurut pemeriksaan imam tanda itu tidak meluas pada barang-barang itu,', 'id', 'TB'),
  ('3', 'im', 'Imamat', 13, 54, 'maka imam harus memerintahkan orang mencuci barang yang mempunyai tanda itu, lalu ia harus mengasingkannya tujuh hari lagi untuk kedua kalinya.', 'id', 'TB'),
  ('3', 'im', 'Imamat', 13, 55, 'Kemudian sesudah barang itu dicuci, imam harus memeriksa tanda itu lagi; bila ternyata rupa tanda itu tidak berubah, biarpun itu tidak meluas, maka barang itu najis, dan engkau harus membakarnya habis, karena tanda itu semakin mendalam pada sebelah belakang atau sebelah muka.', 'id', 'TB'),
  ('3', 'im', 'Imamat', 13, 56, 'Dan jikalau menurut pemeriksaan imam tanda itu menjadi pudar sesudah dicuci, maka ia harus mengoyakkannya dari barang-barang itu.', 'id', 'TB'),
  ('3', 'im', 'Imamat', 13, 57, 'Tetapi jikalau tanda itu tampak pula pada barang-barang itu, maka itu kusta yang sedang timbul; barang yang mempunyai tanda itu, haruslah kaubakar habis.', 'id', 'TB'),
  ('3', 'im', 'Imamat', 13, 58, 'Tetapi barang-barang yang telah kaucuci, sehingga tanda itu lenyap dari padanya, haruslah dicuci untuk kedua kalinya, barulah menjadi tahir.', 'id', 'TB'),
  ('3', 'im', 'Imamat', 13, 59, 'Itulah hukum tentang kusta yang ada pada pakaian bulu domba atau lenan atau pada benang lungsin atau pada benang pakan atau pada setiap barang kulit, untuk menyatakan tahir atau najisnya."', 'id', 'TB'),
  ('3', 'im', 'Imamat', 14, 1, 'TUHAN berfirman kepada Musa:', 'id', 'TB'),
  ('3', 'im', 'Imamat', 14, 2, '"Inilah yang harus menjadi hukum tentang orang yang sakit kusta pada hari pentahirannya: ia harus dibawa kepada imam,', 'id', 'TB'),
  ('3', 'im', 'Imamat', 14, 3, 'dan imam harus pergi ke luar perkemahan; kalau menurut pemeriksaan imam penyakit kusta itu telah sembuh dari padanya,', 'id', 'TB'),
  ('3', 'im', 'Imamat', 14, 4, 'maka imam harus memerintahkan, supaya bagi orang yang akan ditahirkan itu diambil dua ekor burung yang hidup dan yang tidak haram, juga kayu aras, kain kirmizi dan hisop.', 'id', 'TB'),
  ('3', 'im', 'Imamat', 14, 5, 'Imam harus memerintahkan supaya burung yang seekor disembelih di atas belanga tanah berisi air mengalir.', 'id', 'TB'),
  ('3', 'im', 'Imamat', 14, 6, 'Tetapi burung yang masih hidup haruslah diambilnya bersama-sama dengan kayu aras, kain kirmizi dan hisop, lalu bersama-sama dengan burung itu semuanya harus dicelupkannya ke dalam darah burung yang sudah disembelih di atas air mengalir itu.', 'id', 'TB'),
  ('3', 'im', 'Imamat', 14, 7, 'Kemudian ia harus memercik tujuh kali kepada orang yang akan ditahirkan dari kusta itu dan dengan demikian mentahirkan dia, lalu burung yang hidup itu haruslah dilepaskannya ke padang.', 'id', 'TB'),
  ('3', 'im', 'Imamat', 14, 8, 'Orang yang akan ditahirkan itu haruslah mencuci pakaiannya, mencukur seluruh rambutnya dan membasuh tubuhnya dengan air, maka ia menjadi tahir. Sesudah itu ia boleh masuk ke dalam perkemahan, tetapi harus tinggal di luar kemahnya sendiri tujuh hari lamanya.', 'id', 'TB'),
  ('3', 'im', 'Imamat', 14, 9, 'Maka pada hari yang ketujuh ia harus mencukur seluruh rambutnya: rambut kepala, janggut, alis, bahkan segala bulunya harus dicukur, pakaiannya dicuci, dan tubuhnya dibasuh dengan air; maka ia menjadi tahir.', 'id', 'TB'),
  ('3', 'im', 'Imamat', 14, 10, 'Pada hari yang kedelapan ia harus mengambil dua ekor domba jantan yang tidak bercela dan seekor domba betina berumur setahun yang tidak bercela dan tiga persepuluh efa tepung yang terbaik diolah dengan minyak sebagai korban sajian, serta satu log minyak.', 'id', 'TB'),
  ('3', 'im', 'Imamat', 14, 11, 'Imam yang melakukan pentahiran itu harus menempatkan orang yang akan ditahirkan bersama-sama dengan persembahannya di hadapan TUHAN di depan pintu Kemah Pertemuan.', 'id', 'TB'),
  ('3', 'im', 'Imamat', 14, 12, 'Dan ia harus mengambil domba jantan yang seekor dan mempersembahkannya sebagai tebusan salah bersama-sama dengan minyak yang satu log itu, dan ia harus mempersembahkannya sebagai persembahan unjukan di hadapan TUHAN.', 'id', 'TB'),
  ('3', 'im', 'Imamat', 14, 13, 'Domba jantan itu harus disembelihnya di tempat orang menyembelih korban penghapus dosa dan korban bakaran, di tempat kudus, karena korban penebus salah, begitu juga korban penghapus dosa, adalah bagian imam; itulah bagian maha kudus.', 'id', 'TB'),
  ('3', 'im', 'Imamat', 14, 14, 'Imam harus mengambil sedikit dari darah tebusan salah itu dan harus membubuhnya pada cuping telinga kanan dari orang yang akan ditahirkan dan pada ibu jari tangan kanan dan pada ibu jari kaki kanannya.', 'id', 'TB'),
  ('3', 'im', 'Imamat', 14, 15, 'Imam harus mengambil sedikit dari minyak yang satu log itu dan menuangnya ke telapak tangan kiri imam sendiri;', 'id', 'TB'),
  ('3', 'im', 'Imamat', 14, 16, 'ia harus mencelupkan jari kanannya ke dalam minyak yang di telapak tangan kirinya itu dan sedikit dari minyak itu haruslah dipercikkannya dengan jarinya tujuh kali di hadapan TUHAN.', 'id', 'TB'),
  ('3', 'im', 'Imamat', 14, 17, 'Dari minyak selebihnya imam harus membubuh sedikit pada cuping telinga kanan orang itu, pada ibu jari tangan kanannya dan pada ibu jari kaki kanannya, di tempat mana darah tebusan salah dibubuhkan.', 'id', 'TB'),
  ('3', 'im', 'Imamat', 14, 18, 'Dan apa yang tinggal dari minyak itu haruslah dibubuhnya pada kepala orang yang akan ditahirkan. Dengan demikian imam mengadakan pendamaian bagi orang itu di hadapan TUHAN.', 'id', 'TB'),
  ('3', 'im', 'Imamat', 14, 19, 'Imam harus mempersembahkan korban penghapus dosa dan dengan demikian mengadakan pendamaian bagi orang yang akan ditahirkan dari kenajisannya, dan sesudah itu ia harus menyembelih korban bakaran.', 'id', 'TB'),
  ('3', 'im', 'Imamat', 14, 20, 'Kemudian imam harus mempersembahkan korban bakaran dan korban sajian di atas mezbah. Dengan demikian imam mengadakan pendamaian bagi orang itu, maka ia menjadi tahir.', 'id', 'TB'),
  ('3', 'im', 'Imamat', 14, 21, 'Tetapi jikalau orang itu miskin dan tidak mampu, ia harus mengambil domba jantan seekor saja sebagai tebusan salah untuk persembahan unjukan, supaya diadakan pendamaian bagi orang itu, juga sepersepuluh efa tepung yang terbaik diolah dengan minyak untuk korban sajian, dan satu log minyak.', 'id', 'TB'),
  ('3', 'im', 'Imamat', 14, 22, 'Dan lagi dua ekor burung tekukur atau dua ekor burung merpati sekadar kemampuannya, yang seekor harus menjadi korban penghapus dosa dan yang seekor lagi menjadi korban bakaran.', 'id', 'TB'),
  ('3', 'im', 'Imamat', 14, 23, 'Pada hari yang kedelapan ia harus membawa semuanya untuk pentahirannya kepada imam, ke depan pintu Kemah Pertemuan di hadapan TUHAN.', 'id', 'TB'),
  ('3', 'im', 'Imamat', 14, 24, 'Kemudian imam harus mengambil domba tebusan salah dan minyak yang satu log itu, lalu imam harus mempersembahkan semuanya sebagai persembahan unjukan di hadapan TUHAN.', 'id', 'TB'),
  ('3', 'im', 'Imamat', 14, 25, 'Ia harus menyembelih domba tebusan salah dan imam harus mengambil sedikit dari darah tebusan salah itu dan membubuhnya pada cuping telinga kanan orang itu dan pada ibu jari tangan kanan dan ibu jari kaki kanannya.', 'id', 'TB'),
  ('3', 'im', 'Imamat', 14, 26, 'Dan imam harus menuang sedikit dari minyak itu ke telapak tangan kirinya sendiri,', 'id', 'TB'),
  ('3', 'im', 'Imamat', 14, 27, 'lalu sedikit dari minyak itu haruslah dipercikkan oleh imam dengan jari kanannya tujuh kali di hadapan TUHAN.', 'id', 'TB'),
  ('3', 'im', 'Imamat', 14, 28, 'Kemudian imam harus membubuh sedikit dari minyak itu pada cuping telinga kanan dari orang yang akan ditahirkan, pada ibu jari tangan kanannya dan pada ibu jari kaki kanannya, di tempat mana dibubuhi darah tebusan salah itu.', 'id', 'TB'),
  ('3', 'im', 'Imamat', 14, 29, 'Dan minyak selebihnya haruslah dibubuhnya pada kepala orang yang akan ditahirkan, supaya diadakan pendamaian bagi orang itu di hadapan TUHAN.', 'id', 'TB'),
  ('3', 'im', 'Imamat', 14, 30, 'Lalu ia harus mempersembahkan seekor dari kedua burung tekukur atau anak burung merpati, yang dibawa orang itu sekadar kemampuannya,', 'id', 'TB'),
  ('3', 'im', 'Imamat', 14, 31, 'yang seekor sebagai korban penghapus dosa, dan yang seekor lagi sebagai korban bakaran, di samping korban sajian. Dengan demikian imam mengadakan pendamaian bagi orang yang akan ditahirkan di hadapan TUHAN.', 'id', 'TB'),
  ('3', 'im', 'Imamat', 14, 32, 'Itulah hukum tentang pentahiran seorang yang kena kusta yang tidak mampu."', 'id', 'TB'),
  ('3', 'im', 'Imamat', 14, 33, 'TUHAN berfirman kepada Musa dan Harun:', 'id', 'TB'),
  ('3', 'im', 'Imamat', 14, 34, '"Apabila kamu masuk ke tanah Kanaan yang akan Kuberikan kepadamu menjadi milikmu dan Aku mendatangkan tanda kusta di sebuah rumah di negeri milikmu itu,', 'id', 'TB'),
  ('3', 'im', 'Imamat', 14, 35, 'maka pemilik rumah itu harus datang memberitahukannya kepada imam: Ada kelihatan seperti tanda kusta di rumahku.', 'id', 'TB'),
  ('3', 'im', 'Imamat', 14, 36, 'Maka imam harus memerintahkan supaya rumah itu dikosongkan, sebelum ia datang memeriksa tanda kusta itu, supaya jangan menjadi najis segala yang ada di dalam rumah itu, dan sesudah itu barulah imam datang untuk memeriksanya.', 'id', 'TB'),
  ('3', 'im', 'Imamat', 14, 37, 'Kalau menurut pemeriksaannya tanda pada dinding rumah itu merupakan lekuk-lekuk yang kehijau-hijauan atau kemerah-merahan warnanya, yang kelihatan lebih dalam dari permukaan dinding itu,', 'id', 'TB'),
  ('3', 'im', 'Imamat', 14, 38, 'imam harus keluar dari rumah itu, lalu berdiri di depan pintu rumah, dan menutup rumah itu tujuh hari lamanya.', 'id', 'TB'),
  ('3', 'im', 'Imamat', 14, 39, 'Pada hari yang ketujuh imam harus datang kembali; kalau menurut pemeriksaannya tanda kusta itu meluas pada dinding rumah,', 'id', 'TB'),
  ('3', 'im', 'Imamat', 14, 40, 'maka imam harus memerintahkan supaya orang mengungkit batu-batu yang kena tanda itu dan membuangnya ke luar kota ke suatu tempat yang najis.', 'id', 'TB'),
  ('3', 'im', 'Imamat', 14, 41, 'Dan ia harus mengikis rumah itu sebelah dalam berkeliling, dan kikisan lepa itu haruslah ditumpahkan ke luar kota ke suatu tempat yang najis.', 'id', 'TB'),
  ('3', 'im', 'Imamat', 14, 42, 'Dan orang harus mengambil batu-batu lain, lalu memasangnya sebagai pengganti batu-batu tadi, dan harus mengambil lepa lain dan melepa rumah itu.', 'id', 'TB'),
  ('3', 'im', 'Imamat', 14, 43, 'Tetapi jikalau tanda itu timbul lagi di dalam rumah itu, sesudah batu-batunya diungkit dan sesudah rumah itu dikikis, bahkan sesudah dilepa lagi,', 'id', 'TB'),
  ('3', 'im', 'Imamat', 14, 44, 'dan kalau imam datang dan menurut pemeriksaannya tanda itu meluas di dalam rumah, maka kusta ganaslah yang di dalam rumah itu, dan rumah itu najis.', 'id', 'TB'),
  ('3', 'im', 'Imamat', 14, 45, 'Rumah itu haruslah dirombak, yakni batunya, kayunya dan segala lepa rumah itu, lalu dibawa semuanya ke luar kota ke suatu tempat yang najis.', 'id', 'TB'),
  ('3', 'im', 'Imamat', 14, 46, 'Dan orang yang masuk ke dalam rumah itu selama rumah itu ditutup, menjadi najis sampai matahari terbenam.', 'id', 'TB'),
  ('3', 'im', 'Imamat', 14, 47, 'Dan orang yang tidur di dalam rumah itu haruslah mencuci pakaiannya; demikian juga orang yang makan di dalam rumah itu haruslah mencuci pakaiannya.', 'id', 'TB'),
  ('3', 'im', 'Imamat', 14, 48, 'Tetapi jikalau imam datang dan menurut pemeriksaannya tanda itu tidak meluas di dalam rumah itu, sesudah dilepa, maka imam harus menyatakan rumah itu tahir, karena tanda itu telah hilang.', 'id', 'TB'),
  ('3', 'im', 'Imamat', 14, 49, 'Kemudian, untuk menyucikan rumah itu, haruslah ia mengambil dua ekor burung, kayu aras, kain kirmizi dan hisop.', 'id', 'TB'),
  ('3', 'im', 'Imamat', 14, 50, 'Burung yang seekor haruslah disembelihnya di atas belanga tanah berisi air mengalir.', 'id', 'TB'),
  ('3', 'im', 'Imamat', 14, 51, 'Lalu ia harus mengambil kayu aras dan hisop, kain kirmizi dan burung yang masih hidup itu, dan mencelupkan semuanya ke dalam darah burung yang sudah disembelih dan ke dalam air mengalir itu, kemudian ia harus memercik kepada rumah itu tujuh kali.', 'id', 'TB'),
  ('3', 'im', 'Imamat', 14, 52, 'Dengan demikian ia harus menyucikan rumah itu dengan darah burung, air mengalir, burung yang hidup, kayu aras, hisop, dan kain kirmizi.', 'id', 'TB'),
  ('3', 'im', 'Imamat', 14, 53, 'Dan burung yang hidup itu harus dilepaskannya ke luar kota ke padang. Dengan demikian ia mengadakan pendamaian bagi rumah itu, maka rumah itu menjadi tahir.', 'id', 'TB'),
  ('3', 'im', 'Imamat', 14, 54, 'Itulah hukum tentang setiap penyakit kusta, kudis kepala,', 'id', 'TB'),
  ('3', 'im', 'Imamat', 14, 55, 'tentang kusta pada pakaian dan rumah,', 'id', 'TB'),
  ('3', 'im', 'Imamat', 14, 56, 'tentang bengkak, bintil-bintil dan panau,', 'id', 'TB'),
  ('3', 'im', 'Imamat', 14, 57, 'untuk memberi petunjuk dalam hal najis atau dalam hal tahir; itulah hukum tentang kusta."', 'id', 'TB'),
  ('3', 'im', 'Imamat', 15, 1, 'TUHAN berfirman kepada Musa dan Harun:', 'id', 'TB'),
  ('3', 'im', 'Imamat', 15, 2, '"Berbicaralah kepada orang Israel dan katakan kepada mereka: Apabila aurat seorang laki-laki mengeluarkan lelehan, maka najislah ia karena lelehannya itu.', 'id', 'TB'),
  ('3', 'im', 'Imamat', 15, 3, 'Beginilah kenajisannya berhubung dengan lelehannya itu: bila auratnya membiarkan lelehan itu mengalir, atau bila auratnya menahannya, sehingga tidak mengeluarkan lelehan, maka itulah kenajisannya.', 'id', 'TB'),
  ('3', 'im', 'Imamat', 15, 4, 'Setiap tempat tidur, yang ditiduri orang yang mengeluarkan lelehan itu menjadi najis, dan setiap barang yang didudukinya menjadi najis juga.', 'id', 'TB'),
  ('3', 'im', 'Imamat', 15, 5, 'Setiap orang yang kena kepada tempat tidurnya haruslah mencuci pakaiannya, membasuh tubuhnya dengan air dan ia menjadi najis sampai matahari terbenam.', 'id', 'TB'),
  ('3', 'im', 'Imamat', 15, 6, 'Siapa yang duduk di atas barang yang telah diduduki oleh orang yang demikian haruslah mencuci pakaiannya, membasuh tubuhnya dengan air, dan ia menjadi najis sampai matahari terbenam.', 'id', 'TB'),
  ('3', 'im', 'Imamat', 15, 7, 'Siapa yang kena kepada tubuh orang yang demikian, haruslah mencuci pakaiannya, membasuh tubuhnya dengan air dan ia menjadi najis sampai matahari terbenam.', 'id', 'TB'),
  ('3', 'im', 'Imamat', 15, 8, 'Apabila orang yang demikian meludahi orang yang tahir, haruslah orang ini mencuci pakaiannya, membasuh tubuhnya dengan air dan ia menjadi najis sampai matahari terbenam.', 'id', 'TB'),
  ('3', 'im', 'Imamat', 15, 9, 'Dan setiap pelana yang diduduki orang yang demikian menjadi najis.', 'id', 'TB'),
  ('3', 'im', 'Imamat', 15, 10, 'Setiap orang yang kena kepada sesuatu bekas tempat orang tadi menjadi najis sampai matahari terbenam. Siapa yang mengangkatnya, haruslah mencuci pakaiannya, membasuh tubuhnya dengan air dan ia menjadi najis sampai matahari terbenam.', 'id', 'TB'),
  ('3', 'im', 'Imamat', 15, 11, 'Dan setiap orang yang kena pada orang yang demikian, sedang orang ini tidak mencuci tangan dahulu dengan air, haruslah mencuci pakaiannya, membasuh tubuhnya dengan air dan ia menjadi najis sampai matahari terbenam.', 'id', 'TB'),
  ('3', 'im', 'Imamat', 15, 12, 'Kalau orang itu kena pada belanga tanah, itu haruslah dipecahkan, dan setiap perkakas kayu haruslah dicuci dengan air.', 'id', 'TB'),
  ('3', 'im', 'Imamat', 15, 13, 'Apabila orang yang demikian sudah bersih dari lelehannya, ia harus menghitung tujuh hari lagi untuk dapat dinyatakan tahir, lalu mencuci pakaiannya, membasuh tubuhnya dengan air mengalir, maka ia menjadi tahir.', 'id', 'TB'),
  ('3', 'im', 'Imamat', 15, 14, 'Pada hari yang kedelapan ia harus mengambil dua ekor burung tekukur atau dua ekor anak burung merpati, dan datang ke hadapan TUHAN, ke pintu Kemah Pertemuan, dan menyerahkan burung-burung itu kepada imam.', 'id', 'TB'),
  ('3', 'im', 'Imamat', 15, 15, 'Lalu imam harus mempersembahkannya, yang seekor sebagai korban penghapus dosa dan yang seekor lagi sebagai korban bakaran. Dengan demikian imam mengadakan pendamaian bagi orang itu di hadapan TUHAN karena lelehannya.', 'id', 'TB'),
  ('3', 'im', 'Imamat', 15, 16, 'Apabila seorang laki-laki tertumpah maninya, ia harus membasuh seluruh tubuhnya dengan air dan ia menjadi najis sampai matahari terbenam.', 'id', 'TB'),
  ('3', 'im', 'Imamat', 15, 17, 'Setiap pakaian dan setiap kulit, yang kena tumpahan mani itu, haruslah dicuci dengan air dan menjadi najis sampai matahari terbenam.', 'id', 'TB'),
  ('3', 'im', 'Imamat', 15, 18, 'Juga seorang perempuan, kalau seorang laki-laki tidur dengan dia dengan ada tumpahan mani, maka keduanya harus membasuh tubuhnya dengan air dan mereka menjadi najis sampai matahari terbenam.', 'id', 'TB'),
  ('3', 'im', 'Imamat', 15, 19, 'Apabila seorang perempuan mengeluarkan lelehan, dan lelehannya itu adalah darah dari auratnya, ia harus tujuh hari lamanya dalam cemar kainnya, dan setiap orang yang kena kepadanya, menjadi najis sampai matahari terbenam.', 'id', 'TB'),
  ('3', 'im', 'Imamat', 15, 20, 'Segala sesuatu yang ditidurinya selama ia cemar kain menjadi najis. Dan segala sesuatu yang didudukinya menjadi najis juga.', 'id', 'TB'),
  ('3', 'im', 'Imamat', 15, 21, 'Setiap orang yang kena kepada tempat tidur perempuan itu haruslah mencuci pakaiannya, membasuh tubuhnya dengan air dan ia menjadi najis sampai matahari terbenam.', 'id', 'TB'),
  ('3', 'im', 'Imamat', 15, 22, 'Setiap orang yang kena kepada sesuatu barang yang diduduki perempuan itu haruslah mencuci pakaiannya, membasuh diri dengan air dan ia menjadi najis sampai matahari terbenam.', 'id', 'TB'),
  ('3', 'im', 'Imamat', 15, 23, 'Juga pada waktu ia kena kepada sesuatu yang ada di tempat tidur atau di atas barang yang diduduki perempuan itu, ia menjadi najis sampai matahari terbenam.', 'id', 'TB'),
  ('3', 'im', 'Imamat', 15, 24, 'Jikalau seorang laki-laki tidur dengan perempuan itu, dan ia kena cemar kain perempuan itu, maka ia menjadi najis selama tujuh hari, dan setiap tempat tidur yang ditidurinya menjadi najis juga.', 'id', 'TB'),
  ('3', 'im', 'Imamat', 15, 25, 'Apabila seorang perempuan berhari-hari lamanya mengeluarkan lelehan, yakni lelehan darah yang bukan pada waktu cemar kainnya, atau apabila ia mengeluarkan lelehan lebih lama dari waktu cemar kainnya, maka selama lelehannya yang najis itu perempuan itu adalah seperti pada hari-hari cemar kainnya, yakni ia najis.', 'id', 'TB'),
  ('3', 'im', 'Imamat', 15, 26, 'Setiap tempat tidur yang ditidurinya, selama ia mengeluarkan lelehan, haruslah baginya seperti tempat tidur pada waktu cemar kainnya dan setiap barang yang didudukinya menjadi najis sama seperti kenajisan cemar kainnya.', 'id', 'TB'),
  ('3', 'im', 'Imamat', 15, 27, 'Setiap orang yang kena kepada barang-barang itu menjadi najis, dan ia harus mencuci pakaiannya, membasuh tubuhnya dengan air, dan ia menjadi najis sampai matahari terbenam.', 'id', 'TB'),
  ('3', 'im', 'Imamat', 15, 28, 'Tetapi jikalau perempuan itu sudah tahir dari lelehannya, ia harus menghitung tujuh hari lagi, sesudah itu barulah ia menjadi tahir.', 'id', 'TB'),
  ('3', 'im', 'Imamat', 15, 29, 'Pada hari yang kedelapan ia harus mengambil dua ekor burung tekukur atau dua ekor anak burung merpati dan membawanya kepada imam ke pintu Kemah Pertemuan.', 'id', 'TB'),
  ('3', 'im', 'Imamat', 15, 30, 'Imam harus mempersembahkan yang seekor sebagai korban penghapus dosa dan yang seekor lagi sebagai korban bakaran. Dengan demikian imam mengadakan pendamaian bagi orang itu di hadapan TUHAN, karena lelehannya yang najis itu.', 'id', 'TB'),
  ('3', 'im', 'Imamat', 15, 31, 'Begitulah kamu harus menghindarkan orang Israel dari kenajisannya, supaya mereka jangan mati di dalam kenajisannya, bila mereka menajiskan Kemah Suci-Ku yang ada di tengah-tengah mereka itu."', 'id', 'TB'),
  ('3', 'im', 'Imamat', 15, 32, 'Itulah hukum tentang seorang laki-laki yang mengeluarkan lelehan atau yang tertumpah maninya yang menyebabkan dia najis,', 'id', 'TB'),
  ('3', 'im', 'Imamat', 15, 33, 'dan tentang seorang perempuan yang bercemar kain dan tentang seseorang, baik laki-laki maupun perempuan, yang mengeluarkan lelehan, dan tentang laki-laki yang tidur dengan perempuan yang najis.', 'id', 'TB'),
  ('3', 'im', 'Imamat', 16, 1, 'Sesudah kedua anak Harun mati, yang terjadi pada waktu mereka mendekat ke hadapan TUHAN, berfirmanlah TUHAN kepada Musa.', 'id', 'TB'),
  ('3', 'im', 'Imamat', 16, 2, 'Firman TUHAN kepadanya: "Katakanlah kepada Harun, kakakmu, supaya ia jangan sembarang waktu masuk ke dalam tempat kudus di belakang tabir, ke depan tutup pendamaian yang di atas tabut supaya jangan ia mati; karena Aku menampakkan diri dalam awan di atas tutup pendamaian.', 'id', 'TB'),
  ('3', 'im', 'Imamat', 16, 3, 'Beginilah caranya Harun masuk ke dalam tempat kudus itu, yakni dengan membawa seekor lembu jantan muda untuk korban penghapus dosa dan seekor domba jantan untuk korban bakaran.', 'id', 'TB'),
  ('3', 'im', 'Imamat', 16, 4, 'Ia harus mengenakan kemeja lenan yang kudus dan ia harus menutupi auratnya dengan celana lenan dan ia harus memakai ikat pinggang lenan dan berlilitkan serban lenan; itulah pakaian kudus yang harus dikenakannya, sesudah ia membasuh tubuhnya dengan air.', 'id', 'TB'),
  ('3', 'im', 'Imamat', 16, 5, 'Dari umat Israel ia harus mengambil dua ekor kambing jantan untuk korban penghapus dosa dan seekor domba jantan untuk korban bakaran.', 'id', 'TB'),
  ('3', 'im', 'Imamat', 16, 6, 'Kemudian Harun harus mempersembahkan lembu jantan yang akan menjadi korban penghapus dosa baginya sendiri dan dengan demikian mengadakan pendamaian baginya dan bagi keluarganya.', 'id', 'TB'),
  ('3', 'im', 'Imamat', 16, 7, 'Ia harus mengambil kedua ekor kambing jantan itu dan menempatkannya di hadapan TUHAN di depan pintu Kemah Pertemuan,', 'id', 'TB'),
  ('3', 'im', 'Imamat', 16, 8, 'dan harus membuang undi atas kedua kambing jantan itu, sebuah undi bagi TUHAN dan sebuah bagi Azazel.', 'id', 'TB'),
  ('3', 'im', 'Imamat', 16, 9, 'Lalu Harun harus mempersembahkan kambing jantan yang kena undi bagi TUHAN itu dan mengolahnya sebagai korban penghapus dosa.', 'id', 'TB'),
  ('3', 'im', 'Imamat', 16, 10, 'Tetapi kambing jantan yang kena undi bagi Azazel haruslah ditempatkan hidup-hidup di hadapan TUHAN untuk mengadakan pendamaian, lalu dilepaskan bagi Azazel ke padang gurun.', 'id', 'TB'),
  ('3', 'im', 'Imamat', 16, 11, 'Harun harus mempersembahkan lembu jantan yang akan menjadi korban penghapus dosa baginya sendiri dan mengadakan pendamaian baginya dan bagi keluarganya; ia harus menyembelih lembu jantan itu.', 'id', 'TB'),
  ('3', 'im', 'Imamat', 16, 12, 'Dan ia harus mengambil perbaraan berisi penuh bara api dari atas mezbah yang di hadapan TUHAN, serta serangkup penuh ukupan dari wangi-wangian yang digiling sampai halus, lalu membawanya masuk ke belakang tabir.', 'id', 'TB'),
  ('3', 'im', 'Imamat', 16, 13, 'Kemudian ia harus meletakkan ukupan itu di atas api yang di hadapan TUHAN, sehingga asap ukupan itu menutupi tutup pendamaian yang di atas hukum Allah, supaya ia jangan mati.', 'id', 'TB'),
  ('3', 'im', 'Imamat', 16, 14, 'Lalu ia harus mengambil sedikit dari darah lembu jantan itu dan memercikkannya dengan jarinya ke atas tutup pendamaian di bagian muka, dan ke depan tutup pendamaian itu ia harus memercikkan sedikit dari darah itu dengan jarinya tujuh kali.', 'id', 'TB'),
  ('3', 'im', 'Imamat', 16, 15, 'Lalu ia harus menyembelih domba jantan yang akan menjadi korban penghapus dosa bagi bangsa itu dan membawa darahnya masuk ke belakang tabir, kemudian haruslah diperbuatnya dengan darah itu seperti yang diperbuatnya dengan darah lembu jantan, yakni ia harus memercikkannya ke atas tutup pendamaian dan ke depan tutup pendamaian itu.', 'id', 'TB'),
  ('3', 'im', 'Imamat', 16, 16, 'Dengan demikian ia mengadakan pendamaian bagi tempat kudus itu karena segala kenajisan orang Israel dan karena segala pelanggaran mereka, apapun juga dosa mereka. Demikianlah harus diperbuatnya dengan Kemah Pertemuan yang tetap diam di antara mereka di tengah-tengah segala kenajisan mereka.', 'id', 'TB'),
  ('3', 'im', 'Imamat', 16, 17, 'Seorangpun tidak boleh hadir di dalam Kemah Pertemuan, bila Harun masuk untuk mengadakan pendamaian di tempat kudus, sampai ia keluar, setelah mengadakan pendamaian baginya sendiri, bagi keluarganya dan bagi seluruh jemaah orang Israel.', 'id', 'TB'),
  ('3', 'im', 'Imamat', 16, 18, 'Kemudian haruslah ia pergi ke luar ke mezbah yang ada di hadapan TUHAN, dan mengadakan pendamaian bagi mezbah itu. Ia harus mengambil sedikit dari darah lembu jantan dan dari darah domba jantan itu dan membubuhnya pada tanduk-tanduk mezbah sekelilingnya.', 'id', 'TB'),
  ('3', 'im', 'Imamat', 16, 19, 'Kemudian ia harus memercikkan sedikit dari darah itu ke mezbah itu dengan jarinya tujuh kali dan mentahirkan serta menguduskannya dari segala kenajisan orang Israel.', 'id', 'TB'),
  ('3', 'im', 'Imamat', 16, 20, 'Setelah selesai mengadakan pendamaian bagi tempat kudus dan Kemah Pertemuan serta mezbah, ia harus mempersembahkan kambing jantan yang masih hidup itu,', 'id', 'TB'),
  ('3', 'im', 'Imamat', 16, 21, 'dan Harun harus meletakkan kedua tangannya ke atas kepala kambing jantan yang hidup itu dan mengakui di atas kepala kambing itu segala kesalahan orang Israel dan segala pelanggaran mereka, apapun juga dosa mereka; ia harus menanggungkan semuanya itu ke atas kepala kambing jantan itu dan kemudian melepaskannya ke padang gurun dengan perantaraan seseorang yang sudah siap sedia untuk itu.', 'id', 'TB'),
  ('3', 'im', 'Imamat', 16, 22, 'Demikianlah kambing jantan itu harus mengangkut segala kesalahan Israel ke tanah yang tandus, dan kambing itu harus dilepaskan di padang gurun.', 'id', 'TB'),
  ('3', 'im', 'Imamat', 16, 23, 'Sesudah itu Harun harus masuk ke dalam Kemah Pertemuan dan menanggalkan pakaian lenan, yang dikenakannya ketika ia masuk ke dalam tempat kudus dan harus meninggalkannya di sana.', 'id', 'TB'),
  ('3', 'im', 'Imamat', 16, 24, 'Ia harus membasuh tubuhnya dengan air di suatu tempat yang kudus dan mengenakan pakaiannya sendiri, lalu ia harus keluar dan mempersembahkan korban bakarannya sendiri dan korban bakaran bangsa itu; dengan demikian ia mengadakan pendamaian baginya sendiri dan bagi bangsa itu.', 'id', 'TB'),
  ('3', 'im', 'Imamat', 16, 25, 'Kemudian ia harus membakar lemak korban penghapus dosa di atas mezbah.', 'id', 'TB'),
  ('3', 'im', 'Imamat', 16, 26, 'Maka orang yang melepaskan kambing jantan bagi Azazel itu harus mencuci pakaiannya, membasuh tubuhnya dengan air dan sesudah itu barulah boleh masuk ke perkemahan.', 'id', 'TB'),
  ('3', 'im', 'Imamat', 16, 27, 'Lembu jantan dan kambing jantan korban penghapus dosa, yang darahnya telah dibawa masuk untuk mengadakan pendamaian di dalam tempat kudus, harus dibawa keluar dari perkemahan, dan kulitnya, dagingnya dan kotorannya harus dibakar habis.', 'id', 'TB'),
  ('3', 'im', 'Imamat', 16, 28, 'Siapa yang membakar semuanya itu, harus mencuci pakaiannya, membasuh tubuhnya dengan air dan sesudah itu barulah boleh masuk ke perkemahan.', 'id', 'TB'),
  ('3', 'im', 'Imamat', 16, 29, 'Inilah yang harus menjadi ketetapan untuk selama-lamanya bagi kamu, yakni pada bulan yang ketujuh, pada tanggal sepuluh bulan itu kamu harus merendahkan diri dengan berpuasa dan janganlah kamu melakukan sesuatu pekerjaan, baik orang Israel asli maupun orang asing yang tinggal di tengah-tengahmu.', 'id', 'TB'),
  ('3', 'im', 'Imamat', 16, 30, 'Karena pada hari itu harus diadakan pendamaian bagimu untuk mentahirkan kamu. Kamu akan ditahirkan dari segala dosamu di hadapan TUHAN.', 'id', 'TB'),
  ('3', 'im', 'Imamat', 16, 31, 'Hari itu harus menjadi sabat, hari perhentian penuh, bagimu dan kamu harus merendahkan diri dengan berpuasa. Itulah suatu ketetapan untuk selama-lamanya.', 'id', 'TB'),
  ('3', 'im', 'Imamat', 16, 32, 'Dan pendamaian harus diadakan oleh imam yang telah diurapi dan telah ditahbiskan untuk memegang jabatan imam menggantikan ayahnya; ia harus mengenakan pakaian lenan, yakni pakaian kudus.', 'id', 'TB'),
  ('3', 'im', 'Imamat', 16, 33, 'Ia harus mengadakan pendamaian bagi tempat maha kudus, bagi Kemah Pertemuan dan bagi mezbah, juga bagi para imam dan bagi seluruh bangsa itu, yakni jemaah itu.', 'id', 'TB'),
  ('3', 'im', 'Imamat', 16, 34, 'Itulah yang harus menjadi ketetapan untuk selama-lamanya bagimu, supaya sekali setahun diadakan pendamaian bagi orang Israel karena segala dosa mereka." Maka Harun melakukan seperti yang diperintahkan TUHAN kepada Musa.', 'id', 'TB'),
  ('3', 'im', 'Imamat', 17, 1, 'TUHAN berfirman kepada Musa:', 'id', 'TB'),
  ('3', 'im', 'Imamat', 17, 2, '"Berbicaralah kepada Harun dan kepada anak-anaknya dan kepada seluruh orang Israel, dan katakan kepada mereka: Inilah firman yang diperintahkan TUHAN:', 'id', 'TB'),
  ('3', 'im', 'Imamat', 17, 3, 'Setiap orang dari kaum Israel yang menyembelih lembu atau domba atau kambing di dalam perkemahan atau di luarnya,', 'id', 'TB'),
  ('3', 'im', 'Imamat', 17, 4, 'tetapi tidak membawanya ke pintu Kemah Pertemuan, untuk dipersembahkan sebagai persembahan kepada TUHAN di depan Kemah Suci TUHAN, hal itu harus dihitungkan kepada orang itu sebagai hutang darah, karena ia telah menumpahkan darah, dan orang itu haruslah dilenyapkan dari tengah-tengah bangsanya.', 'id', 'TB'),
  ('3', 'im', 'Imamat', 17, 5, 'Maksudnya supaya orang Israel membawa korban sembelihan mereka, yang biasa dipersembahkan mereka di padang, kepada TUHAN ke pintu Kemah Pertemuan dengan menyerahkannya kepada imam, untuk dipersembahkan kepada TUHAN sebagai korban keselamatan.', 'id', 'TB'),
  ('3', 'im', 'Imamat', 17, 6, 'Imam harus menyiramkan darahnya pada mezbah TUHAN di depan pintu Kemah Pertemuan dan membakar lemaknya menjadi bau yang menyenangkan bagi TUHAN.', 'id', 'TB'),
  ('3', 'im', 'Imamat', 17, 7, 'Janganlah mereka mempersembahkan lagi korban mereka kepada jin-jin, sebab menyembah jin-jin itu adalah zinah. Itulah yang harus menjadi ketetapan untuk selama-lamanya bagi mereka turun-temurun.', 'id', 'TB'),
  ('3', 'im', 'Imamat', 17, 8, 'Dan haruslah kaukatakan kepada mereka: Setiap orang dari kaum Israel atau dari orang asing yang tinggal di tengah-tengah mereka, yang mempersembahkan korban bakaran atau korban sembelihan,', 'id', 'TB'),
  ('3', 'im', 'Imamat', 17, 9, 'tetapi tidak membawanya ke pintu Kemah Pertemuan supaya dipersembahkan kepada TUHAN, maka orang itu haruslah dilenyapkan dari antara orang-orang sebangsanya."', 'id', 'TB'),
  ('3', 'im', 'Imamat', 17, 10, '"Setiap orang dari bangsa Israel dan dari orang asing yang tinggal di tengah-tengah mereka, yang makan darah apapun juga Aku sendiri akan menentang dia dan melenyapkan dia dari tengah-tengah bangsanya.', 'id', 'TB'),
  ('3', 'im', 'Imamat', 17, 11, 'Karena nyawa makhluk ada di dalam darahnya dan Aku telah memberikan darah itu kepadamu di atas mezbah untuk mengadakan pendamaian bagi nyawamu, karena darah mengadakan pendamaian dengan perantaraan nyawa.', 'id', 'TB'),
  ('3', 'im', 'Imamat', 17, 12, 'Itulah sebabnya Aku berfirman kepada orang Israel: Seorangpun di antaramu janganlah makan darah. Demikian juga orang asing yang tinggal di tengah-tengahmu tidak boleh makan darah.', 'id', 'TB'),
  ('3', 'im', 'Imamat', 17, 13, 'Setiap orang dari orang Israel dan dari orang asing yang tinggal di tengah-tengahmu, yang menangkap dalam perburuan seekor binatang atau burung yang boleh dimakan, haruslah mencurahkan darahnya, lalu menimbunnya dengan tanah.', 'id', 'TB'),
  ('3', 'im', 'Imamat', 17, 14, 'Karena darah itulah nyawa segala makhluk. Sebab itu Aku telah berfirman kepada orang Israel: Darah makhluk apapun janganlah kamu makan, karena darah itulah nyawa segala makhluk: setiap orang yang memakannya haruslah dilenyapkan.', 'id', 'TB'),
  ('3', 'im', 'Imamat', 17, 15, 'Dan setiap orang yang makan bangkai atau sisa mangsa binatang buas, baik ia orang Israel asli maupun orang asing, haruslah mencuci pakaiannya, membasuh tubuhnya dengan air dan ia menjadi najis sampai matahari terbenam, barulah ia menjadi tahir.', 'id', 'TB'),
  ('3', 'im', 'Imamat', 17, 16, 'Tetapi jikalau ia tidak mencuci pakaiannya dan tidak membasuh tubuhnya, ia akan menanggung kesalahannya sendiri."', 'id', 'TB'),
  ('3', 'im', 'Imamat', 18, 1, 'TUHAN berfirman kepada Musa:', 'id', 'TB'),
  ('3', 'im', 'Imamat', 18, 2, '"Berbicaralah kepada orang Israel dan katakan kepada mereka: Akulah TUHAN, Allahmu.', 'id', 'TB'),
  ('3', 'im', 'Imamat', 18, 3, 'Janganlah kamu berbuat seperti yang diperbuat orang di tanah Mesir, di mana kamu diam dahulu; juga janganlah kamu berbuat seperti yang diperbuat orang di tanah Kanaan, ke mana Aku membawa kamu; janganlah kamu hidup menurut kebiasaan mereka.', 'id', 'TB'),
  ('3', 'im', 'Imamat', 18, 4, 'Kamu harus lakukan peraturan-Ku dan harus berpegang pada ketetapan-Ku dengan hidup menurut semuanya itu; Akulah TUHAN, Allahmu.', 'id', 'TB'),
  ('3', 'im', 'Imamat', 18, 5, 'Sesungguhnya kamu harus berpegang pada ketetapan-Ku dan peraturan-Ku. Orang yang melakukannya, akan hidup karenanya; Akulah TUHAN.', 'id', 'TB'),
  ('3', 'im', 'Imamat', 18, 6, 'Siapapun di antaramu janganlah menghampiri seorang kerabatnya yang terdekat untuk menyingkapkan auratnya; Akulah TUHAN.', 'id', 'TB'),
  ('3', 'im', 'Imamat', 18, 7, 'Janganlah kausingkapkan aurat isteri ayahmu, karena ia hak ayahmu; dia ibumu, jadi janganlah singkapkan auratnya.', 'id', 'TB'),
  ('3', 'im', 'Imamat', 18, 8, 'Janganlah kausingkapkan aurat seorang isteri ayahmu, karena ia hak ayahmu.', 'id', 'TB'),
  ('3', 'im', 'Imamat', 18, 9, 'Mengenai aurat saudaramu perempuan, anak ayahmu atau anak ibumu, baik yang lahir di rumah ayahmu maupun yang lahir di luar, janganlah kausingkapkan auratnya.', 'id', 'TB'),
  ('3', 'im', 'Imamat', 18, 10, 'Mengenai aurat anak perempuan dari anakmu laki-laki atau anakmu perempuan, janganlah kausingkapkan auratnya, karena dengan begitu engkau menodai keturunanmu.', 'id', 'TB'),
  ('3', 'im', 'Imamat', 18, 11, 'Mengenai aurat anak perempuan dari seorang isteri ayahmu, yang lahir pada ayahmu sendiri, janganlah kausingkapkan auratnya, karena ia saudaramu perempuan.', 'id', 'TB'),
  ('3', 'im', 'Imamat', 18, 12, 'Janganlah kausingkapkan aurat saudara perempuan ayahmu, karena ia kerabat ayahmu.', 'id', 'TB'),
  ('3', 'im', 'Imamat', 18, 13, 'Janganlah kausingkapkan aurat saudara perempuan ibumu, karena ia kerabat ibumu.', 'id', 'TB'),
  ('3', 'im', 'Imamat', 18, 14, 'Janganlah kausingkapkan aurat isteri saudara laki-laki ayahmu, janganlah kauhampiri isterinya, karena ia isteri saudara ayahmu.', 'id', 'TB'),
  ('3', 'im', 'Imamat', 18, 15, 'Janganlah kausingkapkan aurat menantumu perempuan, karena ia isteri anakmu laki-laki, maka janganlah kausingkapkan auratnya.', 'id', 'TB'),
  ('3', 'im', 'Imamat', 18, 16, 'Janganlah kausingkapkan aurat isteri saudaramu laki-laki, karena itu hak saudaramu laki-laki.', 'id', 'TB'),
  ('3', 'im', 'Imamat', 18, 17, 'Janganlah kausingkapkan aurat seorang perempuan dan anaknya perempuan. Janganlah kauambil anak perempuan dari anaknya laki-laki atau dari anaknya perempuan untuk menyingkapkan auratnya, karena mereka adalah kerabatmu; itulah perbuatan mesum.', 'id', 'TB'),
  ('3', 'im', 'Imamat', 18, 18, 'Janganlah kauambil seorang perempuan sebagai madu kakaknya untuk menyingkapkan auratnya di samping kakaknya selama kakaknya itu masih hidup.', 'id', 'TB'),
  ('3', 'im', 'Imamat', 18, 19, 'Janganlah kauhampiri seorang perempuan pada waktu cemar kainnya yang menajiskan untuk menyingkapkan auratnya.', 'id', 'TB'),
  ('3', 'im', 'Imamat', 18, 20, 'Dan janganlah engkau bersetubuh dengan isteri sesamamu, sehingga engkau menjadi najis dengan dia.', 'id', 'TB'),
  ('3', 'im', 'Imamat', 18, 21, 'Janganlah kauserahkan seorang dari anak-anakmu untuk dipersembahkan kepada Molokh, supaya jangan engkau melanggar kekudusan nama Allahmu; Akulah TUHAN.', 'id', 'TB'),
  ('3', 'im', 'Imamat', 18, 22, 'Janganlah engkau tidur dengan laki-laki secara orang bersetubuh dengan perempuan, karena itu suatu kekejian.', 'id', 'TB'),
  ('3', 'im', 'Imamat', 18, 23, 'Janganlah engkau berkelamin dengan binatang apapun, sehingga engkau menjadi najis dengan binatang itu. Seorang perempuan janganlah berdiri di depan seekor binatang untuk berkelamin, karena itu suatu perbuatan keji.', 'id', 'TB'),
  ('3', 'im', 'Imamat', 18, 24, 'Janganlah kamu menajiskan dirimu dengan semuanya itu, sebab dengan semuanya itu bangsa-bangsa yang akan Kuhalaukan dari depanmu telah menjadi najis.', 'id', 'TB'),
  ('3', 'im', 'Imamat', 18, 25, 'Negeri itu telah menjadi najis dan Aku telah membalaskan kesalahannya kepadanya, sehingga negeri itu memuntahkan penduduknya.', 'id', 'TB'),
  ('3', 'im', 'Imamat', 18, 26, 'Tetapi kamu ini haruslah tetap berpegang pada ketetapan-Ku dan peraturan-Ku dan jangan melakukan sesuatupun dari segala kekejian itu, baik orang Israel asli maupun orang asing yang tinggal di tengah-tengahmu,', 'id', 'TB'),
  ('3', 'im', 'Imamat', 18, 27, '?karena segala kekejian itu telah dilakukan oleh penghuni negeri yang sebelum kamu, sehingga negeri itu sudah menjadi najis?', 'id', 'TB'),
  ('3', 'im', 'Imamat', 18, 28, 'supaya kamu jangan dimuntahkan oleh negeri itu, apabila kamu menajiskannya, seperti telah dimuntahkannya bangsa yang sebelum kamu.', 'id', 'TB'),
  ('3', 'im', 'Imamat', 18, 29, 'Karena setiap orang yang melakukan sesuatupun dari segala kekejian itu, orang itu harus dilenyapkan dari tengah-tengah bangsanya.', 'id', 'TB'),
  ('3', 'im', 'Imamat', 18, 30, 'Dengan demikian kamu harus tetap berpegang pada kewajibanmu terhadap Aku, dan jangan kamu melakukan sesuatu dari kebiasaan yang keji itu, yang dilakukan sebelum kamu, dan janganlah kamu menajiskan dirimu dengan semuanya itu; Akulah TUHAN, Allahmu."', 'id', 'TB'),
  ('3', 'im', 'Imamat', 19, 1, 'TUHAN berfirman kepada Musa:', 'id', 'TB'),
  ('3', 'im', 'Imamat', 19, 2, '"Berbicaralah kepada segenap jemaah Israel dan katakan kepada mereka: Kuduslah kamu, sebab Aku, TUHAN, Allahmu, kudus.', 'id', 'TB'),
  ('3', 'im', 'Imamat', 19, 3, 'Setiap orang di antara kamu haruslah menyegani ibunya dan ayahnya dan memelihara hari-hari sabat-Ku; Akulah TUHAN, Allahmu.', 'id', 'TB'),
  ('3', 'im', 'Imamat', 19, 4, 'Janganlah kamu berpaling kepada berhala-berhala dan janganlah kamu membuat bagimu dewa tuangan; Akulah TUHAN, Allahmu.', 'id', 'TB'),
  ('3', 'im', 'Imamat', 19, 5, 'Apabila kamu mempersembahkan korban keselamatan kepada TUHAN, kamu harus mempersembahkannya sedemikian, hingga TUHAN berkenan akan kamu.', 'id', 'TB'),
  ('3', 'im', 'Imamat', 19, 6, 'Dan haruslah itu dimakan pada hari mempersembahkannya atau boleh juga pada keesokan harinya, tetapi apa yang tinggal sampai hari yang ketiga haruslah dibakar habis.', 'id', 'TB'),
  ('3', 'im', 'Imamat', 19, 7, 'Jikalau dimakan juga pada hari yang ketiga, maka itu menjadi sesuatu yang jijik dan TUHAN tidak berkenan akan orang itu.', 'id', 'TB'),
  ('3', 'im', 'Imamat', 19, 8, 'Siapa yang memakannya, akan menanggung kesalahannya sendiri, karena ia telah melanggar kekudusan persembahan kudus yang kepada TUHAN. Nyawa orang itu haruslah dilenyapkan dari antara orang-orang sebangsanya.', 'id', 'TB'),
  ('3', 'im', 'Imamat', 19, 9, 'Pada waktu kamu menuai hasil tanahmu, janganlah kausabit ladangmu habis-habis sampai ke tepinya, dan janganlah kaupungut apa yang ketinggalan dari penuaianmu.', 'id', 'TB'),
  ('3', 'im', 'Imamat', 19, 10, 'Juga sisa-sisa buah anggurmu janganlah kaupetik untuk kedua kalinya dan buah yang berjatuhan di kebun anggurmu janganlah kaupungut, tetapi semuanya itu harus kautinggalkan bagi orang miskin dan bagi orang asing; Akulah TUHAN, Allahmu.', 'id', 'TB'),
  ('3', 'im', 'Imamat', 19, 11, 'Janganlah kamu mencuri, janganlah kamu berbohong dan janganlah kamu berdusta seorang kepada sesamanya.', 'id', 'TB'),
  ('3', 'im', 'Imamat', 19, 12, 'Janganlah kamu bersumpah dusta demi nama-Ku, supaya engkau jangan melanggar kekudusan nama Allahmu; Akulah TUHAN.', 'id', 'TB'),
  ('3', 'im', 'Imamat', 19, 13, 'Janganlah engkau memeras sesamamu manusia dan janganlah engkau merampas; janganlah kautahan upah seorang pekerja harian sampai besok harinya.', 'id', 'TB'),
  ('3', 'im', 'Imamat', 19, 14, 'Janganlah kaukutuki orang tuli dan di depan orang buta janganlah kautaruh batu sandungan, tetapi engkau harus takut akan Allahmu; Akulah TUHAN.', 'id', 'TB'),
  ('3', 'im', 'Imamat', 19, 15, 'Janganlah kamu berbuat curang dalam peradilan; janganlah engkau membela orang kecil dengan tidak sewajarnya dan janganlah engkau terpengaruh oleh orang-orang besar, tetapi engkau harus mengadili orang sesamamu dengan kebenaran.', 'id', 'TB'),
  ('3', 'im', 'Imamat', 19, 16, 'Janganlah engkau pergi kian ke mari menyebarkan fitnah di antara orang-orang sebangsamu; janganlah engkau mengancam hidup sesamamu manusia; Akulah TUHAN.', 'id', 'TB'),
  ('3', 'im', 'Imamat', 19, 17, 'Janganlah engkau membenci saudaramu di dalam hatimu, tetapi engkau harus berterus terang menegor orang sesamamu dan janganlah engkau mendatangkan dosa kepada dirimu karena dia.', 'id', 'TB'),
  ('3', 'im', 'Imamat', 19, 18, 'Janganlah engkau menuntut balas, dan janganlah menaruh dendam terhadap orang-orang sebangsamu, melainkan kasihilah sesamamu manusia seperti dirimu sendiri; Akulah TUHAN.', 'id', 'TB'),
  ('3', 'im', 'Imamat', 19, 19, 'Kamu harus berpegang kepada ketetapan-Ku. Janganlah kawinkan dua jenis ternak dan janganlah taburi ladangmu dengan dua jenis benih, dan janganlah pakai pakaian yang dibuat dari pada dua jenis bahan.', 'id', 'TB'),
  ('3', 'im', 'Imamat', 19, 20, 'Apabila seorang laki-laki bersetubuh dengan seorang perempuan, yakni seorang budak perempuan yang ada di bawah kuasa laki-laki lain, tetapi yang tidak pernah ditebus dan tidak juga diberi surat tanda merdeka, maka perbuatan itu haruslah dihukum; tetapi janganlah keduanya dihukum mati, karena perempuan itu belum dimerdekakan.', 'id', 'TB'),
  ('3', 'im', 'Imamat', 19, 21, 'Laki-laki itu harus membawa tebusan salahnya kepada TUHAN ke pintu Kemah Pertemuan, yakni seekor domba jantan sebagai korban penebus salah.', 'id', 'TB'),
  ('3', 'im', 'Imamat', 19, 22, 'Imam harus mengadakan pendamaian bagi orang itu dengan domba jantan korban penebus salah di hadapan TUHAN, karena dosa yang telah diperbuatnya, sehingga ia beroleh pengampunan dari dosanya itu.', 'id', 'TB'),
  ('3', 'im', 'Imamat', 19, 23, 'Apabila kamu sudah masuk ke negeri itu dan menanam bermacam-macam pohon buah-buahan, janganlah kamu memetik buahnya selama tiga tahun dan jangan memakannya.', 'id', 'TB'),
  ('3', 'im', 'Imamat', 19, 24, 'Tetapi pada tahun yang keempat haruslah segala buahnya menjadi persembahan kudus sebagai puji-pujian bagi TUHAN.', 'id', 'TB'),
  ('3', 'im', 'Imamat', 19, 25, 'Barulah pada tahun yang kelima kamu boleh memakan buahnya, supaya hasilnya ditambah bagimu; Akulah TUHAN, Allahmu.', 'id', 'TB'),
  ('3', 'im', 'Imamat', 19, 26, 'Janganlah kamu makan sesuatu yang darahnya masih ada. Janganlah kamu melakukan telaah atau ramalan.', 'id', 'TB'),
  ('3', 'im', 'Imamat', 19, 27, 'Janganlah kamu mencukur tepi rambut kepalamu berkeliling dan janganlah engkau merusakkan tepi janggutmu.', 'id', 'TB'),
  ('3', 'im', 'Imamat', 19, 28, 'Janganlah kamu menggoresi tubuhmu karena orang mati dan janganlah merajah tanda-tanda pada kulitmu; Akulah TUHAN.', 'id', 'TB'),
  ('3', 'im', 'Imamat', 19, 29, 'Janganlah engkau merusak kesucian anakmu perempuan dengan menjadikan dia perempuan sundal, supaya negeri itu jangan melakukan persundalan, sehingga negeri itu penuh dengan perbuatan mesum.', 'id', 'TB'),
  ('3', 'im', 'Imamat', 19, 30, 'Kamu harus memelihara hari-hari sabat-Ku dan menghormati tempat kudus-Ku; Akulah TUHAN.', 'id', 'TB'),
  ('3', 'im', 'Imamat', 19, 31, 'Janganlah kamu berpaling kepada arwah atau kepada roh-roh peramal; janganlah kamu mencari mereka dan dengan demikian menjadi najis karena mereka; Akulah TUHAN, Allahmu.', 'id', 'TB'),
  ('3', 'im', 'Imamat', 19, 32, 'Engkau harus bangun berdiri di hadapan orang ubanan dan engkau harus menaruh hormat kepada orang yang tua dan engkau harus takut akan Allahmu; Akulah TUHAN.', 'id', 'TB'),
  ('3', 'im', 'Imamat', 19, 33, 'Apabila seorang asing tinggal padamu di negerimu, janganlah kamu menindas dia.', 'id', 'TB'),
  ('3', 'im', 'Imamat', 19, 34, 'Orang asing yang tinggal padamu harus sama bagimu seperti orang Israel asli dari antaramu, kasihilah dia seperti dirimu sendiri, karena kamu juga orang asing dahulu di tanah Mesir; Akulah TUHAN, Allahmu.', 'id', 'TB'),
  ('3', 'im', 'Imamat', 19, 35, 'Janganlah kamu berbuat curang dalam peradilan, mengenai ukuran, timbangan dan sukatan.', 'id', 'TB'),
  ('3', 'im', 'Imamat', 19, 36, 'Neraca yang betul, batu timbangan yang betul, efa yang betul dan hin yang betul haruslah kamu pakai; Akulah TUHAN, Allahmu yang membawa kamu keluar dari tanah Mesir.', 'id', 'TB'),
  ('3', 'im', 'Imamat', 19, 37, 'Demikianlah kamu harus berpegang pada segala ketetapan-Ku dan segala peraturan-Ku serta melakukan semuanya itu; Akulah TUHAN."', 'id', 'TB'),
  ('3', 'im', 'Imamat', 20, 1, 'TUHAN berfirman kepada Musa:', 'id', 'TB'),
  ('3', 'im', 'Imamat', 20, 2, '"Engkau harus berkata kepada orang Israel: Setiap orang, baik dari antara orang Israel maupun dari antara orang asing yang tinggal di tengah-tengah orang Israel, yang menyerahkan seorang dari anak-anaknya kepada Molokh, pastilah ia dihukum mati, yakni rakyat negeri harus melontari dia dengan batu.', 'id', 'TB'),
  ('3', 'im', 'Imamat', 20, 3, 'Aku sendiri akan menentang orang itu dan akan melenyapkan dia dari tengah-tengah bangsanya, karena ia menyerahkan seorang dari anak-anaknya kepada Molokh, dengan maksud menajiskan tempat kudus-Ku dan melanggar kekudusan nama-Ku yang kudus.', 'id', 'TB'),
  ('3', 'im', 'Imamat', 20, 4, 'Tetapi jikalau rakyat negeri menutup mata terhadap orang itu, ketika ia menyerahkan seorang dari anak-anaknya kepada Molokh, dan tidak menghukum dia mati,', 'id', 'TB'),
  ('3', 'im', 'Imamat', 20, 5, 'maka Aku sendiri akan menentang orang itu serta kaumnya dan akan melenyapkan dia dari tengah-tengah bangsanya dan semua orang yang turut berzinah mengikuti dia, yakni berzinah dengan menyembah Molokh.', 'id', 'TB'),
  ('3', 'im', 'Imamat', 20, 6, 'Orang yang berpaling kepada arwah atau kepada roh-roh peramal, yakni yang berzinah dengan bertanya kepada mereka, Aku sendiri akan menentang orang itu dan melenyapkan dia dari tengah-tengah bangsanya.', 'id', 'TB'),
  ('3', 'im', 'Imamat', 20, 7, 'Maka kamu harus menguduskan dirimu, dan kuduslah kamu, sebab Akulah TUHAN, Allahmu.', 'id', 'TB'),
  ('3', 'im', 'Imamat', 20, 8, 'Demikianlah kamu harus berpegang pada ketetapan-Ku dan melakukannya; Akulah TUHAN yang menguduskan kamu.', 'id', 'TB'),
  ('3', 'im', 'Imamat', 20, 9, 'Apabila ada seseorang yang mengutuki ayahnya atau ibunya, pastilah ia dihukum mati; ia telah mengutuki ayahnya atau ibunya, maka darahnya tertimpa kepadanya sendiri.', 'id', 'TB'),
  ('3', 'im', 'Imamat', 20, 10, 'Bila seorang laki-laki berzinah dengan isteri orang lain, yakni berzinah dengan isteri sesamanya manusia, pastilah keduanya dihukum mati, baik laki-laki maupun perempuan yang berzinah itu.', 'id', 'TB'),
  ('3', 'im', 'Imamat', 20, 11, 'Bila seorang laki-laki tidur dengan seorang isteri ayahnya, jadi ia melanggar hak ayahnya, pastilah keduanya dihukum mati, dan darah mereka tertimpa kepada mereka sendiri.', 'id', 'TB'),
  ('3', 'im', 'Imamat', 20, 12, 'Bila seorang laki-laki tidur dengan menantunya perempuan, pastilah keduanya dihukum mati; mereka telah melakukan suatu perbuatan keji, maka darah mereka tertimpa kepada mereka sendiri.', 'id', 'TB'),
  ('3', 'im', 'Imamat', 20, 13, 'Bila seorang laki-laki tidur dengan laki-laki secara orang bersetubuh dengan perempuan, jadi keduanya melakukan suatu kekejian, pastilah mereka dihukum mati dan darah mereka tertimpa kepada mereka sendiri.', 'id', 'TB'),
  ('3', 'im', 'Imamat', 20, 14, 'Bila seorang laki-laki mengambil seorang perempuan dan ibunya, itu suatu perbuatan mesum; ia dan kedua perempuan itu harus dibakar, supaya jangan ada perbuatan mesum di tengah-tengah kamu.', 'id', 'TB'),
  ('3', 'im', 'Imamat', 20, 15, 'Bila seorang laki-laki berkelamin dengan seekor binatang, pastilah ia dihukum mati, dan binatang itupun harus kamu bunuh juga.', 'id', 'TB'),
  ('3', 'im', 'Imamat', 20, 16, 'Bila seorang perempuan menghampiri binatang apapun untuk berkelamin, haruslah kaubunuh perempuan dan binatang itu; mereka pasti dihukum mati dan darah mereka tertimpa kepada mereka sendiri.', 'id', 'TB'),
  ('3', 'im', 'Imamat', 20, 17, 'Bila seorang laki-laki mengambil saudaranya perempuan, anak ayahnya atau anak ibunya, dan mereka bersetubuh, maka itu suatu perbuatan sumbang, dan mereka harus dilenyapkan di depan orang-orang sebangsanya; orang itu telah menyingkapkan aurat saudaranya perempuan, maka ia harus menanggung kesalahannya sendiri.', 'id', 'TB'),
  ('3', 'im', 'Imamat', 20, 18, 'Bila seorang laki-laki tidur dengan seorang perempuan yang bercemar kain, jadi ia menyingkapkan aurat perempuan itu dan membuka tutup lelerannya sedang perempuan itupun membiarkan tutup leleran darahnya itu disingkapkan, keduanya harus dilenyapkan dari tengah-tengah bangsanya.', 'id', 'TB'),
  ('3', 'im', 'Imamat', 20, 19, 'Janganlah kausingkapkan aurat saudara perempuan ibumu atau saudara perempuan ayahmu, karena aurat seorang kerabatnya sendirilah yang dibuka, dan mereka harus menanggung kesalahannya sendiri.', 'id', 'TB'),
  ('3', 'im', 'Imamat', 20, 20, 'Bila seorang laki-laki tidur dengan isteri saudara ayahnya, jadi ia melanggar hak saudara ayahnya, mereka mendatangkan dosa kepada dirinya, dan mereka akan mati dengan tidak beranak.', 'id', 'TB'),
  ('3', 'im', 'Imamat', 20, 21, 'Bila seorang laki-laki mengambil isteri saudaranya, itu suatu kecemaran, karena ia melanggar hak saudaranya laki-laki, dan mereka akan tidak beranak.', 'id', 'TB'),
  ('3', 'im', 'Imamat', 20, 22, 'Demikianlah kamu harus berpegang pada segala ketetapan-Ku dan segala peraturan-Ku serta melakukan semuanya itu, supaya jangan kamu dimuntahkan oleh negeri ke mana Aku membawa kamu untuk diam di sana.', 'id', 'TB'),
  ('3', 'im', 'Imamat', 20, 23, 'Janganlah kamu hidup menurut kebiasaan bangsa yang akan Kuhalau dari depanmu: karena semuanya itu telah dilakukan mereka, sehingga Aku muak melihat mereka.', 'id', 'TB'),
  ('3', 'im', 'Imamat', 20, 24, 'Tetapi kepadamu Aku telah berfirman: Kamulah yang akan menduduki tanah mereka dan Akulah yang akan memberikannya kepadamu menjadi milikmu, suatu negeri yang berlimpah-limpah susu dan madunya; Akulah TUHAN, Allahmu, yang memisahkan kamu dari bangsa-bangsa lain.', 'id', 'TB'),
  ('3', 'im', 'Imamat', 20, 25, 'Kamu harus membedakan binatang yang tidak haram dari yang haram, dan burung-burung yang haram dari yang tidak haram, supaya kamu jangan membuat dirimu jijik oleh binatang berkaki empat dan burung-burung dan oleh segala yang merayap di muka bumi, yang telah Kupisahkan supaya kamu haramkan.', 'id', 'TB'),
  ('3', 'im', 'Imamat', 20, 26, 'Kuduslah kamu bagi-Ku, sebab Aku ini, TUHAN, kudus dan Aku telah memisahkan kamu dari bangsa-bangsa lain, supaya kamu menjadi milik-Ku.', 'id', 'TB'),
  ('3', 'im', 'Imamat', 20, 27, 'Apabila seorang laki-laki atau perempuan dirasuk arwah atau roh peramal, pastilah mereka dihukum mati, yakni mereka harus dilontari dengan batu dan darah mereka tertimpa kepada mereka sendiri."', 'id', 'TB'),
  ('3', 'im', 'Imamat', 21, 1, 'TUHAN berfirman kepada Musa: "Berbicaralah kepada para imam, anak-anak Harun, dan katakan kepada mereka: Seorang imam janganlah menajiskan diri dengan orang mati di antara orang-orang sebangsanya,', 'id', 'TB'),
  ('3', 'im', 'Imamat', 21, 2, 'kecuali kalau yang mati itu adalah kerabatnya yang terdekat, yakni: ibunya, ayahnya, anaknya laki-laki atau perempuan, saudaranya laki-laki,', 'id', 'TB'),
  ('3', 'im', 'Imamat', 21, 3, 'saudaranya perempuan, yang masih perawan dan dekat kepadanya karena belum mempunyai suami, dengan mereka itu bolehlah ia menajiskan diri.', 'id', 'TB'),
  ('3', 'im', 'Imamat', 21, 4, 'Sebagai suami janganlah ia menajiskan diri di antara orang-orang sebangsanya dan dengan demikian melanggar kekudusannya.', 'id', 'TB'),
  ('3', 'im', 'Imamat', 21, 5, 'Janganlah mereka menggundul sebagian kepalanya, dan janganlah mereka mencukur tepi janggutnya, dan janganlah mereka menggoresi kulit tubuhnya.', 'id', 'TB'),
  ('3', 'im', 'Imamat', 21, 6, 'Mereka itu harus kudus bagi Allahnya dan janganlah mereka melanggar kekudusan nama Allahnya, karena merekalah yang mempersembahkan segala korban api-apian TUHAN, santapan Allah mereka, dan karena itu haruslah mereka kudus.', 'id', 'TB'),
  ('3', 'im', 'Imamat', 21, 7, 'Janganlah mereka mengambil seorang perempuan sundal atau perempuan yang sudah dirusak kesuciannya atau seorang perempuan yang telah diceraikan oleh suaminya, karena imam itu kudus bagi Allahnya.', 'id', 'TB'),
  ('3', 'im', 'Imamat', 21, 8, 'Dan kamu harus menganggap dia kudus, karena dialah yang mempersembahkan santapan Allahmu. Ia harus kudus bagimu, sebab Aku, TUHAN, yang menguduskan kamu adalah kudus.', 'id', 'TB'),
  ('3', 'im', 'Imamat', 21, 9, 'Apabila anak perempuan seorang imam membiarkan kehormatannya dilanggar dengan bersundal, maka ia melanggar kekudusan ayahnya, dan ia harus dibakar dengan api.', 'id', 'TB'),
  ('3', 'im', 'Imamat', 21, 10, 'Imam yang terbesar di antara saudara-saudaranya, yang sudah diurapi dengan menuangkan minyak urapan di atas kepalanya dan yang ditahbiskan dengan mengenakan kepadanya segala pakaian kudus, janganlah membiarkan rambutnya terurai dan janganlah ia mencabik pakaiannya.', 'id', 'TB'),
  ('3', 'im', 'Imamat', 21, 11, 'Janganlah ia dekat kepada semua mayat, bahkan janganlah ia menajiskan diri dengan mayat ayahnya atau ibunya.', 'id', 'TB'),
  ('3', 'im', 'Imamat', 21, 12, 'Janganlah ia keluar dari tempat kudus, supaya jangan dilanggarnya kekudusan tempat kudus Allahnya, karena minyak urapan Allahnya, yang menandakan bahwa ia telah dikhususkan, ada di atas kepalanya; Akulah TUHAN.', 'id', 'TB'),
  ('3', 'im', 'Imamat', 21, 13, 'Ia harus mengambil seorang perempuan yang masih perawan.', 'id', 'TB'),
  ('3', 'im', 'Imamat', 21, 14, 'Seorang janda atau perempuan yang telah diceraikan atau yang dirusak kesuciannya atau perempuan sundal, janganlah diambil, melainkan harus seorang perawan dari antara orang-orang sebangsanya,', 'id', 'TB'),
  ('3', 'im', 'Imamat', 21, 15, 'supaya jangan ia melanggar kekudusan keturunannya di antara orang-orang sebangsanya, sebab Akulah TUHAN, yang menguduskan dia."', 'id', 'TB'),
  ('3', 'im', 'Imamat', 21, 16, 'TUHAN berfirman kepada Musa:', 'id', 'TB'),
  ('3', 'im', 'Imamat', 21, 17, '"Katakanlah kepada Harun, begini: Setiap orang dari antara keturunanmu turun-temurun yang bercacat badannya, janganlah datang mendekat untuk mempersembahkan santapan Allahnya,', 'id', 'TB'),
  ('3', 'im', 'Imamat', 21, 18, 'karena setiap orang yang bercacat badannya tidak boleh datang mendekat: orang buta, orang timpang, orang yang bercacat mukanya, orang yang terlalu panjang anggotanya,', 'id', 'TB'),
  ('3', 'im', 'Imamat', 21, 19, 'orang yang patah kakinya atau tangannya,', 'id', 'TB'),
  ('3', 'im', 'Imamat', 21, 20, 'orang yang berbongkol atau yang kerdil badannya atau yang bular matanya, orang yang berkedal atau berkurap atau yang rusak buah pelirnya.', 'id', 'TB'),
  ('3', 'im', 'Imamat', 21, 21, 'Setiap orang dari keturunan imam Harun, yang bercacat badannya, janganlah datang untuk mempersembahkan segala korban api-apian TUHAN; karena badannya bercacat janganlah ia datang dekat untuk mempersembahkan santapan Allahnya.', 'id', 'TB'),
  ('3', 'im', 'Imamat', 21, 22, 'Mengenai santapan Allahnya, baik persembahan-persembahan maha kudus maupun persembahan-persembahan kudus boleh dimakannya.', 'id', 'TB'),
  ('3', 'im', 'Imamat', 21, 23, 'Hanya janganlah ia datang sampai ke tabir dan janganlah ia datang ke mezbah, karena badannya bercacat, supaya jangan dilanggarnya kekudusan seluruh tempat kudus-Ku, sebab Akulah TUHAN, yang menguduskan mereka."', 'id', 'TB'),
  ('3', 'im', 'Imamat', 21, 24, 'Demikianlah Musa menyampaikan firman itu kepada Harun serta anak-anaknya dan kepada semua orang Israel.', 'id', 'TB'),
  ('3', 'im', 'Imamat', 22, 1, 'TUHAN berfirman kepada Musa:', 'id', 'TB'),
  ('3', 'im', 'Imamat', 22, 2, '"Katakanlah kepada Harun dan anak-anaknya, supaya mereka berlaku hati-hati terhadap persembahan-persembahan kudus yang dikuduskan orang Israel bagi-Ku, agar jangan mereka melanggar kekudusan nama-Ku yang kudus; Akulah TUHAN.', 'id', 'TB'),
  ('3', 'im', 'Imamat', 22, 3, 'Katakanlah kepada mereka: Setiap orang di antara kamu turun-temurun, yakni dari antara segala keturunanmu yang datang mendekat kepada persembahan-persembahan kudus yang dikuduskan orang Israel bagi TUHAN, sedang ia dalam keadaan najis, maka orang itu akan dilenyapkan dari hadapan-Ku; Akulah TUHAN.', 'id', 'TB'),
  ('3', 'im', 'Imamat', 22, 4, 'Seseorang dari keturunan Harun yang sakit kusta atau yang mengeluarkan lelehan, janganlah memakan persembahan-persembahan kudus, sebelum ia menjadi tahir; dan orang yang kena kepada sesuatu yang najis karena orang mati atau orang yang tertumpah maninya', 'id', 'TB'),
  ('3', 'im', 'Imamat', 22, 5, 'atau orang yang kena kepada seekor binatang yang merayap yang menajiskan dia atau kepada salah seorang manusia yang menajiskan dia, dengan kenajisan apapun ia menjadi najis,', 'id', 'TB'),
  ('3', 'im', 'Imamat', 22, 6, 'orang yang kena kepada yang demikian itu menjadi najis sampai matahari terbenam dan janganlah ia makan dari persembahan-persembahan kudus, sebelum ia membasuh tubuhnya dengan air.', 'id', 'TB'),
  ('3', 'im', 'Imamat', 22, 7, 'Sesudah matahari terbenam, barulah ia menjadi tahir dan sesudah itu bolehlah ia makan dari persembahan-persembahan kudus itu, karena itulah yang menjadi makanannya.', 'id', 'TB'),
  ('3', 'im', 'Imamat', 22, 8, 'Janganlah ia makan bangkai atau sisa mangsa binatang buas, supaya jangan ia menjadi najis karenanya; Akulah TUHAN.', 'id', 'TB'),
  ('3', 'im', 'Imamat', 22, 9, 'Dan mereka harus tetap berpegang pada kewajibannya terhadap Aku, supaya dalam hal itu jangan mereka mendatangkan dosa kepada dirinya dan mati oleh karenanya, karena mereka telah melanggar kekudusan kewajiban itu; Akulah TUHAN, yang menguduskan mereka.', 'id', 'TB'),
  ('3', 'im', 'Imamat', 22, 10, 'Setiap orang awam janganlah memakan persembahan kudus; demikian juga pendatang yang tinggal pada imam ataupun orang upahan.', 'id', 'TB'),
  ('3', 'im', 'Imamat', 22, 11, 'Tetapi apabila seseorang telah dibeli oleh imam dengan uangnya menjadi budak beliannya, maka orang itu boleh turut memakannya, demikian juga mereka yang lahir di rumahnya.', 'id', 'TB'),
  ('3', 'im', 'Imamat', 22, 12, 'Apabila anak perempuan imam bersuamikan orang awam, janganlah ia makan persembahan khusus dari persembahan-persembahan kudus.', 'id', 'TB'),
  ('3', 'im', 'Imamat', 22, 13, 'Tetapi apabila perempuan itu menjadi janda atau diceraikan, dan ia tidak mempunyai anak, dan telah kembali ke rumah ayahnya seperti waktu ia masih gadis, maka ia boleh makan dari makanan ayahnya; tetapi setiap orang awam janganlah memakannya.', 'id', 'TB'),
  ('3', 'im', 'Imamat', 22, 14, 'Apabila seseorang dengan tidak sengaja memakan persembahan kudus, ia harus memberi gantinya kepada imam dengan menambah seperlima.', 'id', 'TB'),
  ('3', 'im', 'Imamat', 22, 15, 'Janganlah pada imam melanggar kekudusan persembahan-persembahan kudus orang Israel yang telah dikhususkan bagi TUHAN,', 'id', 'TB'),
  ('3', 'im', 'Imamat', 22, 16, 'karena dengan demikian mereka mendatangkan kepada orang Israel kesalahan yang harus ditebus, apabila mereka memakan persembahan-persembahan kudus mereka, sebab Akulah TUHAN, yang menguduskan mereka."', 'id', 'TB'),
  ('3', 'im', 'Imamat', 22, 17, 'TUHAN berfirman kepada Musa:', 'id', 'TB'),
  ('3', 'im', 'Imamat', 22, 18, '"Berbicaralah kepada Harun serta anak-anaknya dan kepada semua orang Israel dan katakan kepada mereka: Siapapun dari umat Israel dan dari orang asing di antara orang Israel yang mempersembahkan persembahannya, baik berupa sesuatu persembahan nazar maupun berupa sesuatu persembahan sukarela, yang hendak dipersembahkan mereka kepada TUHAN sebagai korban bakaran,', 'id', 'TB'),
  ('3', 'im', 'Imamat', 22, 19, 'maka supaya TUHAN berkenan akan kamu, haruslah persembahan itu tidak bercela dari lembu jantan, domba atau kambing.', 'id', 'TB'),
  ('3', 'im', 'Imamat', 22, 20, 'Segala yang bercacat badannya janganlah kamu persembahkan, karena dengan itu TUHAN tidak berkenan akan kamu.', 'id', 'TB'),
  ('3', 'im', 'Imamat', 22, 21, 'Juga apabila seseorang mempersembahkan kepada TUHAN korban keselamatan sebagai pembayar nazar khusus atau sebagai korban sukarela dari lembu atau kambing domba, maka korban itu haruslah yang tidak bercela, supaya TUHAN berkenan akan dia, janganlah badannya bercacat sedikitpun.', 'id', 'TB'),
  ('3', 'im', 'Imamat', 22, 22, 'Binatang yang buta atau yang patah tulang, yang luka atau yang berbisul, yang berkedal atau yang berkurap, semuanya itu janganlah kamu persembahkan kepada TUHAN dan binatang yang demikian janganlah kamu taruh sebagai korban api-apian bagi TUHAN ke atas mezbah.', 'id', 'TB'),
  ('3', 'im', 'Imamat', 22, 23, 'Tetapi seekor lembu atau domba yang terlalu panjang atau terlalu pendek anggotanya bolehlah kaupersembahkan sebagai korban sukarela, tetapi sebagai korban nazar TUHAN tidak akan berkenan akan binatang itu.', 'id', 'TB'),
  ('3', 'im', 'Imamat', 22, 24, 'Tetapi binatang yang buah pelirnya terjepit, ditumbuk, direnggut atau dikerat, janganlah kamu persembahkan kepada TUHAN; janganlah kamu berbuat demikian di negerimu.', 'id', 'TB'),
  ('3', 'im', 'Imamat', 22, 25, 'Juga dari tangan orang asing janganlah kamu persembahkan sesuatu dari semuanya itu sebagai santapan Allahmu, karena semuanya itu telah rusak dan bercacat badannya; TUHAN tidak akan berkenan akan kamu karena persembahan-persembahan itu."', 'id', 'TB'),
  ('3', 'im', 'Imamat', 22, 26, 'TUHAN berfirman kepada Musa:', 'id', 'TB'),
  ('3', 'im', 'Imamat', 22, 27, '"Apabila seekor anak lembu atau anak domba atau anak kambing dilahirkan, maka haruslah itu tinggal tujuh hari lamanya dengan induknya, tetapi sejak hari kedelapan dan seterusnya TUHAN berkenan akan binatang itu kalau dipersembahkan berupa korban api-apian bagi-Nya.', 'id', 'TB'),
  ('3', 'im', 'Imamat', 22, 28, 'Seekor lembu atau kambing atau domba janganlah kamu sembelih bersama dengan anaknya pada satu hari juga.', 'id', 'TB'),
  ('3', 'im', 'Imamat', 22, 29, 'Dan apabila kamu menyembelih korban syukur bagi TUHAN, kamu harus menyembelihnya sedemikian, hingga TUHAN berkenan akan kamu.', 'id', 'TB'),
  ('3', 'im', 'Imamat', 22, 30, 'Pada hari itu juga korban itu harus dimakan; janganlah kamu tinggalkan apa-apa dari padanya sampai pagi; Akulah TUHAN.', 'id', 'TB'),
  ('3', 'im', 'Imamat', 22, 31, 'Dengan demikian kamu harus berpegang pada perintah-Ku dan melakukannya; Akulah TUHAN.', 'id', 'TB'),
  ('3', 'im', 'Imamat', 22, 32, 'Janganlah melanggar kekudusan nama-Ku yang kudus, supaya Aku dikuduskan di tengah-tengah orang Israel, sebab Akulah TUHAN, yang menguduskan kamu,', 'id', 'TB'),
  ('3', 'im', 'Imamat', 22, 33, 'yang membawa kamu keluar dari tanah Mesir, supaya Aku menjadi Allahmu; Akulah TUHAN."', 'id', 'TB'),
  ('3', 'im', 'Imamat', 23, 1, 'TUHAN berfirman kepada Musa:', 'id', 'TB'),
  ('3', 'im', 'Imamat', 23, 2, '"Berbicaralah kepada orang Israel dan katakan kepada mereka: Hari-hari raya yang ditetapkan TUHAN yang harus kamu maklumkan sebagai waktu pertemuan kudus, waktu perayaan yang Kutetapkan, adalah yang berikut.', 'id', 'TB'),
  ('3', 'im', 'Imamat', 23, 3, 'Enam hari lamanya boleh dilakukan pekerjaan, tetapi pada hari yang ketujuh haruslah ada sabat, hari perhentian penuh, yakni hari pertemuan kudus; janganlah kamu melakukan sesuatu pekerjaan; itulah sabat bagi TUHAN di segala tempat kediamanmu.', 'id', 'TB'),
  ('3', 'im', 'Imamat', 23, 4, 'Inilah hari-hari raya yang ditetapkan TUHAN, hari-hari pertemuan kudus, yang harus kamu maklumkan masing-masing pada waktunya yang tetap.', 'id', 'TB'),
  ('3', 'im', 'Imamat', 23, 5, 'Dalam bulan yang pertama, pada tanggal empat belas bulan itu, pada waktu senja, ada Paskah bagi TUHAN.', 'id', 'TB'),
  ('3', 'im', 'Imamat', 23, 6, 'Dan pada hari yang kelima belas bulan itu ada hari raya Roti Tidak Beragi bagi TUHAN; tujuh hari lamanya kamu harus makan roti yang tidak beragi.', 'id', 'TB'),
  ('3', 'im', 'Imamat', 23, 7, 'Pada hari yang pertama kamu harus mengadakan pertemuan kudus, janganlah kamu melakukan sesuatu pekerjaan berat.', 'id', 'TB'),
  ('3', 'im', 'Imamat', 23, 8, 'Kamu harus mempersembahkan korban api-apian kepada TUHAN tujuh hari lamanya; pada hari yang ketujuh haruslah ada pertemuan kudus, janganlah kamu melakukan sesuatu pekerjaan berat."', 'id', 'TB'),
  ('3', 'im', 'Imamat', 23, 9, 'TUHAN berfirman kepada Musa:', 'id', 'TB'),
  ('3', 'im', 'Imamat', 23, 10, '"Berbicaralah kepada orang Israel dan katakan kepada mereka: Apabila kamu sampai ke negeri yang akan Kuberikan kepadamu, dan kamu menuai hasilnya, maka kamu harus membawa seberkas hasil pertama dari penuaianmu kepada imam,', 'id', 'TB'),
  ('3', 'im', 'Imamat', 23, 11, 'dan imam itu haruslah mengunjukkan berkas itu di hadapan TUHAN, supaya TUHAN berkenan akan kamu. Imam harus mengunjukkannya pada hari sesudah sabat itu.', 'id', 'TB'),
  ('3', 'im', 'Imamat', 23, 12, 'Pada hari kamu mengunjukkan berkas itu kamu harus mempersembahkan seekor domba berumur setahun yang tidak bercela, sebagai korban bakaran bagi TUHAN,', 'id', 'TB'),
  ('3', 'im', 'Imamat', 23, 13, 'serta dengan korban sajiannya dari dua persepuluh efa tepung yang terbaik, diolah dengan minyak, sebagai korban api-apian bagi TUHAN yakni bau yang menyenangkan, serta dengan korban curahannya dari seperempat hin anggur.', 'id', 'TB'),
  ('3', 'im', 'Imamat', 23, 14, 'Sampai pada hari itu juga janganlah kamu makan roti, atau bertih gandum atau gandum baru, sampai kamu telah membawa persembahan Allahmu; itulah suatu ketetapan untuk selama-lamanya bagi kamu turun-temurun di segala tempat kediamanmu.', 'id', 'TB'),
  ('3', 'im', 'Imamat', 23, 15, 'Kemudian kamu harus menghitung, mulai dari hari sesudah sabat itu, yaitu waktu kamu membawa berkas persembahan unjukan, harus ada genap tujuh minggu;', 'id', 'TB'),
  ('3', 'im', 'Imamat', 23, 16, 'sampai pada hari sesudah sabat yang ketujuh kamu harus hitung lima puluh hari; lalu kamu harus mempersembahkan korban sajian yang baru kepada TUHAN.', 'id', 'TB'),
  ('3', 'im', 'Imamat', 23, 17, 'Dari tempat kediamanmu kamu harus membawa dua buah roti unjukan yang harus dibuat dari dua persepuluh efa tepung yang terbaik dan yang dibakar sesudah dicampur dengan ragi sebagai hulu hasil bagi TUHAN.', 'id', 'TB'),
  ('3', 'im', 'Imamat', 23, 18, 'Beserta roti itu kamu harus mempersembahkan tujuh ekor domba berumur setahun yang tidak bercela dan seekor lembu jantan muda dan dua ekor domba jantan; semuanya itu haruslah menjadi korban bakaran bagi TUHAN, serta dengan korban sajiannya dan korban-korban curahannya, suatu korban api-apian yang baunya menyenangkan bagi TUHAN.', 'id', 'TB'),
  ('3', 'im', 'Imamat', 23, 19, 'Kemudian kamu harus mempersembahkan seekor kambing jantan sebagai korban penghapus dosa, dan dua ekor domba yang berumur setahun sebagai korban keselamatan.', 'id', 'TB'),
  ('3', 'im', 'Imamat', 23, 20, 'Imam harus mengunjukkan semuanya beserta roti hulu hasil itu sebagai persembahan unjukan di hadapan TUHAN, beserta kedua ekor domba itu. Semuanya itu haruslah menjadi persembahan kudus bagi TUHAN dan adalah bagian imam.', 'id', 'TB'),
  ('3', 'im', 'Imamat', 23, 21, 'Pada hari itu juga kamu harus mengumumkan hari raya dan kamu harus mengadakan pertemuan kudus, janganlah kamu melakukan sesuatu pekerjaan berat; itulah suatu ketetapan untuk selama-lamanya di segala tempat kediamanmu turun-temurun.', 'id', 'TB'),
  ('3', 'im', 'Imamat', 23, 22, 'Pada waktu kamu menuai hasil tanahmu, janganlah kausabit ladangmu habis-habis sampai ke tepinya dan janganlah kaupungut apa yang ketinggalan dari penuaianmu, semuanya itu harus kautinggalkan bagi orang miskin dan bagi orang asing; Akulah TUHAN, Allahmu."', 'id', 'TB'),
  ('3', 'im', 'Imamat', 23, 23, 'TUHAN berfirman kepada Musa:', 'id', 'TB'),
  ('3', 'im', 'Imamat', 23, 24, '"Katakanlah kepada orang Israel, begini: Dalam bulan yang ketujuh, pada tanggal satu bulan itu, kamu harus mengadakan hari perhentian penuh yang diperingati dengan meniup serunai, yakni hari pertemuan kudus.', 'id', 'TB'),
  ('3', 'im', 'Imamat', 23, 25, 'Janganlah kamu melakukan sesuatu pekerjaan berat dan kamu harus mempersembahkan korban api-apian kepada TUHAN."', 'id', 'TB'),
  ('3', 'im', 'Imamat', 23, 26, 'TUHAN berfirman kepada Musa:', 'id', 'TB'),
  ('3', 'im', 'Imamat', 23, 27, '"Akan tetapi pada tanggal sepuluh bulan yang ketujuh itu ada hari Pendamaian; kamu harus mengadakan pertemuan kudus dan harus merendahkan diri dengan berpuasa dan mempersembahkan korban api-apian kepada TUHAN.', 'id', 'TB'),
  ('3', 'im', 'Imamat', 23, 28, 'Pada hari itu janganlah kamu melakukan sesuatu pekerjaan; itulah hari Pendamaian untuk mengadakan pendamaian bagimu di hadapan TUHAN, Allahmu.', 'id', 'TB'),
  ('3', 'im', 'Imamat', 23, 29, 'Karena setiap orang yang pada hari itu tidak merendahkan diri dengan berpuasa, haruslah dilenyapkan dari antara orang-orang sebangsanya.', 'id', 'TB'),
  ('3', 'im', 'Imamat', 23, 30, 'Setiap orang yang melakukan sesuatu pekerjaan pada hari itu, orang itu akan Kubinasakan dari tengah-tengah bangsanya.', 'id', 'TB'),
  ('3', 'im', 'Imamat', 23, 31, 'Janganlah kamu melakukan sesuatu pekerjaan; itulah suatu ketetapan untuk selama-lamanya bagimu turun-temurun di segala tempat kediamanmu.', 'id', 'TB'),
  ('3', 'im', 'Imamat', 23, 32, 'Itu harus menjadi suatu sabat, hari perhentian penuh bagimu, dan kamu harus merendahkan diri dengan berpuasa. Mulai pada malam tanggal sembilan bulan itu, dari matahari terbenam sampai matahari terbenam, kamu harus merayakan sabatmu."', 'id', 'TB'),
  ('3', 'im', 'Imamat', 23, 33, 'TUHAN berfirman kepada Musa:', 'id', 'TB'),
  ('3', 'im', 'Imamat', 23, 34, '"Katakanlah kepada orang Israel, begini: Pada hari yang kelima belas bulan yang ketujuh itu ada hari raya Pondok Daun bagi TUHAN tujuh hari lamanya.', 'id', 'TB'),
  ('3', 'im', 'Imamat', 23, 35, 'Pada hari yang pertama haruslah ada pertemuan kudus, janganlah kamu melakukan sesuatu pekerjaan berat.', 'id', 'TB'),
  ('3', 'im', 'Imamat', 23, 36, 'Tujuh hari lamanya kamu harus mempersembahkan korban api-apian kepada TUHAN, dan pada hari yang kedelapan kamu harus mengadakan pertemuan kudus dan mempersembahkan korban api-apian kepada TUHAN. Itulah hari raya perkumpulan, janganlah kamu melakukan sesuatu pekerjaan berat.', 'id', 'TB'),
  ('3', 'im', 'Imamat', 23, 37, 'Itulah hari-hari raya yang ditetapkan TUHAN, yang harus kamu maklumkan sebagai hari pertemuan kudus untuk mempersembahkan korban api-apian kepada TUHAN, yaitu korban bakaran dan korban sajian, korban sembelihan dan korban-korban curahan, setiap hari sebanyak yang ditetapkan untuk hari itu,', 'id', 'TB'),
  ('3', 'im', 'Imamat', 23, 38, 'belum termasuk hari-hari Sabat TUHAN dan belum termasuk persembahan-perse atau segala korban nazarmu atau segala korban sukarelamu, yang kamu hendak persembahkan kepada TUHAN.', 'id', 'TB'),
  ('3', 'im', 'Imamat', 23, 39, 'Akan tetapi pada hari yang kelima belas bulan yang ketujuh itu pada waktu mengumpulkan hasil tanahmu, kamu harus mengadakan perayaan bagi TUHAN tujuh hari lamanya; pada hari yang pertama haruslah ada perhentian penuh dan juga pada hari yang kedelapan harus ada perhentian penuh.', 'id', 'TB'),
  ('3', 'im', 'Imamat', 23, 40, 'Pada hari yang pertama kamu harus mengambil buah-buah dari pohon-pohon yang elok, pelepah-pelepah pohon-pohon korma, ranting-ranting dari pohon-pohon yang rimbun dan dari pohon-pohon gandarusa dan kamu harus bersukaria di hadapan TUHAN, Allahmu, tujuh hari lamanya.', 'id', 'TB'),
  ('3', 'im', 'Imamat', 23, 41, 'Kamu harus merayakannya sebagai perayaan bagi TUHAN tujuh hari lamanya dalam setahun; itulah suatu ketetapan untuk selama-lamanya bagimu turun-temurun. Dalam bulan yang ketujuh kamu harus merayakannya.', 'id', 'TB'),
  ('3', 'im', 'Imamat', 23, 42, 'Di dalam pondok-pondok daun kamu harus tinggal tujuh hari lamanya, setiap orang asli di Israel haruslah tinggal di dalam pondok-pondok daun,', 'id', 'TB'),
  ('3', 'im', 'Imamat', 23, 43, 'supaya diketahui oleh keturunanmu, bahwa Aku telah menyuruh orang Israel tinggal di dalam pondok-pondok selama Aku menuntun mereka sesudah keluar dari tanah Mesir, Akulah TUHAN, Allahmu."', 'id', 'TB'),
  ('3', 'im', 'Imamat', 23, 44, 'Demikianlah Musa menyampaikan kepada orang Israel firman tentang hari-hari raya yang ditetapkan TUHAN.', 'id', 'TB'),
  ('3', 'im', 'Imamat', 24, 1, 'TUHAN berfirman kepada Musa:', 'id', 'TB'),
  ('3', 'im', 'Imamat', 24, 2, '"Perintahkanlah kepada orang Israel, supaya mereka membawa kepadamu minyak zaitun tumbuk yang tulen untuk lampu, supaya lampu dapat dipasang dan tetap menyala.', 'id', 'TB'),
  ('3', 'im', 'Imamat', 24, 3, 'Harun harus tetap mengatur lampu-lampu itu di depan tabir yang menutupi tabut hukum, di dalam Kemah Pertemuan, dari petang sampai pagi, di hadapan TUHAN. Itulah suatu ketetapan untuk selama-lamanya bagimu turun-temurun.', 'id', 'TB'),
  ('3', 'im', 'Imamat', 24, 4, 'Di atas kandil dari emas murni haruslah tetap diaturnya lampu-lampu itu di hadapan TUHAN."', 'id', 'TB'),
  ('3', 'im', 'Imamat', 24, 5, '"Engkau harus mengambil tepung yang terbaik dan membakar dua belas roti bundar dari padanya, setiap roti bundar harus dibuat dari dua persepuluh efa;', 'id', 'TB'),
  ('3', 'im', 'Imamat', 24, 6, 'engkau harus mengaturnya menjadi dua susun, enam buah sesusun, di atas meja dari emas murni itu, di hadapan TUHAN.', 'id', 'TB'),
  ('3', 'im', 'Imamat', 24, 7, 'Engkau harus membubuh kemenyan tulen di atas tiap-tiap susun; kemenyan itulah yang harus menjadi bagian ingat-ingatan roti itu, yakni suatu korban api-apian bagi TUHAN.', 'id', 'TB'),
  ('3', 'im', 'Imamat', 24, 8, 'Setiap hari Sabat ia harus tetap mengaturnya di hadapan TUHAN; itulah dari pihak orang Israel suatu kewajiban perjanjian untuk selama-lamanya.', 'id', 'TB'),
  ('3', 'im', 'Imamat', 24, 9, 'Roti itu teruntuk bagi Harun serta anak-anaknya dan mereka harus memakannya di suatu tempat yang kudus; itulah bagian maha kudus baginya dari segala korban api-apian TUHAN; itulah suatu ketetapan untuk selama-lamanya."', 'id', 'TB'),
  ('3', 'im', 'Imamat', 24, 10, 'Pada suatu hari datanglah seorang laki-laki, ibunya seorang Israel sedang ayahnya seorang Mesir, di tengah-tengah perkemahan orang Israel; dan orang itu berkelahi dengan seorang Israel di perkemahan.', 'id', 'TB'),
  ('3', 'im', 'Imamat', 24, 11, 'Anak perempuan Israel itu menghujat nama TUHAN dengan mengutuk, lalu dibawalah ia kepada Musa. Nama ibunya ialah Selomit binti Dibri dari suku Dan.', 'id', 'TB'),
  ('3', 'im', 'Imamat', 24, 12, 'Ia dimasukkan dalam tahanan untuk menantikan keputusan sesuai dengan firman TUHAN.', 'id', 'TB'),
  ('3', 'im', 'Imamat', 24, 13, 'Lalu berfirmanlah TUHAN kepada Musa:', 'id', 'TB'),
  ('3', 'im', 'Imamat', 24, 14, '"Bawalah orang yang mengutuk itu ke luar perkemahan dan semua orang yang mendengar haruslah meletakkan tangannya ke atas kepala orang itu, sesudahnya haruslah seluruh jemaah itu melontari dia dengan batu.', 'id', 'TB'),
  ('3', 'im', 'Imamat', 24, 15, 'Engkau harus mengatakan kepada orang Israel, begini: Setiap orang yang mengutuki Allah harus menanggung kesalahannya sendiri.', 'id', 'TB'),
  ('3', 'im', 'Imamat', 24, 16, 'Siapa yang menghujat nama TUHAN, pastilah ia dihukum mati dan dilontari dengan batu oleh seluruh jemaah itu. Baik orang asing maupun orang Israel asli, bila ia menghujat nama TUHAN, haruslah dihukum mati.', 'id', 'TB'),
  ('3', 'im', 'Imamat', 24, 17, 'Juga apabila seseorang membunuh seorang manusia, pastilah ia dihukum mati.', 'id', 'TB'),
  ('3', 'im', 'Imamat', 24, 18, 'Tetapi siapa yang memukul mati seekor ternak, harus membayar gantinya, seekor ganti seekor.', 'id', 'TB'),
  ('3', 'im', 'Imamat', 24, 19, 'Apabila seseorang membuat orang sesamanya bercacat, maka seperti yang telah dilakukannya, begitulah harus dilakukan kepadanya:', 'id', 'TB'),
  ('3', 'im', 'Imamat', 24, 20, 'patah ganti patah, mata ganti mata, gigi ganti gigi; seperti dibuatnya orang lain bercacat, begitulah harus dibuat kepadanya.', 'id', 'TB'),
  ('3', 'im', 'Imamat', 24, 21, 'Siapa yang memukul mati seekor ternak, ia harus membayar gantinya, tetapi siapa yang membunuh seorang manusia, ia harus dihukum mati.', 'id', 'TB'),
  ('3', 'im', 'Imamat', 24, 22, 'Satu hukum berlaku bagi kamu, baik bagi orang asing maupun bagi orang Israel asli, sebab Akulah TUHAN, Allahmu."', 'id', 'TB'),
  ('3', 'im', 'Imamat', 24, 23, 'Demikianlah Musa menyampaikan firman itu kepada orang Israel, lalu dibawalah orang yang mengutuk itu ke luar perkemahan, dan dilontarilah dia dengan batu. Maka orang Israel melakukan seperti yang diperintahkan TUHAN kepada Musa.', 'id', 'TB'),
  ('3', 'im', 'Imamat', 25, 1, 'TUHAN berfirman kepada Musa di gunung Sinai:', 'id', 'TB'),
  ('3', 'im', 'Imamat', 25, 2, '"Berbicaralah kepada orang Israel dan katakan kepada mereka: Apabila kamu telah masuk ke negeri yang akan Kuberikan kepadamu, maka tanah itu harus mendapat perhentian sebagai sabat bagi TUHAN.', 'id', 'TB'),
  ('3', 'im', 'Imamat', 25, 3, 'Enam tahun lamanya engkau harus menaburi ladangmu, dan enam tahun lamanya engkau harus merantingi kebun anggurmu dan mengumpulkan hasil tanah itu,', 'id', 'TB'),
  ('3', 'im', 'Imamat', 25, 4, 'tetapi pada tahun yang ketujuh haruslah ada bagi tanah itu suatu sabat, masa perhentian penuh, suatu sabat bagi TUHAN. Ladangmu janganlah kautaburi dan kebun anggurmu janganlah kaurantingi.', 'id', 'TB'),
  ('3', 'im', 'Imamat', 25, 5, 'Dan apa yang tumbuh sendiri dari penuaianmu itu, janganlah kautuai dan buah anggur dari pokok anggurmu yang tidak dirantingi, janganlah kaupetik. Tahun itu harus menjadi tahun perhentian penuh bagi tanah itu.', 'id', 'TB'),
  ('3', 'im', 'Imamat', 25, 6, 'Hasil tanah selama sabat itu haruslah menjadi makanan bagimu, yakni bagimu sendiri, bagi budakmu laki-laki, bagi budakmu perempuan, bagi orang upahan dan bagi orang asing di antaramu, yang semuanya tinggal padamu.', 'id', 'TB'),
  ('3', 'im', 'Imamat', 25, 7, 'Juga bagi ternakmu, dan bagi binatang liar yang ada di tanahmu, segala hasil tanah itu menjadi makanannya.', 'id', 'TB'),
  ('3', 'im', 'Imamat', 25, 8, 'Selanjutnya engkau harus menghitung tujuh tahun sabat, yakni tujuh kali tujuh tahun; sehingga masa tujuh tahun sabat itu sama dengan empat puluh sembilan tahun.', 'id', 'TB'),
  ('3', 'im', 'Imamat', 25, 9, 'Lalu engkau harus memperdengarkan bunyi sangkakala di mana-mana dalam bulan yang ketujuh pada tanggal sepuluh bulan itu; pada hari raya Pendamaian kamu harus memperdengarkan bunyi sangkakala itu di mana-mana di seluruh negerimu.', 'id', 'TB'),
  ('3', 'im', 'Imamat', 25, 10, 'Kamu harus menguduskan tahun yang kelima puluh, dan memaklumkan kebebasan di negeri itu bagi segenap penduduknya. Itu harus menjadi tahun Yobel bagimu, dan kamu harus masing-masing pulang ke tanah miliknya dan kepada kaumnya.', 'id', 'TB'),
  ('3', 'im', 'Imamat', 25, 11, 'Tahun yang kelima puluh itu harus menjadi tahun Yobel bagimu, jangan kamu menabur, dan apa yang tumbuh sendiri dalam tahun itu jangan kamu tuai, dan pokok anggur yang tidak dirantingi jangan kamu petik buahnya.', 'id', 'TB'),
  ('3', 'im', 'Imamat', 25, 12, 'Karena tahun itu adalah tahun Yobel, haruslah itu kudus bagimu; hasil tahun itu yang hendak kamu makan harus diambil dari ladang.', 'id', 'TB'),
  ('3', 'im', 'Imamat', 25, 13, 'Dalam tahun Yobel itu kamu harus masing-masing pulang ke tanah miliknya.', 'id', 'TB'),
  ('3', 'im', 'Imamat', 25, 14, 'Apabila kamu menjual sesuatu kepada sesamamu atau membeli dari padanya, janganlah kamu merugikan satu sama lain.', 'id', 'TB'),
  ('3', 'im', 'Imamat', 25, 15, 'Apabila engkau membeli dari sesamamu haruslah menurut jumlah tahun sesudah tahun Yobel, dan apabila ia menjual kepadamu haruslah menurut jumlah tahun panen.', 'id', 'TB'),
  ('3', 'im', 'Imamat', 25, 16, 'Makin besar jumlah tahun itu, makin besarlah pembeliannya, dan makin kecil jumlah tahun itu, makin kecillah pembeliannya, karena jumlah panenlah yang dijualnya kepadamu.', 'id', 'TB'),
  ('3', 'im', 'Imamat', 25, 17, 'Janganlah kamu merugikan satu sama lain, tetapi engkau harus takut akan Allahmu, sebab Akulah TUHAN, Allahmu.', 'id', 'TB'),
  ('3', 'im', 'Imamat', 25, 18, 'Demikianlah kamu harus melakukan ketetapan-Ku dan tetap berpegang pada peraturan-Ku serta melakukannya, maka kamu akan diam di tanahmu dengan aman tenteram.', 'id', 'TB'),
  ('3', 'im', 'Imamat', 25, 19, 'Tanah itu akan memberi hasilnya, dan kamu akan makan sampai kenyang dan diam di sana dengan aman tenteram.', 'id', 'TB'),
  ('3', 'im', 'Imamat', 25, 20, 'Apabila kamu bertanya: Apakah yang akan kami makan dalam tahun yang ketujuh itu, bukankah kami tidak boleh menabur dan tidak boleh mengumpulkan hasil tanah kami?', 'id', 'TB'),
  ('3', 'im', 'Imamat', 25, 21, 'Maka Aku akan memerintahkan berkat-Ku kepadamu dalam tahun yang keenam, supaya diberinya hasil untuk tiga tahun.', 'id', 'TB'),
  ('3', 'im', 'Imamat', 25, 22, 'Dalam tahun yang kedelapan kamu akan menabur, tetapi kamu akan makan dari hasil yang lama sampai kepada tahun yang kesembilan, sampai masuk hasilnya, kamu akan memakan yang lama."', 'id', 'TB'),
  ('3', 'im', 'Imamat', 25, 23, '"Tanah jangan dijual mutlak, karena Akulah pemilik tanah itu, sedang kamu adalah orang asing dan pendatang bagi-Ku.', 'id', 'TB'),
  ('3', 'im', 'Imamat', 25, 24, 'Di seluruh tanah milikmu haruslah kamu memberi hak menebus tanah.', 'id', 'TB'),
  ('3', 'im', 'Imamat', 25, 25, 'Apabila saudaramu jatuh miskin, sehingga harus menjual sebagian dari miliknya, maka seorang kaumnya yang berhak menebus, yakni kaumnya yang terdekat harus datang dan menebus yang telah dijual saudaranya itu.', 'id', 'TB'),
  ('3', 'im', 'Imamat', 25, 26, 'Apabila seseorang tidak mempunyai penebus, tetapi kemudian ia mampu, sehingga didapatnya yang perlu untuk menebus miliknya itu,', 'id', 'TB'),
  ('3', 'im', 'Imamat', 25, 27, 'maka ia harus memasukkan tahun-tahun sesudah penjualannya itu dalam perhitungan, dan kelebihannya haruslah dikembalikannya kepada orang yang membeli dari padanya, supaya ia boleh pulang ke tanah miliknya.', 'id', 'TB'),
  ('3', 'im', 'Imamat', 25, 28, 'Tetapi jikalau ia tidak mampu untuk mengembalikannya kepadanya, maka yang telah dijualnya itu tetap di tangan orang yang membelinya sampai kepada tahun Yobel; dalam tahun Yobel tanah itu akan bebas, dan orang itu boleh pulang ke tanah miliknya."', 'id', 'TB'),
  ('3', 'im', 'Imamat', 25, 29, '"Apabila seseorang menjual rumah tempat tinggal di suatu kota yang berpagar tembok, maka hak menebus hanya berlaku selama setahun mulai dari hari penjualannya; hak menebus berlaku hanya satu tahun.', 'id', 'TB'),
  ('3', 'im', 'Imamat', 25, 30, 'Tetapi jikalau rumah itu tidak ditebus dalam jangka waktu setahun itu, rumah itu secara mutlak menjadi milik si pembeli turun temurun; dalam tahun Yobel rumah itu tidaklah bebas.', 'id', 'TB'),
  ('3', 'im', 'Imamat', 25, 31, 'Tetapi rumah-rumah di desa-desa yang tidak dikelilingi pagar tembok haruslah dianggap sama dengan ladang-ladang di negeri itu, atasnya harus ada hak menebus dan dalam tahun Yobel rumah itu harus bebas.', 'id', 'TB'),
  ('3', 'im', 'Imamat', 25, 32, 'Mengenai rumah-rumah di kota-kota orang Lewi, hak menebus rumah-rumah itu ada pada orang-orang Lewi untuk selama-lamanya.', 'id', 'TB'),
  ('3', 'im', 'Imamat', 25, 33, 'Sekalipun dari antara orang Lewi yang melakukan penebusan, tetapi rumah yang terjual di kota miliknya itu haruslah bebas dalam tahun Yobel, karena segala rumah di kota-kota orang Lewi adalah milik mereka masing-masing di tengah-tengah orang Israel.', 'id', 'TB'),
  ('3', 'im', 'Imamat', 25, 34, 'Dan padang penggembalaan sekitar kota-kota mereka janganlah dijual, karena itu milik mereka untuk selama-lamanya."', 'id', 'TB'),
  ('3', 'im', 'Imamat', 25, 35, '"Apabila saudaramu jatuh miskin, sehingga tidak sanggup bertahan di antaramu, maka engkau harus menyokong dia sebagai orang asing dan pendatang, supaya ia dapat hidup di antaramu.', 'id', 'TB'),
  ('3', 'im', 'Imamat', 25, 36, 'Janganlah engkau mengambil bunga uang atau riba dari padanya, melainkan engkau harus takut akan Allahmu, supaya saudaramu dapat hidup di antaramu.', 'id', 'TB'),
  ('3', 'im', 'Imamat', 25, 37, 'Janganlah engkau memberi uangmu kepadanya dengan meminta bunga, juga makananmu janganlah kauberikan dengan meminta riba.', 'id', 'TB'),
  ('3', 'im', 'Imamat', 25, 38, 'Akulah TUHAN, Allahmu, yang membawa kamu keluar dari tanah Mesir, untuk memberikan kepadamu tanah Kanaan, supaya Aku menjadi Allahmu.', 'id', 'TB'),
  ('3', 'im', 'Imamat', 25, 39, 'Apabila saudaramu jatuh miskin di antaramu, sehingga menyerahkan dirinya kepadamu, maka janganlah memperbudak dia.', 'id', 'TB'),
  ('3', 'im', 'Imamat', 25, 40, 'Sebagai orang upahan dan sebagai pendatang ia harus tinggal di antaramu; sampai kepada tahun Yobel ia harus bekerja padamu.', 'id', 'TB'),
  ('3', 'im', 'Imamat', 25, 41, 'Kemudian ia harus diizinkan keluar dari padamu, ia bersama-sama anak-anaknya, lalu pulang kembali kepada kaumnya dan ia boleh pulang ke tanah milik nenek moyangnya.', 'id', 'TB'),
  ('3', 'im', 'Imamat', 25, 42, 'Karena mereka itu hamba-hamba-Ku yang Kubawa keluar dari tanah Mesir, janganlah mereka itu dijual, secara orang menjual budak.', 'id', 'TB'),
  ('3', 'im', 'Imamat', 25, 43, 'Janganlah engkau memerintah dia dengan kejam, melainkan engkau harus takut akan Allahmu.', 'id', 'TB'),
  ('3', 'im', 'Imamat', 25, 44, 'Tetapi budakmu laki-laki atau perempuan yang boleh kaumiliki adalah dari antara bangsa-bangsa yang di sekelilingmu; hanya dari antara merekalah kamu boleh membeli budak laki-laki dan perempuan.', 'id', 'TB'),
  ('3', 'im', 'Imamat', 25, 45, 'Juga dari antara anak-anak pendatang yang tinggal di antaramu boleh kamu membelinya dan dari antara kaum mereka yang tinggal di antaramu, yang dilahirkan di negerimu. Orang-orang itu boleh menjadi milikmu.', 'id', 'TB'),
  ('3', 'im', 'Imamat', 25, 46, 'Kamu harus membagikan mereka sebagai milik pusaka kepada anak-anakmu yang kemudian, supaya diwarisi sebagai milik; kamu harus memperbudakkan mereka untuk selama-lamanya, tetapi atas saudara-saudaramu orang-orang Israel, janganlah memerintah dengan kejam yang satu sama yang lain.', 'id', 'TB'),
  ('3', 'im', 'Imamat', 25, 47, 'Apabila seorang asing atau seorang pendatang di antaramu telah menjadi mampu, sedangkan saudaramu yang tinggal padanya jatuh miskin, sehingga menyerahkan dirinya kepada orang asing atau pendatang yang di antaramu itu atau kepada seorang yang berasal dari kaum orang asing,', 'id', 'TB'),
  ('3', 'im', 'Imamat', 25, 48, 'maka sesudah ia menyerahkan dirinya, ia berhak ditebus, yakni seorang dari antara saudara-saudaranya boleh menebus dia,', 'id', 'TB'),
  ('3', 'im', 'Imamat', 25, 49, 'atau saudara ayahnya atau anak laki-laki saudara ayahnya atau seorang kerabatnya yang terdekat dari kaumnya atau kalau ia telah mampu, ia sendiri berhak menebus dirinya.', 'id', 'TB'),
  ('3', 'im', 'Imamat', 25, 50, 'Bersama-sama dengan si pembelinya ia harus membuat perhitungan, mulai dari tahun ia menyerahkan dirinya kepada orang itu sampai kepada tahun Yobel, dan harga penjualan dirinya haruslah ditentukan menurut jumlah tahun-tahun itu; masa ia tinggal pada orang itu haruslah dihitung seperti masa kerja orang upahan.', 'id', 'TB'),
  ('3', 'im', 'Imamat', 25, 51, 'Jikalau jumlah tahun itu masih besar, maka dari harga pembeliannya harus dikembalikan sebagai penebus dirinya menurut jumlah tahun itu.', 'id', 'TB'),
  ('3', 'im', 'Imamat', 25, 52, 'Jika waktu yang masih tinggal sampai kepada tahun Yobel sedikit lagi saja, maka ia harus membuat perhitungan dengan orang itu; menurut jumlah tahun itulah ia harus membayar uang tebusan dirinya.', 'id', 'TB'),
  ('3', 'im', 'Imamat', 25, 53, 'Demikianlah ia harus tinggal padanya sebagai orang upahan dari tahun ke tahun. Janganlah ia diperintah dengan kejam oleh orang itu di depan matamu.', 'id', 'TB'),
  ('3', 'im', 'Imamat', 25, 54, 'Tetapi jikalau ia tidak ditebus dengan cara demikian, maka ia harus diizinkan keluar dalam tahun Yobel, ia bersama-sama anak-anaknya.', 'id', 'TB'),
  ('3', 'im', 'Imamat', 25, 55, 'Karena pada-Kulah orang Israel menjadi hamba; mereka itu adalah hamba-hamba-Ku yang Kubawa keluar dari tanah Mesir; Akulah TUHAN, Allahmu."', 'id', 'TB'),
  ('3', 'im', 'Imamat', 26, 1, '"Janganlah kamu membuat berhala bagimu, dan patung atau tugu berhala janganlah kamu dirikan bagimu; juga batu berukir janganlah kamu tempatkan di negerimu untuk sujud menyembah kepadanya, sebab Akulah TUHAN, Allahmu.', 'id', 'TB'),
  ('3', 'im', 'Imamat', 26, 2, 'Kamu harus memelihara hari-hari Sabat-Ku dan menghormati tempat kudus-Ku, Akulah TUHAN.', 'id', 'TB'),
  ('3', 'im', 'Imamat', 26, 3, 'Jikalau kamu hidup menurut ketetapan-Ku dan tetap berpegang pada perintah-Ku serta melakukannya,', 'id', 'TB'),
  ('3', 'im', 'Imamat', 26, 4, 'maka Aku akan memberi kamu hujan pada masanya, sehingga tanah itu memberi hasilnya dan pohon-pohonan di ladangmu akan memberi buahnya.', 'id', 'TB'),
  ('3', 'im', 'Imamat', 26, 5, 'Lamanya musim mengirik bagimu akan sampai kepada musim memetik buah anggur dan lamanya musim memetik buah anggur akan sampai kepada musim menabur. Kamu akan makan makananmu sampai kenyang dan diam di negerimu dengan aman tenteram.', 'id', 'TB'),
  ('3', 'im', 'Imamat', 26, 6, 'Dan Aku akan memberi damai sejahtera di dalam negeri itu, sehingga kamu akan berbaring dengan tidak dikejutkan oleh apapun; Aku akan melenyapkan binatang buas dari negeri itu, dan pedang tidak akan melintas di negerimu.', 'id', 'TB'),
  ('3', 'im', 'Imamat', 26, 7, 'Kamu akan mengejar musuhmu, dan mereka akan tewas di hadapanmu oleh pedang.', 'id', 'TB'),
  ('3', 'im', 'Imamat', 26, 8, 'Lima orang dari antaramu akan mengejar seratus, dan seratus orang dari antaramu akan mengejar selaksa dan semua musuhmu akan tewas di hadapanmu oleh pedang.', 'id', 'TB'),
  ('3', 'im', 'Imamat', 26, 9, 'Dan Aku akan berpaling kepadamu dan akan membuat kamu beranak cucu serta bertambah banyak dan Aku akan meneguhkan perjanjian-Ku dengan kamu.', 'id', 'TB'),
  ('3', 'im', 'Imamat', 26, 10, 'Kamu masih akan makan hasil lama dari panen yang lampau, dan hasil lama itu akan kamu keluarkan untuk menyimpan yang baru.', 'id', 'TB'),
  ('3', 'im', 'Imamat', 26, 11, 'Aku akan menempatkan Kemah Suci-Ku di tengah-tengahmu dan hati-Ku tidak akan muak melihat kamu.', 'id', 'TB'),
  ('3', 'im', 'Imamat', 26, 12, 'Tetapi Aku akan hadir di tengah-tengahmu dan Aku akan menjadi Allahmu dan kamu akan menjadi umat-Ku.', 'id', 'TB'),
  ('3', 'im', 'Imamat', 26, 13, 'Akulah TUHAN, Allahmu, yang membawa kamu keluar dari tanah Mesir, supaya kamu jangan lagi menjadi budak mereka. Aku telah mematahkan kayu kuk yang di atasmu dan membuat kamu berjalan tegak."', 'id', 'TB'),
  ('3', 'im', 'Imamat', 26, 14, '"Tetapi jikalau kamu tidak mendengarkan Daku, dan tidak melakukan segala perintah itu,', 'id', 'TB'),
  ('3', 'im', 'Imamat', 26, 15, 'jikalau kamu menolak ketetapan-Ku dan hatimu muak mendengar peraturan-Ku, sehingga kamu tidak melakukan segala perintah-Ku dan kamu mengingkari perjanjian-Ku,', 'id', 'TB'),
  ('3', 'im', 'Imamat', 26, 16, 'maka Akupun akan berbuat begini kepadamu, yakni Aku akan mendatangkan kekejutan atasmu, batuk kering serta demam, yang membuat mata rusak dan jiwa merana; kamu akan sia-sia menabur benihmu, karena hasilnya akan habis dimakan musuhmu.', 'id', 'TB'),
  ('3', 'im', 'Imamat', 26, 17, 'Aku sendiri akan menentang kamu, sehingga kamu akan dikalahkan oleh musuhmu, dan mereka yang membenci kamu akan menguasai kamu, dan kamu akan lari, sungguhpun tidak ada orang mengejar kamu.', 'id', 'TB'),
  ('3', 'im', 'Imamat', 26, 18, 'Dan jikalau kamu dalam keadaan yang demikianpun tidak mendengarkan Daku, maka Aku akan lebih keras menghajar kamu sampai tujuh kali lipat karena dosamu,', 'id', 'TB'),
  ('3', 'im', 'Imamat', 26, 19, 'dan Aku akan mematahkan kekuasaanmu yang kaubanggakan dan akan membuat langit di atasmu sebagai besi dan tanahmu sebagai tembaga.', 'id', 'TB'),
  ('3', 'im', 'Imamat', 26, 20, 'Maka tenagamu akan habis dengan sia-sia, tanahmu tidak akan memberi hasilnya dan pohon-pohonan di tanah itu tidak akan memberi buahnya.', 'id', 'TB'),
  ('3', 'im', 'Imamat', 26, 21, 'Jikalau hidupmu tetap bertentangan dengan Daku dan kamu tidak mau mendengarkan Daku, maka Aku akan makin menambah hukuman atasmu sampai tujuh kali lipat setimpal dengan dosamu.', 'id', 'TB'),
  ('3', 'im', 'Imamat', 26, 22, 'Aku akan melepaskan kepadamu binatang liar yang akan memunahkan anak-anakmu dan yang akan melenyapkan ternakmu, serta membuat kamu menjadi sedikit, sehingga jalan-jalanmu menjadi sunyi.', 'id', 'TB'),
  ('3', 'im', 'Imamat', 26, 23, 'Jikalau kamu dalam keadaan yang demikianpun tidak mau Kuajar, dan hidupmu tetap bertentangan dengan Daku,', 'id', 'TB'),
  ('3', 'im', 'Imamat', 26, 24, 'maka Akupun akan bertindak melawan kamu dan Aku sendiri akan menghukum kamu tujuh kali lipat karena dosamu,', 'id', 'TB'),
  ('3', 'im', 'Imamat', 26, 25, 'dan Aku akan mendatangkan ke atasmu suatu pedang, yang akan melakukan pembalasan oleh karena perjanjian itu; bila kamu berkumpul kelak di kota-kotamu, maka Aku akan melepas penyakit sampar ke tengah-tengahmu dan kamu akan diserahkan ke dalam tangan musuh.', 'id', 'TB'),
  ('3', 'im', 'Imamat', 26, 26, 'Jika Aku memusnahkan persediaan makananmu, maka sepuluh perempuan akan membakar roti di dalam satu pembakaran. Mereka akan mengembalikan rotimu menurut timbangan tertentu, dan kamu akan makan, tetapi tidak menjadi kenyang.', 'id', 'TB'),
  ('3', 'im', 'Imamat', 26, 27, 'Dan jikalau kamu dalam keadaan yang demikianpun tidak mendengarkan Daku, dan hidupmu tetap bertentangan dengan Daku,', 'id', 'TB'),
  ('3', 'im', 'Imamat', 26, 28, 'maka Akupun akan bertindak keras melawan kamu dan Aku sendiri akan menghajar kamu tujuh kali lipat karena dosamu,', 'id', 'TB'),
  ('3', 'im', 'Imamat', 26, 29, 'dan kamu akan memakan daging anak-anakmu lelaki dan anak-anakmu perempuan.', 'id', 'TB'),
  ('3', 'im', 'Imamat', 26, 30, 'Dan bukit-bukit pengorbananmu akan Kupunahkan, dan segala pedupaanmu akan Kulenyapkan. Aku akan melemparkan bangkai-bangkaimu ke atas bangkai-bangkai berhalamu dan hati-Ku akan muak melihat kamu.', 'id', 'TB'),
  ('3', 'im', 'Imamat', 26, 31, 'Kota-kotamu akan Kubuat menjadi reruntuhan dan tempat-tempat kudusmu akan Kurusakkan dan Aku tidak mau lagi menghirup bau persembahanmu yang menyenangkan.', 'id', 'TB'),
  ('3', 'im', 'Imamat', 26, 32, 'Aku sendiri akan merusakkan negeri itu, sehingga musuhmu yang tinggal di situ akan tercengang karenanya.', 'id', 'TB'),
  ('3', 'im', 'Imamat', 26, 33, 'Tetapi kamu akan Kuserakkan di antara bangsa-bangsa lain dan Aku akan menghunus pedang di belakang kamu, dan tanahmu akan menjadi tempat tandus dan kota-kotamu akan menjadi reruntuhan.', 'id', 'TB'),
  ('3', 'im', 'Imamat', 26, 34, 'Pada waktu itulah tanah itu pulih dari dilalaikannya tahun-tahun sabatnya selama tanah itu tandus dan selama kamu tinggal di negeri musuh-musuhmu; pada waktu itulah tanah itu akan menjalani sabatnya dan dipulihkan tahun-tahun sabat yang belum didapatnya.', 'id', 'TB'),
  ('3', 'im', 'Imamat', 26, 35, 'Selama ketandusannya tanah itu akan menjalani sabat yang belum dijalaninya pada tiap-tiap tahun sabatmu, ketika kamu masih diam di situ.', 'id', 'TB'),
  ('3', 'im', 'Imamat', 26, 36, 'Dan mengenai mereka yang masih tinggal hidup dari antaramu, Aku akan mendatangkan kecemasan ke dalam hati mereka di dalam negeri-negeri musuh mereka, sehingga bunyi daun yang ditiupkan anginpun akan mengejar mereka, dan mereka akan lari seperti orang lari menjauhi pedang, dan mereka akan rebah, sungguhpun tidak ada orang yang mengejar.', 'id', 'TB'),
  ('3', 'im', 'Imamat', 26, 37, 'Dan mereka akan jatuh tersandung seorang kepada seorang seolah-olah hendak menjauhi pedang, sungguhpun yang mengejar tidak ada, dan kamu tidak akan dapat bertahan di hadapan musuh-musuhmu.', 'id', 'TB'),
  ('3', 'im', 'Imamat', 26, 38, 'Dan kamu akan binasa di antara bangsa-bangsa lain, dan negeri musuhmu akan memusnahkan kamu.', 'id', 'TB'),
  ('3', 'im', 'Imamat', 26, 39, 'Dan siapa yang masih tinggal hidup dari antaramu, mereka akan hancur lebur dalam hukumannya di negeri-negeri musuh mereka, dan karena kesalahan nenek moyang mereka juga mereka akan hancur lebur sama seperti nenek moyangnya.', 'id', 'TB'),
  ('3', 'im', 'Imamat', 26, 40, 'Tetapi bila mereka mengakui kesalahan mereka dan kesalahan nenek moyang mereka dalam hal berubah setia yang dilakukan mereka terhadap Aku dan mengakui juga bahwa hidup mereka bertentangan dengan Daku', 'id', 'TB'),
  ('3', 'im', 'Imamat', 26, 41, '?Akupun bertindak melawan mereka dan membawa mereka ke negeri musuh mereka?atau bila kemudian hati mereka yang tidak bersunat itu telah tunduk dan mereka telah membayar pulih kesalahan mereka,', 'id', 'TB'),
  ('3', 'im', 'Imamat', 26, 42, 'maka Aku akan mengingat perjanjian-Ku dengan Yakub; juga perjanjian dengan Ishak dan perjanjian-Ku dengan Abrahampun akan Kuingat dan negeri itu akan Kuingat juga.', 'id', 'TB'),
  ('3', 'im', 'Imamat', 26, 43, 'Jadi tanah itu akan ditinggalkan mereka dan akan pulih dari akibat tahun-tahun sabat yang dilalaikan selama tanah itu tandus, oleh karena ditinggalkan mereka, dan mereka akan membayar pulih kesalahan mereka, tak lain dan tak bukan karena mereka menolak peraturan-Ku dan hati mereka muak mendengarkan ketetapan-Ku.', 'id', 'TB'),
  ('3', 'im', 'Imamat', 26, 44, 'Namun demikian, apabila mereka ada di negeri musuh mereka, Aku tidak akan menolak mereka dan tidak akan muak melihat mereka, sehingga Aku membinasakan mereka dan membatalkan perjanjian-Ku dengan mereka, sebab Akulah TUHAN, Allah mereka.', 'id', 'TB'),
  ('3', 'im', 'Imamat', 26, 45, 'Untuk keselamatan mereka Aku akan mengingat perjanjian dengan orang-orang dahulu yang Kubawa keluar dari tanah Mesir di depan mata bangsa-bangsa lain, supaya Aku menjadi Allah mereka; Akulah TUHAN."', 'id', 'TB'),
  ('3', 'im', 'Imamat', 26, 46, 'Itulah ketetapan-ketetapan dan peraturan-peraturan serta hukum-hukum yang diberikan TUHAN, berlaku di antara Dia dengan orang Israel, di gunung Sinai, dengan perantaraan Musa.', 'id', 'TB'),
  ('3', 'im', 'Imamat', 27, 1, 'TUHAN berfirman kepada Musa:', 'id', 'TB'),
  ('3', 'im', 'Imamat', 27, 2, '"Berbicaralah kepada orang Israel dan katakan kepada mereka: Apabila seorang mengucapkan nazar khusus kepada TUHAN mengenai orang menurut penilaian yang berlaku untuk itu,', 'id', 'TB'),
  ('3', 'im', 'Imamat', 27, 3, 'maka tentang nilai bagi orang laki-laki dari yang berumur dua puluh tahun sampai yang berumur enam puluh tahun, nilai itu harus lima puluh syikal perak, ditimbang menurut syikal kudus.', 'id', 'TB'),
  ('3', 'im', 'Imamat', 27, 4, 'Tetapi jikalau itu seorang perempuan, maka nilai itu harus tiga puluh syikal.', 'id', 'TB'),
  ('3', 'im', 'Imamat', 27, 5, 'Jikalau itu mengenai seorang dari yang berumur lima tahun sampai yang berumur dua puluh tahun, maka bagi laki-laki nilai itu harus dua puluh syikal dan bagi perempuan sepuluh syikal.', 'id', 'TB'),
  ('3', 'im', 'Imamat', 27, 6, 'Jikalau itu mengenai seorang dari yang berumur satu bulan sampai yang berumur lima tahun, maka bagi laki-laki nilai itu harus lima syikal perak, dan bagi perempuan tiga syikal perak.', 'id', 'TB'),
  ('3', 'im', 'Imamat', 27, 7, 'Jikalau itu mengenai seorang yang berumur enam puluh tahun atau lebih, jikalau itu mengenai laki-laki, maka nilai itu harus lima belas syikal dan bagi perempuan sepuluh syikal.', 'id', 'TB'),
  ('3', 'im', 'Imamat', 27, 8, 'Tetapi jikalau orang itu terlalu miskin untuk membayar nilai itu, maka haruslah dihadapkannya orang yang dinazarkannya itu kepada imam, dan imam harus menilainya; sesuai dengan kemampuan orang yang bernazar itu imam harus menentukan nilainya.', 'id', 'TB'),
  ('3', 'im', 'Imamat', 27, 9, 'Jikalau itu termasuk hewan yang boleh dipersembahkan sebagai persembahan kepada TUHAN, maka apapun dari pada hewan itu yang dipersembahkan orang itu kepada TUHAN haruslah kudus.', 'id', 'TB'),
  ('3', 'im', 'Imamat', 27, 10, 'Janganlah ia menggantinya dan janganlah ia menukarnya, yang baik dengan yang buruk atau yang buruk dengan yang baik. Tetapi jikalau ia menukar juga seekor hewan dengan seekor hewan lain, maka baik hewan itu maupun tukarnya haruslah kudus.', 'id', 'TB'),
  ('3', 'im', 'Imamat', 27, 11, 'Jikalau itu barang seekor dari antara hewan haram yang tidak boleh dipersembahkan sebagai persembahan kepada TUHAN, maka hewan itu harus dihadapkannya kepada imam,', 'id', 'TB'),
  ('3', 'im', 'Imamat', 27, 12, 'dan imam harus menetapkan nilainya menurut baik atau buruknya, dan seperti penilaian imam demikianlah jadinya.', 'id', 'TB'),
  ('3', 'im', 'Imamat', 27, 13, 'Dan jikalau orang itu mau menebusnya juga, ia harus menambahkan seperlima kepada nilai itu.', 'id', 'TB'),
  ('3', 'im', 'Imamat', 27, 14, 'Apabila seorang menguduskan rumahnya sebagai persembahan kudus bagi TUHAN, maka imam harus menetapkan nilainya menurut baik atau buruknya, dan seperti nilai yang ditetapkan imam demikianlah harus dipegang teguh.', 'id', 'TB'),
  ('3', 'im', 'Imamat', 27, 15, 'Tetapi jikalau orang yang menguduskan itu mau menebus rumahnya, maka ia harus menambah harganya dengan seperlima dari uang nilainya dan rumah itu menjadi kepunyaannya pula.', 'id', 'TB'),
  ('3', 'im', 'Imamat', 27, 16, 'Jikalau seseorang menguduskan sebagian dari ladang miliknya bagi TUHAN, maka nilainya haruslah sesuai dengan taburannya, yakni sehomer taburan benih jelai berharga lima puluh syikal perak.', 'id', 'TB'),
  ('3', 'im', 'Imamat', 27, 17, 'Jikalau ia menguduskan ladangnya mulai dari tahun Yobel, maka nilainya haruslah dipegang teguh.', 'id', 'TB'),
  ('3', 'im', 'Imamat', 27, 18, 'Tetapi jikalau ia menguduskan ladangnya sesudah tahun Yobel, maka imam harus menghitung harganya bagi orang itu sesuai dengan tahun-tahun yang masih tinggal sampai kepada tahun Yobel, dan harga itu harus dikurangkan dari nilainya.', 'id', 'TB'),
  ('3', 'im', 'Imamat', 27, 19, 'Dan jikalau orang yang menguduskannya benar-benar mau menebus ladang itu, maka ia harus menambah harganya dengan seperlima dari uang nilainya dan ladang itu tetap dimilikinya.', 'id', 'TB'),
  ('3', 'im', 'Imamat', 27, 20, 'Tetapi jikalau ia tidak menebus ladang itu, malahan ladang itu telah dijualnya kepada orang lain, maka tidak dapat ditebus lagi.', 'id', 'TB'),
  ('3', 'im', 'Imamat', 27, 21, 'Tetapi pada waktu bebas dalam tahun Yobel, ladang itu haruslah kudus bagi TUHAN, sama seperti ladang yang dikhususkan bagi TUHAN. Imamlah yang harus memilikinya.', 'id', 'TB'),
  ('3', 'im', 'Imamat', 27, 22, 'Dan jikalau ia menguduskan bagi TUHAN ladang yang telah dibelinya dan yang tidak termasuk ladang miliknya dahulu,', 'id', 'TB'),
  ('3', 'im', 'Imamat', 27, 23, 'maka imam harus menghitung baginya harga nilainya sampai kepada tahun Yobel dan orang itu haruslah mempersembahkan nilai itu pada hari itu juga sebagai persembahan kudus bagi TUHAN.', 'id', 'TB'),
  ('3', 'im', 'Imamat', 27, 24, 'Dalam tahun Yobel ladang itu harus dipulangkan kepada orang yang menjualnya kepadanya, yakni kepada orang yang mula-mula memiliki tanah itu.', 'id', 'TB'),
  ('3', 'im', 'Imamat', 27, 25, 'Dan segala nilai harus menurut syikal kudus, syikal itu harus dua puluh gera beratnya.', 'id', 'TB'),
  ('3', 'im', 'Imamat', 27, 26, 'Akan tetapi anak sulung, yang sebagai anak sulung menjadi hak TUHAN dari antara hewan, tidak boleh dikuduskan oleh siapapun, baik seekor lembu maupun seekor kambing atau domba, itu milik TUHAN.', 'id', 'TB'),
  ('3', 'im', 'Imamat', 27, 27, 'Tetapi jikalau itu dari antara hewan yang haram, maka haruslah orang menebusnya menurut nilainya dengan menambah seperlima dan jikalau tidak ditebus, haruslah dijual menurut nilainya.', 'id', 'TB'),
  ('3', 'im', 'Imamat', 27, 28, 'Akan tetapi segala yang sudah dikhususkan oleh seseorang bagi TUHAN dari segala miliknya, baik manusia atau hewan, maupun ladang miliknya, tidak boleh dijual dan tidak boleh ditebus, karena segala yang dikhususkan adalah maha kudus bagi TUHAN.', 'id', 'TB'),
  ('3', 'im', 'Imamat', 27, 29, 'Setiap orang yang dikhususkan, yang harus ditumpas di antara manusia, tidak boleh ditebus, pastilah ia dihukum mati.', 'id', 'TB'),
  ('3', 'im', 'Imamat', 27, 30, 'Demikian juga segala persembahan persepuluhan dari tanah, baik dari hasil benih di tanah maupun dari buah pohon-pohonan, adalah milik TUHAN; itulah persembahan kudus bagi TUHAN.', 'id', 'TB'),
  ('3', 'im', 'Imamat', 27, 31, 'Tetapi jikalau seseorang mau menebus juga sebagian dari persembahan persepuluhannya itu, maka ia harus menambah seperlima.', 'id', 'TB'),
  ('3', 'im', 'Imamat', 27, 32, 'Mengenai segala persembahan persepuluhan dari lembu sapi atau kambing domba, maka dari segala yang lewat dari bawah tongkat gembala waktu dihitung, setiap yang kesepuluh harus menjadi persembahan kudus bagi TUHAN.', 'id', 'TB'),
  ('3', 'im', 'Imamat', 27, 33, 'Janganlah dipilih-pilih mana yang baik dan mana yang buruk, dan janganlah ditukar; jikalau orang menukarnya juga, maka baik hewan itu maupun tukarnya haruslah kudus dan tidak boleh ditebus."', 'id', 'TB'),
  ('3', 'im', 'Imamat', 27, 34, 'Itulah perintah-perintah yang diperintahkan TUHAN kepada Musa di gunung Sinai untuk disampaikan kepada orang Israel.', 'id', 'TB'),
  ('4', 'bil', 'Bilangan', 1, 1, 'TUHAN berfirman kepada Musa di padang gurun Sinai, dalam Kemah Pertemuan, pada tanggal satu bulan yang kedua dalam tahun yang kedua sesudah mereka keluar dari tanah Mesir:', 'id', 'TB'),
  ('4', 'bil', 'Bilangan', 1, 2, '"Hitunglah jumlah segenap umat Israel menurut kaum-kaum yang ada dalam setiap suku mereka, dan catatlah nama semua laki-laki di Israel', 'id', 'TB'),
  ('4', 'bil', 'Bilangan', 1, 3, 'yang berumur dua puluh tahun ke atas dan yang sanggup berperang, orang demi orang. Engkau ini beserta Harun harus mencatat mereka menurut pasukannya masing-masing.', 'id', 'TB'),
  ('4', 'bil', 'Bilangan', 1, 4, 'Dari tiap-tiap suku harus ada satu orang yang mendampingi kamu, yakni orang yang menjadi kepala dari suku yang diwakilinya itu.', 'id', 'TB'),
  ('4', 'bil', 'Bilangan', 1, 5, 'Dan inilah nama semua orang yang harus mendampingi kamu. Dari suku Ruben: Elizur bin Syedeur;', 'id', 'TB'),
  ('4', 'bil', 'Bilangan', 1, 6, 'dari suku Simeon: Selumiel bin Zurisyadai;', 'id', 'TB'),
  ('4', 'bil', 'Bilangan', 1, 7, 'dari suku Yehuda: Nahason bin Aminadab;', 'id', 'TB'),
  ('4', 'bil', 'Bilangan', 1, 8, 'dari suku Isakhar: Netaneel bin Zuar;', 'id', 'TB'),
  ('4', 'bil', 'Bilangan', 1, 9, 'dari suku Zebulon: Eliab bin Helon;', 'id', 'TB'),
  ('4', 'bil', 'Bilangan', 1, 10, 'dari keturunan Yusuf: Elisama bin Amihud dari suku Efraim, dan Gamaliel bin Pedazur dari suku Manasye;', 'id', 'TB'),
  ('4', 'bil', 'Bilangan', 1, 11, 'dari suku Benyamin: Abidan bin Gideoni;', 'id', 'TB'),
  ('4', 'bil', 'Bilangan', 1, 12, 'dari suku Dan: Ahiezer bin Amisyadai;', 'id', 'TB'),
  ('4', 'bil', 'Bilangan', 1, 13, 'dari suku Asyer: Pagiel bin Okhran;', 'id', 'TB'),
  ('4', 'bil', 'Bilangan', 1, 14, 'dari suku Gad: Elyasaf bin Rehuel;', 'id', 'TB'),
  ('4', 'bil', 'Bilangan', 1, 15, 'dari suku Naftali: Ahira bin Enan."', 'id', 'TB'),
  ('4', 'bil', 'Bilangan', 1, 16, 'Itulah orang-orang yang dipilih dari umat itu, masing-masing sebagai pemimpin dari suku bapa leluhurnya; mereka inilah kepala-kepala pasukan Israel.', 'id', 'TB'),
  ('4', 'bil', 'Bilangan', 1, 17, 'Lalu Musa dan Harun memanggil orang-orang yang tertunjuk namanya itu,', 'id', 'TB'),
  ('4', 'bil', 'Bilangan', 1, 18, 'dan pada tanggal satu bulan yang kedua mereka menyuruh segenap umat berkumpul. Kemudian silsilah orang-orang Israel disusun menurut kaum-kaum yang ada dalam setiap suku mereka, sedang nama-nama mereka yang berumur dua puluh tahun ke atas dicatat orang demi orang,', 'id', 'TB'),
  ('4', 'bil', 'Bilangan', 1, 19, 'seperti yang diperintahkan TUHAN kepada Musa. Demikianlah Musa mencatat mereka di padang gurun Sinai.', 'id', 'TB'),
  ('4', 'bil', 'Bilangan', 1, 20, 'Ketika silsilah bani Ruben, yaitu keturunan anak sulung Israel, disusun menurut kaum-kaum yang ada dalam suku mereka, maka dicatatlah nama semua laki-laki yang berumur dua puluh tahun ke atas, semua orang yang sanggup berperang, orang demi orang.', 'id', 'TB'),
  ('4', 'bil', 'Bilangan', 1, 21, 'Jumlah yang dicatat dari suku Ruben ada empat puluh enam ribu lima ratus orang.', 'id', 'TB'),
  ('4', 'bil', 'Bilangan', 1, 22, 'Ketika silsilah bani Simeon disusun menurut kaum-kaum yang ada dalam suku mereka, maka dicatatlah nama semua laki-laki yang berumur dua puluh tahun ke atas, semua orang yang sanggup berperang, orang demi orang.', 'id', 'TB'),
  ('4', 'bil', 'Bilangan', 1, 23, 'Jumlah yang dicatat dari suku Simeon ada lima puluh sembilan ribu tiga ratus orang.', 'id', 'TB'),
  ('4', 'bil', 'Bilangan', 1, 24, 'Ketika silsilah bani Gad disusun menurut kaum-kaum yang ada dalam suku mereka, maka dicatatlah nama orang-orang yang berumur dua puluh tahun ke atas, semua orang yang sanggup berperang.', 'id', 'TB'),
  ('4', 'bil', 'Bilangan', 1, 25, 'Jumlah yang dicatat dari suku Gad ada empat puluh lima ribu enam ratus lima puluh orang.', 'id', 'TB'),
  ('4', 'bil', 'Bilangan', 1, 26, 'Ketika silsilah bani Yehuda disusun menurut kaum-kaum yang ada dalam suku mereka, maka dicatatlah nama orang-orang yang berumur dua puluh tahun ke atas, semua orang yang sanggup berperang.', 'id', 'TB'),
  ('4', 'bil', 'Bilangan', 1, 27, 'Jumlah yang dicatat dari suku Yehuda ada tujuh puluh empat ribu enam ratus orang.', 'id', 'TB'),
  ('4', 'bil', 'Bilangan', 1, 28, 'Ketika silsilah bani Isakhar disusun menurut kaum-kaum yang ada dalam suku mereka, maka dicatatlah nama orang-orang yang berumur dua puluh tahun ke atas, semua orang yang sanggup berperang.', 'id', 'TB'),
  ('4', 'bil', 'Bilangan', 1, 29, 'Jumlah yang dicatat dari suku Isakhar ada lima puluh empat ribu empat ratus orang.', 'id', 'TB'),
  ('4', 'bil', 'Bilangan', 1, 30, 'Ketika silsilah bani Zebulon disusun menurut kaum-kaum yang ada dalam suku mereka, maka dicatatlah nama orang-orang yang berumur dua puluh tahun ke atas, semua orang yang sanggup berperang.', 'id', 'TB'),
  ('4', 'bil', 'Bilangan', 1, 31, 'Jumlah yang dicatat dari suku Zebulon ada lima puluh tujuh ribu empat ratus orang.', 'id', 'TB'),
  ('4', 'bil', 'Bilangan', 1, 32, 'Mengenai keturunan Yusuf: Ketika silsilah bani Efraim disusun menurut kaum-kaum yang ada dalam suku mereka, maka dicatatlah nama orang-orang yang berumur dua puluh tahun ke atas, semua orang yang sanggup berperang.', 'id', 'TB'),
  ('4', 'bil', 'Bilangan', 1, 33, 'Jumlah yang dicatat dari suku Efraim ada empat puluh ribu lima ratus orang.', 'id', 'TB'),
  ('4', 'bil', 'Bilangan', 1, 34, 'Dan ketika silsilah bani Manasye disusun menurut kaum-kaum yang ada dalam suku mereka, maka dicatatlah nama orang-orang yang berumur dua puluh tahun ke atas, semua orang yang sanggup berperang.', 'id', 'TB'),
  ('4', 'bil', 'Bilangan', 1, 35, 'Jumlah yang dicatat dari suku Manasye ada tiga puluh dua ribu dua ratus orang.', 'id', 'TB'),
  ('4', 'bil', 'Bilangan', 1, 36, 'Ketika silsilah bani Benyamin disusun menurut kaum-kaum yang ada dalam suku mereka, maka dicatatlah nama orang-orang yang berumur dua puluh tahun ke atas, semua orang yang sanggup berperang.', 'id', 'TB'),
  ('4', 'bil', 'Bilangan', 1, 37, 'Jumlah yang dicatat dari suku Benyamin ada tiga puluh lima ribu empat ratus orang.', 'id', 'TB'),
  ('4', 'bil', 'Bilangan', 1, 38, 'Ketika silsilah bani Dan disusun menurut kaum-kaum yang ada dalam suku mereka, maka dicatatlah nama orang-orang yang berumur dua puluh tahun ke atas, semua orang yang sanggup berperang.', 'id', 'TB'),
  ('4', 'bil', 'Bilangan', 1, 39, 'Jumlah yang dicatat dari suku Dan ada enam puluh dua ribu tujuh ratus orang.', 'id', 'TB'),
  ('4', 'bil', 'Bilangan', 1, 40, 'Ketika silsilah bani Asyer disusun menurut kaum-kaum yang ada dalam suku mereka, maka dicatatlah nama orang-orang yang berumur dua puluh tahun ke atas, semua orang yang sanggup berperang.', 'id', 'TB'),
  ('4', 'bil', 'Bilangan', 1, 41, 'Jumlah yang dicatat dari suku Asyer ada empat puluh satu ribu lima ratus orang.', 'id', 'TB'),
  ('4', 'bil', 'Bilangan', 1, 42, 'Ketika silsilah bani Naftali disusun menurut kaum-kaum yang ada dalam suku mereka, maka dicatatlah nama orang-orang yang berumur dua puluh tahun ke atas, semua orang yang sanggup berperang.', 'id', 'TB'),
  ('4', 'bil', 'Bilangan', 1, 43, 'Jumlah yang dicatat dari suku Naftali ada lima puluh tiga ribu empat ratus orang.', 'id', 'TB'),
  ('4', 'bil', 'Bilangan', 1, 44, 'Itulah jumlah orang-orang yang dicatat oleh Musa dengan Harun dan dengan kedua belas pemimpin Israel yang masing-masing mewakili sukunya.', 'id', 'TB'),
  ('4', 'bil', 'Bilangan', 1, 45, 'Jadi semua orang Israel yang dicatat menurut suku-suku mereka, yaitu orang-orang yang berumur dua puluh tahun ke atas dan yang sanggup berperang di antara orang Israel,', 'id', 'TB'),
  ('4', 'bil', 'Bilangan', 1, 46, 'berjumlah enam ratus tiga ribu lima ratus lima puluh orang.', 'id', 'TB'),
  ('4', 'bil', 'Bilangan', 1, 47, 'Tetapi mereka yang menurut suku bapa leluhurnya termasuk orang Lewi, tidak turut dicatat bersama-sama dengan mereka itu.', 'id', 'TB'),
  ('4', 'bil', 'Bilangan', 1, 48, 'Sebab TUHAN telah berfirman kepada Musa:', 'id', 'TB'),
  ('4', 'bil', 'Bilangan', 1, 49, '"Hanya suku Lewi janganlah kaucatat dan janganlah kauhitung jumlahnya bersama-sama dengan orang Israel,', 'id', 'TB'),
  ('4', 'bil', 'Bilangan', 1, 50, 'tetapi tugaskanlah mereka untuk mengawasi Kemah Suci, tempat hukum Allah dengan segala perabotan dan perlengkapannya; mereka harus mengangkat Kemah Suci dengan segala perabotannya; mereka harus mengurusnya dan harus berkemah di sekelilingnya.', 'id', 'TB'),
  ('4', 'bil', 'Bilangan', 1, 51, 'Apabila berangkat, Kemah Suci harus dibongkar oleh orang Lewi, dan apabila berkemah, Kemah Suci harus dipasang oleh mereka; sedang orang awam yang mendekat harus dihukum mati.', 'id', 'TB'),
  ('4', 'bil', 'Bilangan', 1, 52, 'Orang Israel haruslah berkemah masing-masing di tempat perkemahannya dan masing-masing dekat panji-panjinya, menurut pasukan mereka,', 'id', 'TB'),
  ('4', 'bil', 'Bilangan', 1, 53, 'tetapi orang Lewi haruslah berkemah di sekeliling Kemah Suci, tempat hukum Allah supaya umat Israel jangan kena murka; orang Lewi haruslah memelihara Kemah Suci, tempat hukum itu."', 'id', 'TB'),
  ('4', 'bil', 'Bilangan', 1, 54, 'Maka orang Israel berbuat demikian; tepat seperti yang diperintahkan TUHAN kepada Musa, demikianlah diperbuat mereka.', 'id', 'TB'),
  ('4', 'bil', 'Bilangan', 2, 1, 'TUHAN berfirman kepada Musa dan Harun:', 'id', 'TB'),
  ('4', 'bil', 'Bilangan', 2, 2, '"Orang Israel harus berkemah masing-masing dekat panji-panjinya, menurut lambang suku-sukunya. Mereka harus berkemah di sekeliling Kemah Pertemuan, agak jauh dari padanya.', 'id', 'TB'),
  ('4', 'bil', 'Bilangan', 2, 3, 'Yang berkemah di sebelah timur dekat panji-panjinya, ialah laskar Yehuda, menurut pasukan-pasukan mereka. Pemimpin bani Yehuda ialah Nahason bin Aminadab.', 'id', 'TB'),
  ('4', 'bil', 'Bilangan', 2, 4, 'Pasukannya terdiri dari tujuh puluh empat ribu enam ratus orang yang dicatat.', 'id', 'TB'),
  ('4', 'bil', 'Bilangan', 2, 5, 'Yang berkemah di dekatnya ialah suku Isakhar. Pemimpin bani Isakhar ialah Netaneel bin Zuar.', 'id', 'TB'),
  ('4', 'bil', 'Bilangan', 2, 6, 'Pasukannya terdiri dari lima puluh empat ribu empat ratus orang yang dicatat.', 'id', 'TB'),
  ('4', 'bil', 'Bilangan', 2, 7, 'Kemudian suku Zebulon. Pemimpin bani Zebulon ialah Eliab bin Helon.', 'id', 'TB'),
  ('4', 'bil', 'Bilangan', 2, 8, 'Pasukannya terdiri dari lima puluh tujuh ribu empat ratus orang yang dicatat.', 'id', 'TB'),
  ('4', 'bil', 'Bilangan', 2, 9, 'Jumlah orang yang dicatat dalam laskar Yehuda menurut pasukan-pasukan mereka ada seratus delapan puluh enam ribu empat ratus orang. Merekalah yang terdahulu berangkat.', 'id', 'TB'),
  ('4', 'bil', 'Bilangan', 2, 10, 'Panji-panji laskar Ruben adalah di sebelah selatan, menurut pasukan-pasukan mereka. Pemimpin bani Ruben ialah Elizur bin Syedeur.', 'id', 'TB'),
  ('4', 'bil', 'Bilangan', 2, 11, 'Pasukannya terdiri dari empat puluh enam ribu lima ratus orang yang dicatat.', 'id', 'TB'),
  ('4', 'bil', 'Bilangan', 2, 12, 'Yang berkemah di dekatnya ialah suku Simeon. Pemimpin bani Simeon ialah Selumiel bin Zurisyadai.', 'id', 'TB'),
  ('4', 'bil', 'Bilangan', 2, 13, 'Pasukannya terdiri dari lima puluh sembilan ribu tiga ratus orang yang dicatat.', 'id', 'TB'),
  ('4', 'bil', 'Bilangan', 2, 14, 'Kemudian suku Gad. Pemimpin bani Gad ialah Elyasaf bin Rehuel.', 'id', 'TB'),
  ('4', 'bil', 'Bilangan', 2, 15, 'Pasukannya terdiri dari empat puluh lima ribu enam ratus lima puluh orang yang dicatat.', 'id', 'TB'),
  ('4', 'bil', 'Bilangan', 2, 16, 'Jumlah orang yang dicatat dalam laskar Ruben menurut pasukan-pasukan mereka ada seratus lima puluh satu ribu empat ratus lima puluh orang. Merekalah yang nomor dua berangkat.', 'id', 'TB'),
  ('4', 'bil', 'Bilangan', 2, 17, 'Sesudah itu berangkatlah Kemah Pertemuan dengan laskar orang Lewi, di tengah-tengah laskar yang lain itu. Sama seperti mereka berkemah, demikianlah juga mereka berangkat, masing-masing di tempatnya menurut panji-panji mereka.', 'id', 'TB'),
  ('4', 'bil', 'Bilangan', 2, 18, 'Panji-panji laskar Efraim, menurut pasukan-pasukan mereka, adalah di sebelah barat. Pemimpin bani Efraim ialah Elisama bin Amihud.', 'id', 'TB'),
  ('4', 'bil', 'Bilangan', 2, 19, 'Pasukannya terdiri dari empat puluh ribu lima ratus orang yang dicatat.', 'id', 'TB'),
  ('4', 'bil', 'Bilangan', 2, 20, 'Di dekatnya ialah suku Manasye. Pemimpin bani Manasye ialah Gamaliel bin Pedazur.', 'id', 'TB'),
  ('4', 'bil', 'Bilangan', 2, 21, 'Pasukannya terdiri dari tiga puluh dua ribu dua ratus orang yang dicatat.', 'id', 'TB'),
  ('4', 'bil', 'Bilangan', 2, 22, 'Kemudian suku Benyamin. Pemimpin bani Benyamin ialah Abidan bin Gideoni.', 'id', 'TB'),
  ('4', 'bil', 'Bilangan', 2, 23, 'Pasukannya terdiri dari tiga puluh lima ribu empat ratus orang yang dicatat.', 'id', 'TB'),
  ('4', 'bil', 'Bilangan', 2, 24, 'Jumlah orang yang dicatat dalam laskar Efraim menurut pasukan-pasukan mereka ada seratus delapan ribu seratus orang. Merekalah yang nomor tiga berangkat.', 'id', 'TB'),
  ('4', 'bil', 'Bilangan', 2, 25, 'Panji-panji laskar Dan adalah di sebelah utara, menurut pasukan-pasukan mereka. Pemimpin bani Dan ialah Ahiezer bin Amisyadai.', 'id', 'TB'),
  ('4', 'bil', 'Bilangan', 2, 26, 'Pasukannya terdiri dari enam puluh dua ribu tujuh ratus orang yang dicatat.', 'id', 'TB'),
  ('4', 'bil', 'Bilangan', 2, 27, 'Yang berkemah di dekatnya ialah suku Asyer. Pemimpin bani Asyer ialah Pagiel bin Okhran.', 'id', 'TB'),
  ('4', 'bil', 'Bilangan', 2, 28, 'Pasukannya terdiri dari empat puluh satu ribu lima ratus orang yang dicatat.', 'id', 'TB'),
  ('4', 'bil', 'Bilangan', 2, 29, 'Kemudian suku Naftali. Pemimpin bani Naftali ialah Ahira bin Enan.', 'id', 'TB'),
  ('4', 'bil', 'Bilangan', 2, 30, 'Pasukannya terdiri dari lima puluh tiga ribu empat ratus orang yang dicatat.', 'id', 'TB'),
  ('4', 'bil', 'Bilangan', 2, 31, 'Jumlah orang yang dicatat dalam laskar Dan ada seratus lima puluh tujuh ribu enam ratus orang. Merekalah yang terkemudian berangkat, menurut panji-panji mereka."', 'id', 'TB'),
  ('4', 'bil', 'Bilangan', 2, 32, 'Itulah pencatatan orang Israel menurut suku-suku mereka. Jumlah orang yang dicatat dalam laskar-laskar dengan pasukan-pasukannya ada enam ratus tiga ribu lima ratus lima puluh orang.', 'id', 'TB'),
  ('4', 'bil', 'Bilangan', 2, 33, 'Tetapi orang Lewi tidak turut dicatat bersama-sama dengan orang Israel, seperti yang diperintahkan TUHAN kepada Musa.', 'id', 'TB'),
  ('4', 'bil', 'Bilangan', 2, 34, 'Maka orang Israel berbuat demikian; tepat seperti yang diperintahkan TUHAN kepada Musa, demikianlah mereka berkemah menurut panji-panji mereka, dan demikianlah mereka berangkat, masing-masing menurut kaumnya dan sukunya.', 'id', 'TB'),
  ('4', 'bil', 'Bilangan', 3, 1, 'Inilah keturunan Harun dan Musa pada waktu TUHAN berfirman kepada Musa di gunung Sinai.', 'id', 'TB'),
  ('4', 'bil', 'Bilangan', 3, 2, 'Nama anak-anak Harun, ialah: yang sulung Nadab, kemudian Abihu, Eleazar dan Itamar.', 'id', 'TB'),
  ('4', 'bil', 'Bilangan', 3, 3, 'Itulah nama anak-anak Harun, imam-imam yang diurapi, yang telah ditahbiskan untuk memegang jabatan imam.', 'id', 'TB'),
  ('4', 'bil', 'Bilangan', 3, 4, 'Tetapi Nadab dan Abihu sudah mati di hadapan TUHAN di padang gurun Sinai, ketika mereka mempersembahkan api yang asing ke hadapan TUHAN. Mereka tidak mempunyai anak. Jadi ketika Harun, ayah mereka, masih hidup, yang memegang jabatan imam ialah Eleazar dan Itamar.', 'id', 'TB'),
  ('4', 'bil', 'Bilangan', 3, 5, 'TUHAN berfirman kepada Musa:', 'id', 'TB'),
  ('4', 'bil', 'Bilangan', 3, 6, '"Suruhlah suku Lewi mendekat dan menghadap imam Harun, supaya mereka melayani dia.', 'id', 'TB'),
  ('4', 'bil', 'Bilangan', 3, 7, 'Mereka harus mengerjakan tugas-tugas bagi Harun dan bagi segenap umat Israel di depan Kemah Pertemuan dan dengan demikian melakukan pekerjaan jabatannya pada Kemah Suci.', 'id', 'TB'),
  ('4', 'bil', 'Bilangan', 3, 8, 'Mereka harus memelihara segala perabotan Kemah Pertemuan, dan mengerjakan tugas-tugas bagi orang Israel dan dengan demikian melakukan pekerjaan jabatannya pada Kemah Suci.', 'id', 'TB'),
  ('4', 'bil', 'Bilangan', 3, 9, 'Orang Lewi harus kauserahkan kepada Harun dan anak-anaknya; dari antara orang Israel haruslah orang-orang itu diserahkan kepadanya dengan sepenuhnya.', 'id', 'TB'),
  ('4', 'bil', 'Bilangan', 3, 10, 'Tetapi Harun dan anak-anaknya haruslah kautugaskan untuk memegang jabatannya sebagai imam, sedang orang awam yang mendekat harus dihukum mati."', 'id', 'TB'),
  ('4', 'bil', 'Bilangan', 3, 11, 'TUHAN berfirman kepada Musa:', 'id', 'TB'),
  ('4', 'bil', 'Bilangan', 3, 12, '"Sesungguhnya, Aku mengambil orang Lewi dari antara orang Israel ganti semua anak sulung mereka, yang terdahulu lahir dari kandungan, supaya orang Lewi menjadi kepunyaan-Ku,', 'id', 'TB'),
  ('4', 'bil', 'Bilangan', 3, 13, 'sebab Akulah yang punya semua anak sulung. Pada waktu Aku membunuh semua anak sulung di tanah Mesir, maka Aku menguduskan bagi-Ku semua anak sulung yang ada pada orang Israel, baik dari manusia maupun dari hewan; semuanya itu kepunyaan-Ku; Akulah TUHAN."', 'id', 'TB'),
  ('4', 'bil', 'Bilangan', 3, 14, 'TUHAN berfirman kepada Musa di padang gurun Sinai:', 'id', 'TB'),
  ('4', 'bil', 'Bilangan', 3, 15, '"Catatlah bani Lewi menurut puak-puak dan kaum-kaum mereka; semua laki-laki yang berumur satu bulan ke atas harus kaucatat."', 'id', 'TB'),
  ('4', 'bil', 'Bilangan', 3, 16, 'Lalu Musa mencatat mereka sesuai dengan titah TUHAN, seperti yang diperintahkan kepadanya.', 'id', 'TB'),
  ('4', 'bil', 'Bilangan', 3, 17, 'Inilah anak-anak Lewi dengan nama mereka: Gerson, Kehat dan Merari.', 'id', 'TB'),
  ('4', 'bil', 'Bilangan', 3, 18, 'Inilah nama anak-anak Gerson dan kaum-kaum mereka: Libni dan Simei.', 'id', 'TB'),
  ('4', 'bil', 'Bilangan', 3, 19, 'Anak-anak Kehat dan kaum-kaum mereka ialah Amram, Yizhar, Hebron dan Uziel.', 'id', 'TB'),
  ('4', 'bil', 'Bilangan', 3, 20, 'Anak-anak Merari dan kaum-kaum mereka ialah Mahli dan Musi. Inilah kaum-kaum orang Lewi yang ada dalam puak-puak mereka.', 'id', 'TB'),
  ('4', 'bil', 'Bilangan', 3, 21, 'Puak Gerson terdiri dari kaum Libni dan kaum Simei; itulah kaum-kaum Gerson.', 'id', 'TB'),
  ('4', 'bil', 'Bilangan', 3, 22, 'Jumlah pencatatan mereka ketika semua laki-laki yang berumur satu bulan ke atas dicatat ada tujuh ribu lima ratus orang.', 'id', 'TB'),
  ('4', 'bil', 'Bilangan', 3, 23, 'Kaum-kaum Gerson ini berkemah di belakang Kemah Suci di sebelah barat.', 'id', 'TB'),
  ('4', 'bil', 'Bilangan', 3, 24, 'Pemimpin puak Gerson ialah Elyasaf bin Lael.', 'id', 'TB'),
  ('4', 'bil', 'Bilangan', 3, 25, 'Yang harus dipelihara oleh bani Gerson dalam Kemah Pertemuan ialah Kemah Suci dan Kemah dengan tudungnya, tirai pintu Kemah Pertemuan,', 'id', 'TB'),
  ('4', 'bil', 'Bilangan', 3, 26, 'layar pelataran dan tirai pintu pelataran yang ada sekeliling Kemah Suci dan mezbah, dan talinya, termasuk segala pekerjaan yang berhubungan dengan semuanya itu.', 'id', 'TB'),
  ('4', 'bil', 'Bilangan', 3, 27, 'Puak Kehat terdiri dari kaum Amram, kaum Yizhar, kaum Hebron dan kaum Uziel; itulah kaum-kaum Kehat.', 'id', 'TB'),
  ('4', 'bil', 'Bilangan', 3, 28, 'Jumlah pencatatan mereka ketika semua laki-laki yang berumur satu bulan ke atas dicatat ada delapan ribu enam ratus orang, yakni mereka yang memelihara barang-barang kudus.', 'id', 'TB'),
  ('4', 'bil', 'Bilangan', 3, 29, 'Kaum-kaum bani Kehat ini berkemah pada sisi Kemah Suci sebelah selatan.', 'id', 'TB'),
  ('4', 'bil', 'Bilangan', 3, 30, 'Pemimpin puak Kehat dan kaum-kaumnya ialah Elisafan bin Uziel.', 'id', 'TB'),
  ('4', 'bil', 'Bilangan', 3, 31, 'Yang harus dipelihara mereka ialah tabut, meja, kandil, mezbah-mezbah, perkakas tempat kudus yang dipakai untuk menyelenggarakan ibadah, juga tirai, termasuk segala pekerjaan yang berhubungan dengan semuanya itu.', 'id', 'TB'),
  ('4', 'bil', 'Bilangan', 3, 32, 'Adapun pemimpin tertinggi orang Lewi ialah Eleazar, anak imam Harun, yang mengawasi mereka yang memelihara barang-barang kudus.', 'id', 'TB'),
  ('4', 'bil', 'Bilangan', 3, 33, 'Puak Merari terdiri dari kaum Mahli dan kaum Musi; itulah kaum-kaum Merari.', 'id', 'TB'),
  ('4', 'bil', 'Bilangan', 3, 34, 'Jumlah pencatatan mereka ketika semua laki-laki yang berumur satu bulan ke atas dicatat ada enam ribu dua ratus orang.', 'id', 'TB'),
  ('4', 'bil', 'Bilangan', 3, 35, 'Pemimpin puak Merari dan kaum-kaumnya ialah Zuriel bin Abihail. Mereka berkemah pada sisi Kemah Suci sebelah utara.', 'id', 'TB'),
  ('4', 'bil', 'Bilangan', 3, 36, 'Yang ditugaskan kepada bani Merari untuk dipelihara ialah papan Kemah Suci, kayu lintangnya, tiang-tiangnya, alasnya, segala perabotannya, termasuk segala pekerjaan yang berhubungan dengan semuanya itu,', 'id', 'TB'),
  ('4', 'bil', 'Bilangan', 3, 37, 'juga tiang pelataran sekelilingnya, alas, patok dan talinya.', 'id', 'TB'),
  ('4', 'bil', 'Bilangan', 3, 38, 'Yang berkemah di depan Kemah Suci di sebelah timur, di depan Kemah Pertemuan, ialah Musa, dan Harun serta anak-anaknya, yang mengerjakan tugas pemeliharaan tempat kudus bagi orang Israel; tetapi orang awam yang mendekat, haruslah dihukum mati.', 'id', 'TB'),
  ('4', 'bil', 'Bilangan', 3, 39, 'Jumlah orang Lewi yang sesuai dengan titah TUHAN dicatat oleh Musa dan Harun, menurut kaum-kaum mereka, yakni semua laki-laki yang berumur satu bulan ke atas, ada dua puluh dua ribu orang.', 'id', 'TB'),
  ('4', 'bil', 'Bilangan', 3, 40, 'Lalu berfirmanlah TUHAN kepada Musa: "Catatlah semua anak sulung laki-laki Israel yang berumur satu bulan ke atas, lalu hitunglah jumlah mereka,', 'id', 'TB'),
  ('4', 'bil', 'Bilangan', 3, 41, 'dan ambillah orang-orang Lewi bagi-Ku?Akulah TUHAN?sebagai ganti semua anak sulung yang ada pada orang Israel, juga hewan orang Lewi ganti semua anak sulung di antara hewan orang Israel."', 'id', 'TB'),
  ('4', 'bil', 'Bilangan', 3, 42, 'Maka Musa mencatat semua anak sulung yang ada pada orang Israel, seperti yang diperintahkan TUHAN kepadanya.', 'id', 'TB'),
  ('4', 'bil', 'Bilangan', 3, 43, 'Semua anak sulung laki-laki yang dicatat namanya dalam pencatatan itu, yakni yang berumur satu bulan ke atas, ada dua puluh dua ribu dua ratus tujuh puluh tiga orang.', 'id', 'TB'),
  ('4', 'bil', 'Bilangan', 3, 44, 'Lalu berfirmanlah TUHAN kepada Musa:', 'id', 'TB'),
  ('4', 'bil', 'Bilangan', 3, 45, '"Ambillah orang Lewi ganti semua anak sulung yang ada pada orang Israel, juga hewan orang Lewi ganti hewan mereka, supaya orang Lewi itu menjadi kepunyaan-Ku; Akulah TUHAN.', 'id', 'TB'),
  ('4', 'bil', 'Bilangan', 3, 46, 'Sebagai uang tebusan untuk kedua ratus tujuh puluh tiga anak sulung Israel yang melebihi jumlah orang Lewi itu,', 'id', 'TB'),
  ('4', 'bil', 'Bilangan', 3, 47, 'haruslah engkau mengambil lima syikal seorang; engkau harus mengambilnya menurut syikal kudus?syikal ini dua puluh gera beratnya?.', 'id', 'TB'),
  ('4', 'bil', 'Bilangan', 3, 48, 'Berikanlah perak itu kepada Harun dan anak-anaknya sebagai uang tebusan untuk orang-orang yang kelebihan itu."', 'id', 'TB'),
  ('4', 'bil', 'Bilangan', 3, 49, 'Lalu Musa mengambil uang tebusan untuk orang-orang yang melebihi jumlah mereka yang telah ditebus oleh orang Lewi itu;', 'id', 'TB'),
  ('4', 'bil', 'Bilangan', 3, 50, 'dari pada anak-anak sulung Israel diambilnya perak itu, seribu tiga ratus enam puluh lima syikal, ditimbang menurut syikal kudus,', 'id', 'TB'),
  ('4', 'bil', 'Bilangan', 3, 51, 'maka Musa memberikan uang tebusan itu kepada Harun dan anak-anaknya sesuai dengan titah TUHAN, seperti yang diperintahkan TUHAN kepada Musa.', 'id', 'TB'),
  ('4', 'bil', 'Bilangan', 4, 1, 'TUHAN berfirman kepada Musa dan Harun:', 'id', 'TB'),
  ('4', 'bil', 'Bilangan', 4, 2, '"Hitunglah jumlah bani Kehat sebagai suatu golongan tersendiri di antara bani Lewi, menurut kaum-kaum yang ada dalam puak mereka.', 'id', 'TB'),
  ('4', 'bil', 'Bilangan', 4, 3, 'Hitunglah yang berumur tiga puluh tahun ke atas sampai yang berumur lima puluh tahun, semua orang yang kena wajib tugas, supaya mereka melakukan pekerjaan di Kemah Pertemuan.', 'id', 'TB'),
  ('4', 'bil', 'Bilangan', 4, 4, 'Pekerjaan jabatan orang Kehat di Kemah Pertemuan ialah mengurus barang-barang yang maha kudus.', 'id', 'TB'),
  ('4', 'bil', 'Bilangan', 4, 5, 'Kalau perkemahan akan berangkat, haruslah Harun dan anak-anaknya masuk ke dalam untuk menurunkan tabir penudung, dan menudungkannya kepada tabut hukum.', 'id', 'TB'),
  ('4', 'bil', 'Bilangan', 4, 6, 'Di atasnya mereka harus meletakkan tutup dari kulit lumba-lumba, dan di atasnya lagi mereka harus membentangkan sehelai kain yang seluruhnya ungu tua, kemudian mereka harus memasang kayu-kayu pengusung tabut itu.', 'id', 'TB'),
  ('4', 'bil', 'Bilangan', 4, 7, 'Lagipula di atas meja roti sajian mereka harus membentangkan sehelai kain ungu tua, dan di atasnya mereka harus meletakkan pinggan, cawan, piala dan kendi korban curahan; juga roti sajian harus tetap ada di atasnya.', 'id', 'TB'),
  ('4', 'bil', 'Bilangan', 4, 8, 'Di atas semuanya itu mereka harus membentangkan sehelai kain kirmizi, lalu menudungnya dengan tudung dari kulit lumba-lumba, kemudian mereka harus memasang kayu-kayu pengusung meja itu.', 'id', 'TB'),
  ('4', 'bil', 'Bilangan', 4, 9, 'Lalu mereka harus mengambil sehelai kain ungu tua dan menudungkannya kepada kandil untuk penerangan dengan lampu-lampunya, sepit-sepit dan penadah-penadahnya, dan segala perkakas minyaknya yang dipakai untuk mengurus kandil itu.', 'id', 'TB'),
  ('4', 'bil', 'Bilangan', 4, 10, 'Dan mereka harus meletakkannya dengan segala perkakasnya ke atas tudung dengan dari kulit lumba-lumba dan meletakkannya di atas usungan.', 'id', 'TB'),
  ('4', 'bil', 'Bilangan', 4, 11, 'Di atas mezbah dari emas itu mereka harus membentangkan sehelai kain ungu tua dan menudunginya dengan tudung dari kulit lumba-lumba, kemudian mereka harus memasang kayu-kayu pengusung mezbah itu.', 'id', 'TB'),
  ('4', 'bil', 'Bilangan', 4, 12, 'Lalu mereka harus mengambil segala perkakas yang dipakai untuk menyelenggarakan kebaktian di tempat kudus, meletakkannya di atas sehelai kain ungu tua dan menudunginya dengan tudung dari kulit lumba-lumba, kemudian meletakkannya di atas usungan.', 'id', 'TB'),
  ('4', 'bil', 'Bilangan', 4, 13, 'Dan mereka harus membersihkan mezbah itu dari abu, lalu membentangkan sehelai kain ungu muda di atasnya,', 'id', 'TB'),
  ('4', 'bil', 'Bilangan', 4, 14, 'sesudah itu meletakkan di atasnya segala perkakasnya yang dipakai untuk mengurusnya, yakni perbaraan, garpu, penyodok, bokor penyiraman, segala perkakas mezbah itu, dan di atasnya mereka harus membentangkan tutup dari kulit lumba-lumba, kemudian mereka harus memasang kayu-kayu pengusung mezbah itu.', 'id', 'TB'),
  ('4', 'bil', 'Bilangan', 4, 15, 'Setelah Harun dan anak-anaknya selesai menudungi barang-barang kudus dan segala perkakas tempat kudus, pada waktu perkemahan akan berangkat, barulah orang Kehat boleh masuk ke dalam untuk mengangkat barang-barang itu; tetapi janganlah mereka kena kepada barang-barang kudus itu, nanti mereka mati. Jadi itulah barang-barang di Kemah Pertemuan yang harus diangkat bani Kehat.', 'id', 'TB'),
  ('4', 'bil', 'Bilangan', 4, 16, 'Tetapi Eleazar, anak imam Harun, bertanggung jawab atas minyak untuk penerangan, ukupan dari wangi-wangian, korban sajian yang tetap dan minyak urapan; ia bertanggung jawab atas segenap Kemah Suci dan segala isinya, yakni barang-barang kudus dan perabotannya."', 'id', 'TB'),
  ('4', 'bil', 'Bilangan', 4, 17, 'TUHAN berfirman kepada Musa dan Harun:', 'id', 'TB'),
  ('4', 'bil', 'Bilangan', 4, 18, '"Perhatikanlah supaya puak Kehat dan kaum-kaumnya jangan musnah binasa dari tengah-tengah orang Lewi.', 'id', 'TB'),
  ('4', 'bil', 'Bilangan', 4, 19, 'Inilah yang harus kamu lakukan bagi mereka, supaya mereka tinggal hidup dan jangan mati, apabila mereka mendekat ke barang-barang maha kudus: Harun dan anak-anaknya haruslah masuk ke dalam dan menempatkan mereka masing-masing di tempat tugasnya dekat barang yang harus diangkat.', 'id', 'TB'),
  ('4', 'bil', 'Bilangan', 4, 20, 'Tetapi janganlah orang Kehat masuk ke dalam untuk melihat barang-barang kudus itu walau sesaatpun, nanti mereka mati."', 'id', 'TB'),
  ('4', 'bil', 'Bilangan', 4, 21, 'TUHAN berfirman kepada Musa:', 'id', 'TB'),
  ('4', 'bil', 'Bilangan', 4, 22, '"Hitunglah juga jumlah bani Gerson menurut puak dan kaum-kaum mereka.', 'id', 'TB'),
  ('4', 'bil', 'Bilangan', 4, 23, 'Catatlah mereka yang berumur tiga puluh tahun ke atas sampai yang berumur lima puluh tahun, yakni setiap orang yang wajib tugas, supaya mereka melakukan pekerjaan jabatan di Kemah Pertemuan.', 'id', 'TB'),
  ('4', 'bil', 'Bilangan', 4, 24, 'Inilah tugas kaum-kaum Gerson dalam hal pekerjaan jabatan dan pengangkatan barang itu:', 'id', 'TB'),
  ('4', 'bil', 'Bilangan', 4, 25, 'mereka harus mengangkat tenda-tenda Kemah Suci, dan Kemah Pertemuan tudungnya dan tudung dari kulit lumba-lumba yang ada di atasnya, tirai pintu Kemah Pertemuan,', 'id', 'TB'),
  ('4', 'bil', 'Bilangan', 4, 26, 'layar-layar pelataran dan tirai pintu gerbang pelataran yang ada sekeliling Kemah Suci dan mezbah, dengan talinya dan segala perkakas untuk pekerjaan jabatan mereka; dan mereka harus melakukan segala tugas yang perlu berkenaan dengan semuanya itu.', 'id', 'TB'),
  ('4', 'bil', 'Bilangan', 4, 27, 'Seluruh pekerjaan jabatan bani Gerson harus dilakukan sesuai dengan perintah Harun dan anak-anaknya, yakni segala tugas pengangkatan barang dan pekerjaan jabatan itu; kamu harus membuat mereka penanggung jawab atas segala yang harus diangkat mereka.', 'id', 'TB'),
  ('4', 'bil', 'Bilangan', 4, 28, 'Itulah tugas kaum-kaum bani Gerson di Kemah Pertemuan. Mereka harus mengerjakan di bawah pimpinan Itamar, anak imam Harun itu.', 'id', 'TB'),
  ('4', 'bil', 'Bilangan', 4, 29, 'Orang Merari haruslah kaucatat menurut kaum-kaum yang ada dalam puak mereka.', 'id', 'TB'),
  ('4', 'bil', 'Bilangan', 4, 30, 'Catatlah mereka yang berumur tiga puluh tahun ke atas sampai yang berumur lima puluh tahun, yakni setiap orang yang kena wajib tugas, supaya mereka melakukan pekerjaan jabatan pada Kemah Pertemuan.', 'id', 'TB'),
  ('4', 'bil', 'Bilangan', 4, 31, 'Inilah yang wajib diangkat mereka berhubung dengan seluruh pekerjaan jabatan mereka di Kemah Pertemuan: papan-papan Kemah Suci, kayu-kayu lintangnya, tiang-tiangnya, alas-alasnya,', 'id', 'TB'),
  ('4', 'bil', 'Bilangan', 4, 32, 'tiang-tiang pelataran sekelilingnya, alas-alasnya, patok-patok dan tali-talinya, serta segala perkakasnya; semuanya termasuk tugas mereka. Dengan terperinci haruslah kamu tunjuk perkakas yang wajib diangkat mereka itu.', 'id', 'TB'),
  ('4', 'bil', 'Bilangan', 4, 33, 'Itulah tugas kaum-kaum bani Merari, yakni seluruh pekerjaan jabatan mereka di Kemah Pertemuan, yang harus dilakukan di bawah pimpinan Itamar, anak imam Harun."', 'id', 'TB'),
  ('4', 'bil', 'Bilangan', 4, 34, 'Demikianlah Musa dan Harun dengan para pemimpin umat Israel mencatat bani Kehat menurut kaum-kaum yang ada dalam puak mereka,', 'id', 'TB'),
  ('4', 'bil', 'Bilangan', 4, 35, 'yakni orang-orang yang berumur tiga puluh tahun ke atas sampai yang berumur lima puluh tahun, setiap orang yang kena wajib tugas berhubung dengan pekerjaan jabatan di Kemah Pertemuan.', 'id', 'TB'),
  ('4', 'bil', 'Bilangan', 4, 36, 'Maka jumlah pencatatan mereka menurut kaum-kaum mereka ada dua ribu tujuh ratus lima puluh orang.', 'id', 'TB'),
  ('4', 'bil', 'Bilangan', 4, 37, 'Itulah orang-orang yang dicatat dari kaum-kaum Kehat, semua orang yang melakukan pekerjaan jabatan di Kemah Pertemuan, yakni mereka yang dicatat oleh Musa dan Harun, sesuai dengan titah TUHAN dengan perantaraan Musa.', 'id', 'TB'),
  ('4', 'bil', 'Bilangan', 4, 38, 'Bani Gerson yang dicatat menurut kaum-kaum yang ada dalam puak mereka,', 'id', 'TB'),
  ('4', 'bil', 'Bilangan', 4, 39, 'yaitu orang-orang yang berumur tiga puluh tahun ke atas sampai yang berumur lima puluh tahun, setiap orang yang kena wajib tugas berhubung dengan pekerjaan jabatan di Kemah Pertemuan,', 'id', 'TB'),
  ('4', 'bil', 'Bilangan', 4, 40, 'jadi mereka yang dicatat menurut kaum-kaum yang ada dalam puak mereka, berjumlah dua ribu enam ratus tiga puluh orang.', 'id', 'TB'),
  ('4', 'bil', 'Bilangan', 4, 41, 'Itulah jumlah pencatatan kaum-kaum bani Gerson, semua orang yang melakukan pekerjaan jabatan di Kemah Pertemuan, yakni mereka yang dicatat oleh Musa dan Harun sesuai dengan titah TUHAN.', 'id', 'TB'),
  ('4', 'bil', 'Bilangan', 4, 42, 'Bani Merari yang dicatat menurut kaum-kaum yang ada dalam puak mereka,', 'id', 'TB'),
  ('4', 'bil', 'Bilangan', 4, 43, 'yaitu orang-orang yang berumur tiga puluh tahun ke atas sampai yang berumur lima puluh tahun, setiap orang yang kena wajib tugas berhubung dengan pekerjaan jabatan di Kemah Pertemuan,', 'id', 'TB'),
  ('4', 'bil', 'Bilangan', 4, 44, 'jadi mereka yang dicatat menurut kaum-kaum mereka, berjumlah tiga ribu dua ratus orang.', 'id', 'TB'),
  ('4', 'bil', 'Bilangan', 4, 45, 'Itulah jumlah pencatatan kaum-kaum bani Merari, yakni mereka yang dicatat oleh Musa dan Harun, sesuai dengan titah TUHAN dengan perantaraan Musa.', 'id', 'TB'),
  ('4', 'bil', 'Bilangan', 4, 46, 'Semua orang Lewi yang dicatat oleh Musa dan Harun dengan para pemimpin Israel menurut kaum-kaum yang ada dalam puak-puak mereka,', 'id', 'TB'),
  ('4', 'bil', 'Bilangan', 4, 47, 'yakni orang-orang yang berumur tiga puluh tahun ke atas sampai yang berumur lima puluh tahun, setiap orang yang wajib melakukan pekerjaan jabatan di Kemah Pertemuan dan pekerjaan pengangkatan barang,', 'id', 'TB'),
  ('4', 'bil', 'Bilangan', 4, 48, 'jadi mereka yang dicatat, berjumlah delapan ribu lima ratus delapan puluh orang.', 'id', 'TB'),
  ('4', 'bil', 'Bilangan', 4, 49, 'Sesuai dengan titah TUHAN dengan perantaraan Musa, maka mereka masing-masing dibuat penanggung jawab atas apa yang harus dikerjakan dan diangkatnya. Demikianlah mereka dicatat, seperti yang diperintahkan TUHAN kepada Musa.', 'id', 'TB'),
  ('4', 'bil', 'Bilangan', 5, 1, 'TUHAN berfirman kepada Musa:', 'id', 'TB'),
  ('4', 'bil', 'Bilangan', 5, 2, '"Perintahkanlah kepada orang Israel, supaya semua orang yang sakit kusta, semua orang yang mengeluarkan lelehan, dan semua orang yang najis oleh mayat disuruh meninggalkan tempat perkemahan;', 'id', 'TB'),
  ('4', 'bil', 'Bilangan', 5, 3, 'baik laki-laki maupun perempuan haruslah kausuruh pergi; ke luar tempat perkemahan haruslah mereka kausuruh pergi, supaya mereka jangan menajiskan tempat perkemahan di mana Aku diam di tengah-tengah mereka."', 'id', 'TB'),
  ('4', 'bil', 'Bilangan', 5, 4, 'Maka orang Israel berbuat demikian, mereka menyuruh orang-orang itu meninggalkan tempat perkemahan; seperti yang difirmankan TUHAN kepada Musa, demikianlah diperbuat orang Israel.', 'id', 'TB'),
  ('4', 'bil', 'Bilangan', 5, 5, 'TUHAN berfirman kepada Musa:', 'id', 'TB'),
  ('4', 'bil', 'Bilangan', 5, 6, '"Berbicaralah kepada orang Israel: Apabila seseorang, laki-laki atau perempuan, melakukan sesuatu dosa terhadap sesamanya manusia, dan oleh karena itu berubah setia terhadap TUHAN, sehingga orang itu menjadi bersalah,', 'id', 'TB'),
  ('4', 'bil', 'Bilangan', 5, 7, 'maka haruslah ia mengakui dosa yang telah dilakukannya itu; kemudian membayar tebusan sepenuhnya dengan menambah seperlima, lalu menyerahkannya kepada orang terhadap siapa ia bersalah.', 'id', 'TB'),
  ('4', 'bil', 'Bilangan', 5, 8, 'Tetapi apabila orang itu tidak ada kaumnya, kepada siapa dapat dibayar tebusan salah itu, maka tebusan salah yang harus dibayar itu menjadi kepunyaan TUHAN, dan adalah bagian imam, belum terhitung domba jantan pendamaian yang dipakai untuk mengadakan pendamaian bagi orang itu.', 'id', 'TB'),
  ('4', 'bil', 'Bilangan', 5, 9, 'Dari persembahan-persembahan kudus yang disampaikan orang Israel kepada imam, persembahan khususnya adalah bagian imam.', 'id', 'TB'),
  ('4', 'bil', 'Bilangan', 5, 10, 'Sedang persembahan-persembahan kudus yang dibawa oleh seseorang adalah bagian orang itu sendiri; hanya apa yang diserahkannya kepada seorang imam adalah bagian imam itu."', 'id', 'TB'),
  ('4', 'bil', 'Bilangan', 5, 11, 'TUHAN berfirman kepada Musa:', 'id', 'TB'),
  ('4', 'bil', 'Bilangan', 5, 12, '"Berbicaralah kepada orang Israel dan katakanlah kepada mereka: Apabila isteri seseorang berbuat serong dan tidak setia terhadap suaminya,', 'id', 'TB'),
  ('4', 'bil', 'Bilangan', 5, 13, 'dan laki-laki lain tidur dan bersetubuh dengan perempuan itu, dengan tidak diketahui suaminya, karena tinggal rahasia bahwa perempuan itu mencemarkan dirinya, tidak ada saksi terhadap dia, dia tidak kedapatan,', 'id', 'TB'),
  ('4', 'bil', 'Bilangan', 5, 14, 'dan apabila kemudian roh cemburu menguasai suami itu, sehingga ia menjadi cemburu terhadap isterinya, dan perempuan itu memang telah mencemarkan dirinya, atau apabila roh cemburu menguasai suami itu, sehingga ia menjadi cemburu terhadap isterinya, walaupun perempuan itu tidak mencemarkan dirinya,', 'id', 'TB'),
  ('4', 'bil', 'Bilangan', 5, 15, 'maka haruslah orang itu membawa isterinya kepada imam. Dan orang itu harus membawa persembahan karena perempuan itu sebanyak sepersepuluh efa tepung jelai, yang ke atasnya tidak dituangkannya minyak dan yang tidak dibubuhinya kemenyan, karena korban itu ialah korban sajian cemburuan, suatu korban peringatan yang mengingatkan kepada kedurjanaan.', 'id', 'TB'),
  ('4', 'bil', 'Bilangan', 5, 16, 'Maka haruslah imam menyuruh perempuan itu mendekat dan menghadapkannya kepada TUHAN.', 'id', 'TB'),
  ('4', 'bil', 'Bilangan', 5, 17, 'Lalu imam harus membawa air kudus dalam suatu tempayan tanah, kemudian harus memungut debu yang ada di lantai Kemah Suci dan membubuhnya ke dalam air itu.', 'id', 'TB'),
  ('4', 'bil', 'Bilangan', 5, 18, 'Apabila imam sudah menghadapkan perempuan itu kepada TUHAN, haruslah ia menguraikan rambut perempuan itu, lalu meletakkan korban peringatan, yakni korban sajian cemburuan, ke atas telapak tangan perempuan itu, sedang di tangan imam haruslah ada air pahit yang mendatangkan kutuk.', 'id', 'TB'),
  ('4', 'bil', 'Bilangan', 5, 19, 'Maka haruslah imam menyumpah perempuan itu dengan berkata kepadanya: Jika tidak benar ada laki-laki yang tidur dengan engkau, dan jika tidak engkau berbuat serong kepada kecemaran, padahal engkau di bawah kuasa suamimu, maka luputlah engkau dari air pahit yang mendatangkan kutuk ini;', 'id', 'TB'),
  ('4', 'bil', 'Bilangan', 5, 20, 'tetapi jika engkau, padahal engkau di bawah kuasa suamimu, berbuat serong dan mencemarkan dirimu, oleh karena orang lain dari suamimu sendiri bersetubuh dengan engkau?', 'id', 'TB'),
  ('4', 'bil', 'Bilangan', 5, 21, 'dalam hal ini haruslah imam menyumpah perempuan itu dengan sumpah kutuk, dan haruslah imam berkata kepada perempuan itu?maka TUHAN kiranya membuat engkau menjadi sumpah kutuk di tengah-tengah bangsamu dengan mengempiskan pahamu dan mengembungkan perutmu,', 'id', 'TB'),
  ('4', 'bil', 'Bilangan', 5, 22, 'sebab air yang mendatangkan kutuk ini akan masuk ke dalam tubuhmu untuk mengembungkan perutmu dan mengempiskan pahamu. Dan haruslah perempuan itu berkata: Amin, amin.', 'id', 'TB'),
  ('4', 'bil', 'Bilangan', 5, 23, 'Lalu imam harus menuliskan kutuk itu pada sehelai kertas dan menghapusnya dengan air pahit itu,', 'id', 'TB'),
  ('4', 'bil', 'Bilangan', 5, 24, 'dan ia harus memberi perempuan itu minum air pahit yang mendatangkan kutuk itu, dan air itu akan masuk ke dalam badannya dan menyebabkan sakit yang pedih.', 'id', 'TB'),
  ('4', 'bil', 'Bilangan', 5, 25, 'Maka haruslah imam mengambil korban sajian cemburuan dari tangan perempuan itu lalu mengunjukkannya ke hadapan TUHAN, dan membawanya ke mezbah.', 'id', 'TB'),
  ('4', 'bil', 'Bilangan', 5, 26, 'Sesudah itu haruslah imam mengambil segenggam dari korban sajian itu sebagai bagian ingat-ingatannya dan membakarnya di atas mezbah, kemudian memberi perempuan itu minum air itu.', 'id', 'TB'),
  ('4', 'bil', 'Bilangan', 5, 27, 'Setelah terjadi demikian, apabila perempuan itu memang mencemarkan dirinya dan berubah setia terhadap suaminya, air yang mendatangkan sumpah serapah itu akan masuk ke badannya dan menyebabkan sakit yang pedih, sehingga perutnya mengembung dan pahanya mengempis, dan perempuan itu akan menjadi sumpah kutuk di antara bangsanya.', 'id', 'TB'),
  ('4', 'bil', 'Bilangan', 5, 28, 'Tetapi apabila perempuan itu tidak mencemarkan dirinya, melainkan ia suci, maka ia akan bebas dan akan dapat beranak."', 'id', 'TB'),
  ('4', 'bil', 'Bilangan', 5, 29, 'Itulah hukum tentang perkara cemburuan, kalau seorang perempuan telah berbuat serong dan mencemarkan dirinya, padahal ia di bawah kuasa suaminya,', 'id', 'TB'),
  ('4', 'bil', 'Bilangan', 5, 30, 'atau kalau roh cemburu menguasai seorang laki-laki, sehingga ia cemburu terhadap isterinya; ia harus menghadapkan perempuan itu kepada TUHAN dan imam haruslah melaksanakan seluruh hukum ini kepada perempuan itu.', 'id', 'TB'),
  ('4', 'bil', 'Bilangan', 5, 31, 'Laki-laki itu akan bebas dari pada salah, tetapi perempuan itu haruslah menanggung akibat kesalahannya.', 'id', 'TB'),
  ('4', 'bil', 'Bilangan', 6, 1, 'TUHAN berfirman kepada Musa:', 'id', 'TB'),
  ('4', 'bil', 'Bilangan', 6, 2, '"Berbicaralah kepada orang Israel dan katakanlah kepada mereka: Apabila seseorang, laki-laki atau perempuan, mengucapkan nazar khusus, yakni nazar orang nazir, untuk mengkhususkan dirinya bagi TUHAN,', 'id', 'TB'),
  ('4', 'bil', 'Bilangan', 6, 3, 'maka haruslah ia menjauhkan dirinya dari anggur dan minuman yang memabukkan, jangan meminum cuka anggur atau cuka minuman yang memabukkan dan jangan meminum sesuatu minuman yang dibuat dari buah anggur, dan jangan memakan buah anggur, baik yang segar maupun yang kering.', 'id', 'TB'),
  ('4', 'bil', 'Bilangan', 6, 4, 'Selama waktu kenazirannya janganlah ia makan sesuatu apapun yang berasal dari pohon anggur, dari bijinya sampai kepada pucuk rantingnya.', 'id', 'TB'),
  ('4', 'bil', 'Bilangan', 6, 5, 'Selama waktu nazarnya sebagai orang nazir janganlah pisau cukur lalu di kepalanya; sampai genap waktunya ia mengkhususkan dirinya bagi TUHAN, haruslah ia tetap kudus dan membiarkan rambutnya tumbuh panjang.', 'id', 'TB'),
  ('4', 'bil', 'Bilangan', 6, 6, 'Selama waktunya ia mengkhususkan dirinya bagi TUHAN, janganlah ia dekat kepada mayat orang;', 'id', 'TB'),
  ('4', 'bil', 'Bilangan', 6, 7, 'bahkan apabila mati ayahnya ataupun ibunya, saudaranya laki-laki ataupun saudaranya perempuan, janganlah ia menajiskan dirinya kepada mereka, sebab tanda kenaziran bagi Allahnya ada di atas kepalanya.', 'id', 'TB'),
  ('4', 'bil', 'Bilangan', 6, 8, 'Selama waktu kenazirannya ia kudus bagi TUHAN.', 'id', 'TB'),
  ('4', 'bil', 'Bilangan', 6, 9, 'Tetapi apabila seseorang mati di dekatnya dengan sangat tiba-tiba, sehingga ia menajiskan rambut kenazirannya, maka haruslah ia mencukur rambutnya pada hari pentahirannya, yaitu pada hari yang ketujuh haruslah ia mencukurnya.', 'id', 'TB'),
  ('4', 'bil', 'Bilangan', 6, 10, 'Pada hari yang kedelapan haruslah ia membawa dua ekor burung tekukur atau dua ekor anak burung merpati kepada imam, ke pintu Kemah Pertemuan.', 'id', 'TB'),
  ('4', 'bil', 'Bilangan', 6, 11, 'Maka haruslah imam mengolah yang seekor menjadi korban penghapus dosa dan yang lain menjadi korban bakaran, dan mengadakan pendamaian bagi dia, oleh karena dia telah berdosa dengan berada dekat mayat. Pada hari itu juga ia harus menguduskan kepalanya', 'id', 'TB'),
  ('4', 'bil', 'Bilangan', 6, 12, 'dan mengkhususkan waktu kenazirannya bagi TUHAN. Ia harus membawa seekor domba jantan berumur setahun menjadi korban penebus salah. Hari-hari yang sudah lewat dianggap batal, karena rambut kenazirannya telah menjadi najis.', 'id', 'TB'),
  ('4', 'bil', 'Bilangan', 6, 13, 'Dan inilah hukum tentang seorang nazir. Apabila waktu kenazirannya genap, ia harus dibawa ke pintu Kemah Pertemuan,', 'id', 'TB'),
  ('4', 'bil', 'Bilangan', 6, 14, 'dan ia harus mempersembahkan sebagai persembahannya kepada TUHAN seekor domba jantan berumur setahun yang tidak bercela untuk korban bakaran dan seekor domba betina berumur setahun yang tidak bercela untuk korban penghapus dosa dan seekor domba jantan yang tidak bercela untuk korban keselamatan,', 'id', 'TB'),
  ('4', 'bil', 'Bilangan', 6, 15, 'juga sebakul roti yang tidak beragi, yakni roti bundar dari tepung yang terbaik, yang diolah dengan minyak, dan roti tipis yang tidak beragi diolesi dengan minyak, serta dengan korban sajian dan korban-korban curahannya.', 'id', 'TB'),
  ('4', 'bil', 'Bilangan', 6, 16, 'Lalu haruslah imam membawa semuanya itu ke hadapan TUHAN dan mengolah korban penghapus dosa dan korban bakarannya;', 'id', 'TB'),
  ('4', 'bil', 'Bilangan', 6, 17, 'domba jantan itu haruslah diolahnya sebagai korban keselamatan bagi TUHAN, beserta sebakul roti yang tidak beragi itu; juga haruslah imam mengolah korban sajian dan korban curahannya.', 'id', 'TB'),
  ('4', 'bil', 'Bilangan', 6, 18, 'Maka haruslah orang nazir itu mencukur rambut kenazirannya di depan pintu Kemah Pertemuan, lalu mengambil rambut kenazirannya itu dan melemparkannya ke dalam api yang di bawah korban keselamatan.', 'id', 'TB'),
  ('4', 'bil', 'Bilangan', 6, 19, 'Imam haruslah mengambil paha depan domba jantan itu, sesudah dimasak, dan satu roti bundar yang tidak beragi dari dalam bakul, dengan satu roti tipis yang tidak beragi, lalu meletakkannya ke atas telapak tangan orang nazir itu, setelah orang ini mencukur rambut kenazirannya;', 'id', 'TB'),
  ('4', 'bil', 'Bilangan', 6, 20, 'kemudian haruslah imam mengunjukkan semuanya itu ke hadapan TUHAN sebagai persembahan unjukan; semuanya itu menjadi bagian kudus bagi imam, beserta dada persembahan unjukan dan beserta paha persembahan khusus. Sesudah itu barulah boleh orang nazir itu minum anggur."', 'id', 'TB'),
  ('4', 'bil', 'Bilangan', 6, 21, 'Itulah hukum tentang orang nazir yang menazarkan persembahannya kepada TUHAN berdasarkan kenazirannya, belum dihitung apa yang ia mampu mempersembahkan di samping itu. Sesuai dengan bunyi nazar yang diikrarkannya, demikianlah harus dilakukannya berdasarkan hukum tentang kenazirannya.', 'id', 'TB'),
  ('4', 'bil', 'Bilangan', 6, 22, 'TUHAN berfirman kepada Musa:', 'id', 'TB'),
  ('4', 'bil', 'Bilangan', 6, 23, '"Berbicaralah kepada Harun dan anak-anaknya: Beginilah harus kamu memberkati orang Israel, katakanlah kepada mereka:', 'id', 'TB'),
  ('4', 'bil', 'Bilangan', 6, 24, 'TUHAN memberkati engkau dan melindungi engkau;', 'id', 'TB'),
  ('4', 'bil', 'Bilangan', 6, 25, 'TUHAN menyinari engkau dengan wajah-Nya dan memberi engkau kasih karunia;', 'id', 'TB'),
  ('4', 'bil', 'Bilangan', 6, 26, 'TUHAN menghadapkan wajah-Nya kepadamu dan memberi engkau damai sejahtera.', 'id', 'TB'),
  ('4', 'bil', 'Bilangan', 6, 27, 'Demikianlah harus mereka meletakkan nama-Ku atas orang Israel, maka Aku akan memberkati mereka."', 'id', 'TB'),
  ('4', 'bil', 'Bilangan', 7, 1, 'Pada waktu Musa selesai mendirikan Kemah Suci, diurapinya dan dikuduskannyalah itu dengan segala perabotannya, juga mezbah dengan segala perkakasnya; dan setelah diurapi dan dikuduskannya semuanya itu,', 'id', 'TB'),
  ('4', 'bil', 'Bilangan', 7, 2, 'maka para pemimpin Israel, para kepala suku mereka, mempersembahkan persembahan. Mereka itu ialah para pemimpin suku yang bertanggung jawab atas pencatatan itu.', 'id', 'TB'),
  ('4', 'bil', 'Bilangan', 7, 3, 'Sebagai persembahan dibawa mereka ke hadapan TUHAN: enam kereta beratap dengan dua belas ekor lembu; satu kereta untuk dua orang pemimpin dan satu ekor lembu untuk satu orang pemimpin, lalu mereka membawa semuanya itu ke depan Kemah Suci.', 'id', 'TB'),
  ('4', 'bil', 'Bilangan', 7, 4, 'Kemudian TUHAN berfirman kepada Musa:', 'id', 'TB'),
  ('4', 'bil', 'Bilangan', 7, 5, '"Terimalah semuanya itu dari mereka, supaya dipergunakan untuk pekerjaan pada Kemah Pertemuan; berikanlah semuanya itu kepada orang Lewi, sesuai dengan keperluan pekerjaan masing-masing."', 'id', 'TB'),
  ('4', 'bil', 'Bilangan', 7, 6, 'Lalu Musa menerima kereta-kereta dan lembu-lembu itu dan memberikannya kepada orang Lewi;', 'id', 'TB'),
  ('4', 'bil', 'Bilangan', 7, 7, 'dua kereta dengan empat ekor lembu diberikannya kepada bani Gerson, sesuai dengan keperluan pekerjaan mereka,', 'id', 'TB'),
  ('4', 'bil', 'Bilangan', 7, 8, 'dan empat kereta dengan delapan ekor lembu diberikannya kepada bani Merari, sesuai dengan keperluan pekerjaan mereka di bawah pimpinan Itamar, anak imam Harun itu.', 'id', 'TB'),
  ('4', 'bil', 'Bilangan', 7, 9, 'Tetapi kepada bani Kehat tidak diberikannya apa-apa, karena pekerjaan mereka ialah mengurus barang-barang kudus, yang harus diangkat di atas bahunya.', 'id', 'TB'),
  ('4', 'bil', 'Bilangan', 7, 10, 'Lagi para pemimpin mempersembahkan persembahan pentahbisan mezbah, pada hari mezbah itu diurapi; para pemimpin membawa persembahan mereka ke depan mezbah itu.', 'id', 'TB'),
  ('4', 'bil', 'Bilangan', 7, 11, 'TUHAN berfirman kepada Musa: "Satu pemimpin setiap hari haruslah mempersembahkan persembahannya untuk mentahbiskan mezbah itu."', 'id', 'TB'),
  ('4', 'bil', 'Bilangan', 7, 12, 'Yang mempersembahkan persembahannya pada hari pertama ialah Nahason bin Aminadab, dari suku Yehuda.', 'id', 'TB'),
  ('4', 'bil', 'Bilangan', 7, 13, 'Persembahannya ialah satu pinggan perak, seratus tiga puluh syikal timbangannya, dan satu bokor penyiraman dari perak tujuh puluh syikal beratnya, ditimbang menurut syikal kudus, keduanya berisi tepung yang terbaik, diolah dengan minyak, untuk korban sajian;', 'id', 'TB'),
  ('4', 'bil', 'Bilangan', 7, 14, 'satu cawan sepuluh syikal emas beratnya, berisi ukupan;', 'id', 'TB'),
  ('4', 'bil', 'Bilangan', 7, 15, 'seekor lembu jantan muda, seekor domba jantan dan seekor domba berumur setahun, untuk korban bakaran;', 'id', 'TB'),
  ('4', 'bil', 'Bilangan', 7, 16, 'seekor kambing jantan, untuk korban penghapus dosa;', 'id', 'TB'),
  ('4', 'bil', 'Bilangan', 7, 17, 'dan untuk korban keselamatan dua ekor lembu, lima ekor domba jantan, lima ekor kambing jantan dan lima ekor domba berumur setahun. Itulah persembahan Nahason bin Aminadab.', 'id', 'TB'),
  ('4', 'bil', 'Bilangan', 7, 18, 'Pada hari kedua Netaneel bin Zuar, pemimpin suku Isakhar, mempersembahkan persembahan.', 'id', 'TB'),
  ('4', 'bil', 'Bilangan', 7, 19, 'Sebagai persembahannya dipersembahkannya satu pinggan perak, seratus tiga puluh syikal timbangannya, dan satu bokor penyiraman dari perak, tujuh puluh syikal beratnya, ditimbang menurut syikal kudus, keduanya berisi tepung yang terbaik, diolah dengan minyak, untuk korban sajian;', 'id', 'TB'),
  ('4', 'bil', 'Bilangan', 7, 20, 'satu cawan, sepuluh syikal emas beratnya, berisi ukupan;', 'id', 'TB'),
  ('4', 'bil', 'Bilangan', 7, 21, 'seekor lembu jantan muda, seekor domba jantan dan seekor domba berumur setahun, untuk korban bakaran;', 'id', 'TB'),
  ('4', 'bil', 'Bilangan', 7, 22, 'seekor kambing jantan untuk korban penghapus dosa;', 'id', 'TB'),
  ('4', 'bil', 'Bilangan', 7, 23, 'dan untuk korban keselamatan dua ekor lembu, lima ekor domba jantan, lima ekor kambing jantan dan lima ekor domba berumur setahun. Itulah persembahan Netaneel bin Zuar.', 'id', 'TB'),
  ('4', 'bil', 'Bilangan', 7, 24, 'Pada hari ketiga: pemimpin bani Zebulon, Eliab bin Helon.', 'id', 'TB'),
  ('4', 'bil', 'Bilangan', 7, 25, 'Persembahannya ialah satu pinggan perak, seratus tiga puluh syikal timbangannya, dan satu bokor penyiraman dari perak tujuh puluh syikal beratnya, ditimbang menurut syikal kudus, keduanya berisi tepung yang terbaik, diolah dengan minyak, untuk korban sajian;', 'id', 'TB'),
  ('4', 'bil', 'Bilangan', 7, 26, 'satu cawan, sepuluh syikal emas beratnya, berisi ukupan;', 'id', 'TB'),
  ('4', 'bil', 'Bilangan', 7, 27, 'seekor lembu jantan muda, seekor domba jantan dan seekor domba berumur setahun, untuk korban bakaran;', 'id', 'TB'),
  ('4', 'bil', 'Bilangan', 7, 28, 'seekor kambing jantan untuk korban penghapus dosa;', 'id', 'TB'),
  ('4', 'bil', 'Bilangan', 7, 29, 'dan untuk korban keselamatan dua ekor lembu, lima ekor domba jantan, lima ekor kambing jantan dan lima ekor domba berumur setahun. Itulah persembahan Eliab bin Helon.', 'id', 'TB'),
  ('4', 'bil', 'Bilangan', 7, 30, 'Pada hari keempat: pemimpin bani Ruben, Elizur bin Syedeur.', 'id', 'TB'),
  ('4', 'bil', 'Bilangan', 7, 31, 'Persembahannya ialah satu pinggan perak, seratus tiga puluh syikal timbangannya, dan satu bokor penyiraman dari perak, tujuh puluh syikal beratnya, ditimbang menurut syikal kudus, keduanya berisi tepung yang terbaik diolah dengan minyak, untuk korban sajian;', 'id', 'TB'),
  ('4', 'bil', 'Bilangan', 7, 32, 'satu cawan, sepuluh syikal emas beratnya, berisi ukupan;', 'id', 'TB'),
  ('4', 'bil', 'Bilangan', 7, 33, 'seekor lembu jantan muda, seekor domba jantan dan seekor domba berumur setahun, untuk korban bakaran;', 'id', 'TB'),
  ('4', 'bil', 'Bilangan', 7, 34, 'seekor kambing jantan untuk korban penghapus dosa;', 'id', 'TB'),
  ('4', 'bil', 'Bilangan', 7, 35, 'dan untuk korban keselamatan dua ekor lembu, lima ekor domba jantan, lima ekor kambing jantan dan lima ekor domba berumur setahun. Itulah persembahan Elizur bin Syedeur.', 'id', 'TB'),
  ('4', 'bil', 'Bilangan', 7, 36, 'Pada hari kelima: pemimpin bani Simeon, Selumiel bin Zurisyadai.', 'id', 'TB'),
  ('4', 'bil', 'Bilangan', 7, 37, 'Persembahannya ialah satu pinggan perak, seratus tiga puluh syikal timbangannya, dan satu bokor penyiraman dari perak, tujuh puluh syikal beratnya, ditimbang menurut syikal kudus, keduanya berisi tepung yang terbaik, diolah dengan minyak, untuk korban sajian;', 'id', 'TB'),
  ('4', 'bil', 'Bilangan', 7, 38, 'satu cawan, sepuluh syikal emas beratnya, berisi ukupan;', 'id', 'TB'),
  ('4', 'bil', 'Bilangan', 7, 39, 'seekor lembu jantan muda, seekor domba jantan dan seekor domba berumur setahun, untuk korban bakaran;', 'id', 'TB'),
  ('4', 'bil', 'Bilangan', 7, 40, 'seekor kambing jantan untuk korban penghapus dosa;', 'id', 'TB'),
  ('4', 'bil', 'Bilangan', 7, 41, 'dan untuk korban keselamatan dua ekor lembu, lima ekor domba jantan, lima ekor kambing jantan dan lima ekor domba berumur setahun. Itulah persembahan Selumiel bin Zurisyadai.', 'id', 'TB'),
  ('4', 'bil', 'Bilangan', 7, 42, 'Pada hari keenam: pemimpin bani Gad, Elyasaf bin Rehuel.', 'id', 'TB'),
  ('4', 'bil', 'Bilangan', 7, 43, 'Persembahannya ialah satu pinggan perak, seratus tiga puluh syikal timbangannya, dan satu bokor penyiraman dari perak, tujuh puluh syikal beratnya, ditimbang menurut syikal kudus, keduanya berisi tepung yang terbaik, diolah dengan minyak, untuk korban sajian;', 'id', 'TB'),
  ('4', 'bil', 'Bilangan', 7, 44, 'satu cawan, sepuluh syikal emas beratnya, berisi ukupan;', 'id', 'TB'),
  ('4', 'bil', 'Bilangan', 7, 45, 'seekor lembu jantan muda, seekor domba jantan dan seekor domba berumur setahun, untuk korban bakaran;', 'id', 'TB'),
  ('4', 'bil', 'Bilangan', 7, 46, 'seekor kambing jantan untuk korban penghapus dosa;', 'id', 'TB'),
  ('4', 'bil', 'Bilangan', 7, 47, 'dan untuk korban keselamatan dua ekor lembu, lima ekor domba jantan, lima ekor kambing jantan dan lima ekor domba berumur setahun. Itulah persembahan Elyasaf bin Rehuel.', 'id', 'TB'),
  ('4', 'bil', 'Bilangan', 7, 48, 'Pada hari ketujuh: pemimpin bani Efraim, Elisama bin Amihud.', 'id', 'TB'),
  ('4', 'bil', 'Bilangan', 7, 49, 'Persembahannya ialah satu pinggan perak, seratus tiga puluh syikal timbangannya, dan satu bokor penyiraman dari perak, tujuh puluh syikal beratnya, ditimbang menurut syikal kudus, keduanya berisi tepung yang terbaik, diolah dengan minyak, untuk korban sajian;', 'id', 'TB'),
  ('4', 'bil', 'Bilangan', 7, 50, 'satu cawan, sepuluh syikal emas beratnya, berisi ukupan;', 'id', 'TB'),
  ('4', 'bil', 'Bilangan', 7, 51, 'seekor lembu jantan muda, seekor domba jantan dan seekor domba berumur setahun, untuk korban bakaran;', 'id', 'TB'),
  ('4', 'bil', 'Bilangan', 7, 52, 'seekor kambing jantan untuk korban penghapus dosa;', 'id', 'TB'),
  ('4', 'bil', 'Bilangan', 7, 53, 'dan untuk korban keselamatan dua ekor lembu, lima ekor domba jantan, lima ekor kambing jantan dan lima ekor domba berumur setahun. Itulah persembahan Elisama bin Amihud.', 'id', 'TB'),
  ('4', 'bil', 'Bilangan', 7, 54, 'Pada hari kedelapan: pemimpin bani Manasye, Gamaliel bin Pedazur.', 'id', 'TB'),
  ('4', 'bil', 'Bilangan', 7, 55, 'Persembahannya ialah satu pinggan perak, seratus tiga puluh syikal timbangannya, dan satu bokor penyiraman dari perak, tujuh puluh syikal beratnya, ditimbang menurut syikal kudus, keduanya berisi tepung yang terbaik, diolah dengan minyak, untuk korban sajian;', 'id', 'TB'),
  ('4', 'bil', 'Bilangan', 7, 56, 'satu cawan, sepuluh syikal emas beratnya, berisi ukupan;', 'id', 'TB'),
  ('4', 'bil', 'Bilangan', 7, 57, 'seekor lembu jantan muda, seekor domba jantan dan seekor domba berumur setahun, untuk korban bakaran;', 'id', 'TB'),
  ('4', 'bil', 'Bilangan', 7, 58, 'seekor kambing jantan untuk korban penghapus dosa;', 'id', 'TB'),
  ('4', 'bil', 'Bilangan', 7, 59, 'dan untuk korban keselamatan dua ekor lembu, lima ekor domba jantan, lima ekor kambing jantan dan lima ekor domba berumur setahun. Itulah persembahan Gamaliel bin Pedazur.', 'id', 'TB'),
  ('4', 'bil', 'Bilangan', 7, 60, 'Pada hari kesembilan: pemimpin bani Benyamin, Abidan bin Gideoni.', 'id', 'TB'),
  ('4', 'bil', 'Bilangan', 8, 1, 'TUHAN berfirman kepada Musa:', 'id', 'TB'),
  ('4', 'bil', 'Bilangan', 8, 2, '"Berbicaralah kepada Harun dan katakanlah kepadanya: Apabila engkau memasang lampu-lampu itu, haruslah ketujuh lampu itu menerangi yang di sebelah depan kandil."', 'id', 'TB'),
  ('4', 'bil', 'Bilangan', 8, 3, 'Demikianlah diperbuat Harun. Di sebelah depan kandil dipasangnyalah lampu-lampunya, seperti yang diperintahkan TUHAN kepada Musa.', 'id', 'TB'),
  ('4', 'bil', 'Bilangan', 8, 4, 'Dan beginilah kandil itu dibuat: dari emas tempaan; kandil itu tempaan, baik kakinya maupun kembangnya; sesuai dengan apa yang telah diperlihatkan TUHAN kepada Musa, demikianlah kandil itu dibuatnya.', 'id', 'TB'),
  ('4', 'bil', 'Bilangan', 8, 5, 'TUHAN berfirman kepada Musa:', 'id', 'TB'),
  ('4', 'bil', 'Bilangan', 8, 6, '"Ambillah orang Lewi dari tengah-tengah orang Israel dan tahirkanlah mereka.', 'id', 'TB'),
  ('4', 'bil', 'Bilangan', 8, 7, 'Beginilah harus kaulakukan kepada mereka untuk mentahirkan mereka: percikkanlah kepada mereka air penghapus dosa, kemudian haruslah mereka mencukur seluruh tubuhnya dan mencuci pakaiannya dan dengan demikian mentahirkan dirinya.', 'id', 'TB'),
  ('4', 'bil', 'Bilangan', 8, 8, 'Sesudah itu haruslah mereka mengambil seekor lembu jantan muda dengan korban sajiannya dari tepung yang terbaik, diolah dengan minyak, juga seekor lembu jantan muda yang lain haruslah kauambil untuk korban penghapus dosa.', 'id', 'TB'),
  ('4', 'bil', 'Bilangan', 8, 9, 'Selanjutnya haruslah kausuruh orang Lewi mendekat ke depan Kemah Pertemuan, dan kaupanggil berkumpul segenap umat Israel.', 'id', 'TB'),
  ('4', 'bil', 'Bilangan', 8, 10, 'Apabila engkau telah menyuruh orang Lewi mendekat ke hadapan TUHAN, maka haruslah orang Israel meletakkan tangannya atas orang Lewi itu,', 'id', 'TB'),
  ('4', 'bil', 'Bilangan', 8, 11, 'dan Harun harus mengunjukkan orang Lewi itu sebagai persembahan unjukan dari antara orang Israel di hadapan TUHAN, dan demikianlah mereka diuntukkan melakukan pekerjaan jabatannya bagi TUHAN.', 'id', 'TB'),
  ('4', 'bil', 'Bilangan', 8, 12, 'Setelah orang Lewi meletakkan tangannya atas kepala lembu-lembu jantan muda itu, maka haruslah yang seekor diolah sebagai korban penghapus dosa dan yang lain sebagai korban bakaran bagi TUHAN untuk mengadakan pendamaian bagi orang Lewi.', 'id', 'TB'),
  ('4', 'bil', 'Bilangan', 8, 13, 'Maka haruslah engkau menghadapkan orang Lewi kepada Harun dengan anak-anaknya dan mengunjukkan mereka sebagai persembahan unjukan bagi TUHAN.', 'id', 'TB'),
  ('4', 'bil', 'Bilangan', 8, 14, 'Demikianlah harus engkau mentahirkan mereka dari tengah-tengah orang Israel, supaya orang Lewi itu menjadi kepunyaan-Ku.', 'id', 'TB'),
  ('4', 'bil', 'Bilangan', 8, 15, 'Barulah sesudah itu orang Lewi boleh masuk untuk melakukan pekerjaan jabatannya pada Kemah Pertemuan, sesudah engkau mentahirkan mereka dan mengunjukkan mereka sebagai persembahan unjukan.', 'id', 'TB'),
  ('4', 'bil', 'Bilangan', 8, 16, 'Sebab mereka harus diserahkan dengan sepenuhnya kepada-Ku dari tengah-tengah orang Israel; ganti semua yang terdahulu lahir dari kandungan, yakni semua anak sulung yang ada pada orang Israel, telah Kuambil mereka bagi-Ku.', 'id', 'TB'),
  ('4', 'bil', 'Bilangan', 8, 17, 'Sebab semua anak sulung yang ada pada orang Israel, baik dari manusia maupun dari hewan, adalah kepunyaan-Ku; pada waktu Aku membunuh semua anak sulung di tanah Mesir, Aku telah menguduskan semuanya bagi-Ku.', 'id', 'TB'),
  ('4', 'bil', 'Bilangan', 8, 18, 'Maka Aku mengambil orang Lewi ganti semua anak sulung yang ada pada orang Israel,', 'id', 'TB'),
  ('4', 'bil', 'Bilangan', 8, 19, 'dan Aku menyerahkan orang Lewi dari tengah-tengah orang Israel sebagai pemberian kepada Harun dan anak-anaknya untuk melakukan segala pekerjaan jabatan bagi orang Israel di Kemah Pertemuan, dan untuk mengadakan pendamaian bagi orang Israel, supaya orang Israel jangan kena tulah apabila mereka mendekat ke tempat kudus."', 'id', 'TB'),
  ('4', 'bil', 'Bilangan', 8, 20, 'Lalu Musa, Harun dan segenap umat Israel melakukan yang demikian kepada orang Lewi; tepat seperti yang diperintahkan TUHAN kepada Musa mengenai orang Lewi, demikianlah dilakukan orang Israel kepada mereka.', 'id', 'TB'),
  ('4', 'bil', 'Bilangan', 8, 21, 'Orang Lewi itu menghapus dosa dari dirinya dan mencuci pakaian mereka, kemudian Harun mengunjukkan mereka sebagai persembahan unjukan di hadapan TUHAN, dan mengadakan pendamaian bagi mereka sambil mentahirkan mereka.', 'id', 'TB'),
  ('4', 'bil', 'Bilangan', 8, 22, 'Sesudah itu masuklah orang Lewi untuk melakukan pekerjaan jabatan mereka di Kemah Pertemuan, di bawah pengawasan Harun dan anak-anaknya. Seperti yang diperintahkan TUHAN kepada Musa mengenai orang Lewi, demikianlah dilakukan kepada mereka.', 'id', 'TB'),
  ('4', 'bil', 'Bilangan', 8, 23, 'TUHAN berfirman kepada Musa:', 'id', 'TB'),
  ('4', 'bil', 'Bilangan', 8, 24, '"Inilah yang berlaku bagi orang Lewi: setiap orang yang berumur dua puluh lima tahun ke atas wajib bertugas, supaya ia bekerja pada Kemah Pertemuan,', 'id', 'TB'),
  ('4', 'bil', 'Bilangan', 8, 25, 'tetapi jika ia berumur lima puluh tahun haruslah ia dibebaskan dari pekerjaan itu, sehingga tak usah ia bekerja lebih lama lagi.', 'id', 'TB'),
  ('4', 'bil', 'Bilangan', 8, 26, 'Ia boleh membantu saudara-saudaranya di Kemah Pertemuan dalam menjalankan tugas mereka, tetapi tidak usah lagi ia menjabat pekerjaan itu. Demikianlah harus kaulakukan kepada orang Lewi mengenai tugas mereka."', 'id', 'TB'),
  ('4', 'bil', 'Bilangan', 9, 1, 'TUHAN berfirman kepada Musa di padang gurun Sinai, pada bulan yang pertama tahun yang kedua sesudah mereka keluar dari tanah Mesir:', 'id', 'TB'),
  ('4', 'bil', 'Bilangan', 9, 2, '"Orang Israel harus merayakan Paskah pada waktunya;', 'id', 'TB'),
  ('4', 'bil', 'Bilangan', 9, 3, 'pada hari yang keempat belas bulan ini, pada waktu senja, haruslah kamu merayakannya pada waktu yang ditetapkan, menurut segala ketetapan dan peraturannya haruslah kamu merayakannya."', 'id', 'TB'),
  ('4', 'bil', 'Bilangan', 9, 4, 'Lalu Musa menyuruh orang Israel merayakan Paskah.', 'id', 'TB'),
  ('4', 'bil', 'Bilangan', 9, 5, 'Maka mereka merayakan Paskah pada bulan yang pertama, pada hari yang keempat belas bulan itu, pada waktu senja, di padang gurun Sinai; tepat seperti yang diperintahkan TUHAN kepada Musa, demikianlah dilakukan orang Israel.', 'id', 'TB'),
  ('4', 'bil', 'Bilangan', 9, 6, 'Tetapi ada beberapa orang yang najis oleh karena mayat, sehingga tidak dapat merayakan Paskah pada hari itu. Mereka datang menghadap Musa dan Harun pada hari itu juga,', 'id', 'TB'),
  ('4', 'bil', 'Bilangan', 9, 7, 'lalu berkata kepadanya: "Sungguhpun kami najis oleh karena mayat, dengan dasar apakah kami dicegah mempersembahkan persembahan bagi TUHAN di tengah-tengah orang Israel pada waktu yang ditetapkan?"', 'id', 'TB'),
  ('4', 'bil', 'Bilangan', 9, 8, 'Lalu jawab Musa kepada mereka: "Tunggulah dahulu, aku hendak mendengar apa yang akan diperintahkan TUHAN mengenai kamu."', 'id', 'TB'),
  ('4', 'bil', 'Bilangan', 9, 9, 'Lalu berfirmanlah TUHAN kepada Musa:', 'id', 'TB'),
  ('4', 'bil', 'Bilangan', 9, 10, '"Katakanlah kepada orang Israel: Apabila salah seorang di antara kamu atau keturunanmu najis oleh karena mayat, atau berada dalam perjalanan jauh, maka ia harus juga merayakan Paskah bagi TUHAN.', 'id', 'TB'),
  ('4', 'bil', 'Bilangan', 9, 11, 'Pada bulan yang kedua, pada hari yang keempat belas, pada waktu senja, haruslah orang-orang itu merayakannya; beserta roti yang tidak beragi dan sayur pahit haruslah mereka memakannya.', 'id', 'TB'),
  ('4', 'bil', 'Bilangan', 9, 12, 'Janganlah mereka meninggalkan sebagian dari padanya sampai pagi, dan satu tulangpun tidak boleh dipatahkan mereka. Menurut segala ketetapan Paskah haruslah mereka merayakannya.', 'id', 'TB'),
  ('4', 'bil', 'Bilangan', 9, 13, 'Sebaliknya orang yang tidak najis, dan tidak dalam perjalanan, tetapi lalai merayakan Paskah, orang itu harus dilenyapkan dari antara orang-orang sebangsanya, sebab ia tidak mempersembahkan persembahan yang kepada TUHAN pada waktunya; orang itu akan menanggung akibat dosanya.', 'id', 'TB'),
  ('4', 'bil', 'Bilangan', 9, 14, 'Apabila seorang asing yang telah menetap padamu hendak merayakan Paskah bagi TUHAN, maka haruslah ia merayakannya menurut segala ketetapan dan peraturan Paskah. Satu ketetapan harus berlaku bagi kamu, baik bagi orang asing maupun bagi orang Israel asli."', 'id', 'TB'),
  ('4', 'bil', 'Bilangan', 9, 15, 'Pada hari didirikan Kemah Suci, maka awan itu menutupi Kemah Suci, kemah hukum Allah; dan pada waktu malam sampai pagi awan itu ada di atas Kemah Suci, kelihatan seperti api.', 'id', 'TB'),
  ('4', 'bil', 'Bilangan', 9, 16, 'Demikianlah selalu terjadi: awan itu menutupi Kemah, dan pada waktu malam kelihatan seperti api.', 'id', 'TB'),
  ('4', 'bil', 'Bilangan', 9, 17, 'Dan setiap kali awan itu naik dari atas Kemah, maka orang Israelpun berangkatlah, dan di tempat awan itu diam, di sanalah orang Israel berkemah.', 'id', 'TB'),
  ('4', 'bil', 'Bilangan', 9, 18, 'Atas titah TUHAN orang Israel berangkat dan atas titah TUHAN juga mereka berkemah; selama awan itu diam di atas Kemah Suci, mereka tetap berkemah.', 'id', 'TB'),
  ('4', 'bil', 'Bilangan', 9, 19, 'Apabila awan itu lama tinggal di atas Kemah Suci, maka orang Israel memelihara kewajibannya kepada TUHAN, dan tidaklah mereka berangkat.', 'id', 'TB'),
  ('4', 'bil', 'Bilangan', 9, 20, 'Ada kalanya awan itu hanya tinggal beberapa hari di atas Kemah Suci; maka atas titah TUHAN mereka berkemah dan atas titah TUHAN juga mereka berangkat.', 'id', 'TB'),
  ('4', 'bil', 'Bilangan', 9, 21, 'Ada kalanya awan itu tinggal dari petang sampai pagi; ketika awan itu naik pada waktu pagi, merekapun berangkatlah; baik pada waktu siang baik pada waktu malam, apabila awan itu naik, merekapun berangkatlah.', 'id', 'TB'),
  ('4', 'bil', 'Bilangan', 9, 22, 'Berapa lamapun juga awan itu diam di atas Kemah Suci, baik dua hari, baik sebulan atau lebih lama, maka orang Israel tetap berkemah dan tidak berangkat; tetapi apabila awan itu naik, barulah mereka berangkat.', 'id', 'TB'),
  ('4', 'bil', 'Bilangan', 9, 23, 'Atas titah TUHAN mereka berkemah dan atas titah TUHAN juga mereka berangkat; mereka memelihara kewajibannya kepada TUHAN, menurut titah TUHAN dengan perantaraan Musa.', 'id', 'TB'),
  ('4', 'bil', 'Bilangan', 10, 1, 'TUHAN berfirman kepada Musa:', 'id', 'TB'),
  ('4', 'bil', 'Bilangan', 10, 2, '"Buatlah dua nafiri dari perak. Dari perak tempaan harus kaubuat itu, supaya dipergunakan untuk memanggil umat Israel dan untuk menyuruh laskar-laskarnya berangkat.', 'id', 'TB'),
  ('4', 'bil', 'Bilangan', 10, 3, 'Apabila kedua nafiri itu ditiup, segenap umat itu harus berkumpul kepadamu di depan pintu Kemah Pertemuan.', 'id', 'TB'),
  ('4', 'bil', 'Bilangan', 10, 4, 'Jikalau hanya satu saja ditiup, maka para pemimpin, para kepala pasukan Israel harus berkumpul kepadamu.', 'id', 'TB'),
  ('4', 'bil', 'Bilangan', 10, 5, 'Apabila kamu meniup tanda semboyan, maka haruslah berangkat laskar-laskar yang berkemah di sebelah timur;', 'id', 'TB'),
  ('4', 'bil', 'Bilangan', 10, 6, 'apabila kamu meniup tanda semboyan kedua kalinya, maka haruslah berangkat laskar-laskar yang berkemah di sebelah selatan. Jadi tanda semboyan harus ditiup untuk menyuruh mereka berangkat;', 'id', 'TB'),
  ('4', 'bil', 'Bilangan', 10, 7, 'tetapi untuk menyuruh jemaah itu berkumpul kamu harus meniup saja tanpa memberi tanda semboyan.', 'id', 'TB'),
  ('4', 'bil', 'Bilangan', 10, 8, 'Nafiri-nafiri itu harus ditiup oleh anak-anak imam Harun; itulah yang harus menjadi ketetapan untuk selama-lamanya bagimu turun-temurun.', 'id', 'TB'),
  ('4', 'bil', 'Bilangan', 10, 9, 'Dan apabila kamu maju berperang di negerimu melawan musuh yang menyesakkan kamu, kamu harus memberi tanda semboyan dengan nafiri, supaya kamu diingat di hadapan TUHAN, Allahmu, dan diselamatkan dari pada musuhmu.', 'id', 'TB'),
  ('4', 'bil', 'Bilangan', 10, 10, 'Juga pada hari-hari kamu bersukaria, pada perayaan-perayaanmu dan pada bulan-bulan barumu haruslah kamu meniup nafiri itu pada waktu mempersembahkan korban-korban bakaranmu dan korban-korban keselamatanmu; maksudnya supaya kamu diingat di hadapan Allahmu; Akulah TUHAN, Allahmu."', 'id', 'TB'),
  ('4', 'bil', 'Bilangan', 10, 11, 'Pada tahun yang kedua, pada bulan yang kedua, pada tanggal dua puluh bulan itu, naiklah awan itu dari atas Kemah Suci, tempat hukum Allah.', 'id', 'TB'),
  ('4', 'bil', 'Bilangan', 10, 12, 'Lalu berangkatlah orang Israel dari padang gurun Sinai menurut aturan keberangkatan mereka, kemudian diamlah awan itu di padang gurun Paran.', 'id', 'TB'),
  ('4', 'bil', 'Bilangan', 10, 13, 'Itulah pertama kali mereka berangkat menurut titah TUHAN dengan perantaraan Musa.', 'id', 'TB'),
  ('4', 'bil', 'Bilangan', 10, 14, 'Terdahulu berangkatlah laskar yang di bawah panji-panji bani Yehuda menurut pasukan mereka; yang mengepalai laskar itu ialah Nahason bin Aminadab;', 'id', 'TB'),
  ('4', 'bil', 'Bilangan', 10, 15, 'yang mengepalai laskar suku bani Isakhar ialah Netaneel bin Zuar;', 'id', 'TB'),
  ('4', 'bil', 'Bilangan', 10, 16, 'yang mengepalai laskar suku bani Zebulon ialah Eliab bin Helon.', 'id', 'TB'),
  ('4', 'bil', 'Bilangan', 10, 17, 'Sesudah itu Kemah Suci dibongkar, dan berangkatlah bani Gerson dan bani Merari yang mengangkat Kemah Suci itu.', 'id', 'TB'),
  ('4', 'bil', 'Bilangan', 10, 18, 'Kemudian berangkatlah laskar yang di bawah panji-panji Ruben menurut pasukan mereka; yang mengepalai laskar itu ialah Elizur bin Syedeur;', 'id', 'TB'),
  ('4', 'bil', 'Bilangan', 10, 19, 'yang mengepalai laskar suku bani Simeon ialah Selumiel bin Zurisyadai;', 'id', 'TB'),
  ('4', 'bil', 'Bilangan', 10, 20, 'yang mengepalai laskar suku bani Gad ialah Elyasaf bin Rehuel.', 'id', 'TB'),
  ('4', 'bil', 'Bilangan', 10, 21, 'Sesudah itu berangkatlah orang Kehat, yang mengangkat barang-barang tempat kudus; Kemah Suci sudah dipasang sebelum mereka datang.', 'id', 'TB'),
  ('4', 'bil', 'Bilangan', 10, 22, 'Kemudian berangkatlah laskar yang di bawah panji-panji bani Efraim menurut pasukan mereka;', 'id', 'TB'),
  ('4', 'bil', 'Bilangan', 10, 23, 'yang mengepalai laskar itu ialah Elisama bin Amihud; yang mengepalai laskar suku bani Manasye ialah Gamaliel bin Pedazur;', 'id', 'TB'),
  ('4', 'bil', 'Bilangan', 10, 24, 'yang mengepalai laskar suku bani Benyamin ialah Abidan bin Gideoni.', 'id', 'TB'),
  ('4', 'bil', 'Bilangan', 10, 25, 'Sebagai barisan penutup semua laskar itu berangkatlah laskar yang di bawah panji-panji bani Dan menurut pasukan mereka; yang mengepalai laskar itu ialah Ahiezer bin Amisyadai;', 'id', 'TB'),
  ('4', 'bil', 'Bilangan', 10, 26, 'yang mengepalai laskar suku bani Asyer ialah Pagiel bin Okhran;', 'id', 'TB'),
  ('4', 'bil', 'Bilangan', 10, 27, 'yang mengepalai laskar suku bani Naftali ialah Ahira bin Enan.', 'id', 'TB'),
  ('4', 'bil', 'Bilangan', 10, 28, 'Itulah aturan keberangkatan orang Israel menurut pasukan mereka, ketika mereka berangkat.', 'id', 'TB'),
  ('4', 'bil', 'Bilangan', 10, 29, 'Lalu berkatalah Musa kepada Hobab anak Rehuel orang Midian, mertua Musa: "Kami berangkat ke tempat yang dimaksud TUHAN ketika Ia berfirman: Aku akan memberikannya kepadamu. Sebab itu ikutlah bersama-sama dengan kami, maka kami akan berbuat baik kepadamu, sebab TUHAN telah menjanjikan yang baik tentang Israel."', 'id', 'TB'),
  ('4', 'bil', 'Bilangan', 10, 30, 'Tetapi jawabnya kepada Musa: "Aku tidak ikut, melainkan aku hendak pergi ke negeriku dan kepada sanak saudaraku."', 'id', 'TB'),
  ('4', 'bil', 'Bilangan', 10, 31, 'Kata Musa: "Janganlah kiranya tinggalkan kami, sebab engkaulah yang tahu, bagaimana kami berkemah di padang gurun, maka engkau dapat menjadi penunjuk jalan bagi kami.', 'id', 'TB'),
  ('4', 'bil', 'Bilangan', 10, 32, 'Jika engkau ikut bersama-sama dengan kami, maka kebaikan yang akan dilakukan TUHAN kepada kami akan kami lakukan juga kepadamu."', 'id', 'TB'),
  ('4', 'bil', 'Bilangan', 10, 33, 'Lalu berangkatlah mereka dari gunung TUHAN dan berjalan tiga hari perjalanan jauhnya, sedang tabut perjanjian TUHAN berangkat di depan mereka dan berjalan tiga hari perjalanan jauhnya untuk mencari tempat perhentian bagi mereka.', 'id', 'TB'),
  ('4', 'bil', 'Bilangan', 10, 34, 'Dan awan TUHAN ada di atas mereka pada siang hari, apabila mereka berangkat dari tempat perkemahan.', 'id', 'TB'),
  ('4', 'bil', 'Bilangan', 10, 35, 'Apabila tabut itu berangkat, berkatalah Musa: "Bangkitlah, TUHAN, supaya musuh-Mu berserak dan orang-orang yang membenci Engkau melarikan diri dari hadapan-Mu."', 'id', 'TB'),
  ('4', 'bil', 'Bilangan', 10, 36, 'Dan apabila tabut itu berhenti, berkatalah ia: "Kembalilah, TUHAN, kepada umat Israel yang beribu-ribu laksa ini."', 'id', 'TB'),
  ('4', 'bil', 'Bilangan', 11, 1, 'Pada suatu kali bangsa itu bersungut-sungut di hadapan TUHAN tentang nasib buruk mereka, dan ketika TUHAN mendengarnya bangkitlah murka-Nya, kemudian menyalalah api TUHAN di antara mereka dan merajalela di tepi tempat perkemahan.', 'id', 'TB'),
  ('4', 'bil', 'Bilangan', 11, 2, 'Lalu berteriaklah bangsa itu kepada Musa, dan Musa berdoa kepada TUHAN; maka padamlah api itu.', 'id', 'TB'),
  ('4', 'bil', 'Bilangan', 11, 3, 'Sebab itu orang menamai tempat itu Tabera, karena telah menyala api TUHAN di antara mereka.', 'id', 'TB'),
  ('4', 'bil', 'Bilangan', 11, 4, 'Orang-orang bajingan yang ada di antara mereka kemasukan nafsu rakus; dan orang Israelpun menangislah pula serta berkata: "Siapakah yang akan memberi kita makan daging?', 'id', 'TB'),
  ('4', 'bil', 'Bilangan', 11, 5, 'Kita teringat kepada ikan yang kita makan di Mesir dengan tidak bayar apa-apa, kepada mentimun dan semangka, bawang prei, bawang merah dan bawang putih.', 'id', 'TB'),
  ('4', 'bil', 'Bilangan', 11, 6, 'Tetapi sekarang kita kurus kering, tidak ada sesuatu apapun, kecuali manna ini saja yang kita lihat."', 'id', 'TB'),
  ('4', 'bil', 'Bilangan', 11, 7, 'Adapun manna itu seperti ketumbar dan kelihatannya seperti damar bedolah.', 'id', 'TB'),
  ('4', 'bil', 'Bilangan', 11, 8, 'Bangsa itu berlari kian ke mari untuk memungutnya, lalu menggilingnya dengan batu kilangan atau menumbuknya dalam lumpang. Mereka memasaknya dalam periuk dan membuatnya menjadi roti bundar; rasanya seperti rasa panganan yang digoreng.', 'id', 'TB'),
  ('4', 'bil', 'Bilangan', 11, 9, 'Dan apabila embun turun di tempat perkemahan pada waktu malam, maka turunlah juga manna di situ.', 'id', 'TB'),
  ('4', 'bil', 'Bilangan', 11, 10, 'Ketika Musa mendengar bangsa itu, yaitu orang-orang dari setiap kaum, menangis di depan pintu kemahnya, bangkitlah murka TUHAN dengan sangat, dan hal itu dipandang jahat oleh Musa.', 'id', 'TB'),
  ('4', 'bil', 'Bilangan', 11, 11, 'Lalu berkatalah Musa kepada TUHAN: "Mengapa Kauperlakukan hamba-Mu ini dengan buruk dan mengapa aku tidak mendapat kasih karunia di mata-Mu, sehingga Engkau membebankan kepadaku tanggung jawab atas seluruh bangsa ini?', 'id', 'TB'),
  ('4', 'bil', 'Bilangan', 11, 12, 'Akukah yang mengandung seluruh bangsa ini atau akukah yang melahirkannya, sehingga Engkau berkata kepadaku: Pangkulah dia seperti pak pengasuh memangku anak yang menyusu, berjalan ke tanah yang Kaujanjikan dengan bersumpah kepada nenek moyangnya?', 'id', 'TB'),
  ('4', 'bil', 'Bilangan', 11, 13, 'Dari manakah aku mengambil daging untuk diberikan kepada seluruh bangsa ini? Sebab mereka menangis kepadaku dengan berkata: Berilah kami daging untuk dimakan.', 'id', 'TB'),
  ('4', 'bil', 'Bilangan', 11, 14, 'Aku seorang diri tidak dapat memikul tanggung jawab atas seluruh bangsa ini, sebab terlalu berat bagiku.', 'id', 'TB'),
  ('4', 'bil', 'Bilangan', 11, 15, 'Jika Engkau berlaku demikian kepadaku, sebaiknya Engkau membunuh aku saja, jika aku mendapat kasih karunia di mata-Mu, supaya aku tidak harus melihat celakaku."', 'id', 'TB'),
  ('4', 'bil', 'Bilangan', 11, 16, 'Lalu berfirmanlah TUHAN kepada Musa: "Kumpulkanlah di hadapan-Ku dari antara para tua-tua Israel tujuh puluh orang, yang kauketahui menjadi tua-tua bangsa dan pengatur pasukannya, kemudian bawalah mereka ke Kemah Pertemuan, supaya mereka berdiri di sana bersama-sama dengan engkau.', 'id', 'TB'),
  ('4', 'bil', 'Bilangan', 11, 17, 'Maka Aku akan turun dan berbicara dengan engkau di sana, lalu sebagian dari Roh yang hinggap padamu itu akan Kuambil dan Kutaruh atas mereka, maka mereka bersama-sama dengan engkau akan memikul tanggung jawab atas bangsa itu, jadi tidak usah lagi engkau seorang diri memikulnya.', 'id', 'TB'),
  ('4', 'bil', 'Bilangan', 11, 18, 'Tetapi kepada bangsa itu haruslah kaukatakan: Kuduskanlah dirimu untuk besok, maka kamu akan makan daging; sebab kamu telah menangis di hadapan TUHAN dengan berkata: Siapakah yang akan memberi kami makan daging? Begitu baik keadaan kita di Mesir, bukan? ?TUHAN akan memberi kamu daging untuk dimakan.', 'id', 'TB'),
  ('4', 'bil', 'Bilangan', 11, 19, 'Bukan hanya satu hari kamu akan memakannya, bukan dua hari, bukan lima hari, bukan sepuluh hari, bukan dua puluh hari,', 'id', 'TB'),
  ('4', 'bil', 'Bilangan', 11, 20, 'tetapi genap sebulan lamanya, sampai keluar dari dalam hidungmu dan sampai kamu muak?karena kamu telah menolak TUHAN yang ada di tengah-tengah kamu dan menangis di hadapan-Nya dengan berkata: Untuk apakah kita keluar dari Mesir?"', 'id', 'TB'),
  ('4', 'bil', 'Bilangan', 11, 21, 'Tetapi kata Musa: "Bangsa yang ada bersama aku ini berjumlah enam ratus ribu orang berjalan kaki, namun Engkau berfirman: Daging akan Kuberikan kepada mereka, dan genap sebulan lamanya mereka akan memakannya!', 'id', 'TB'),
  ('4', 'bil', 'Bilangan', 11, 22, 'Dapatkah sekian banyak kambing domba dan lembu sapi disembelih bagi mereka, sehingga mereka mendapat cukup? Atau dapatkah ditangkap segala ikan di laut bagi mereka, sehingga mereka mendapat cukup?"', 'id', 'TB'),
  ('4', 'bil', 'Bilangan', 11, 23, 'Tetapi TUHAN menjawab Musa: "Masakan kuasa TUHAN akan kurang untuk melakukan itu? Sekarang engkau akan melihat apakah firman-Ku terjadi kepadamu atau tidak!"', 'id', 'TB'),
  ('4', 'bil', 'Bilangan', 11, 24, 'Setelah Musa datang ke luar, disampaikannya firman TUHAN itu kepada bangsa itu. Ia mengumpulkan tujuh puluh orang dari para tua-tua bangsa itu dan menyuruh mereka berdiri di sekeliling kemah.', 'id', 'TB'),
  ('4', 'bil', 'Bilangan', 11, 25, 'Lalu turunlah TUHAN dalam awan dan berbicara kepada Musa, kemudian diambil-Nya sebagian dari Roh yang hinggap padanya, dan ditaruh-Nya atas ketujuh puluh tua-tua itu; ketika Roh itu hinggap pada mereka, kepenuhanlah mereka seperti nabi, tetapi sesudah itu tidak lagi.', 'id', 'TB'),
  ('4', 'bil', 'Bilangan', 11, 26, 'Masih ada dua orang tinggal di tempat perkemahan; yang seorang bernama Eldad, yang lain bernama Medad. Ketika Roh itu hinggap pada mereka?mereka itu termasuk orang-orang yang dicatat, tetapi tidak turut pergi ke kemah?maka kepenuhanlah mereka seperti nabi di tempat perkemahan.', 'id', 'TB'),
  ('4', 'bil', 'Bilangan', 11, 27, 'Lalu berlarilah seorang muda memberitahukan kepada Musa: "Eldad dan Medad kepenuhan seperti nabi di tempat perkemahan."', 'id', 'TB'),
  ('4', 'bil', 'Bilangan', 11, 28, 'Maka menjawablah Yosua bin Nun, yang sejak mudanya menjadi abdi Musa: "Tuanku Musa, cegahlah mereka!"', 'id', 'TB'),
  ('4', 'bil', 'Bilangan', 11, 29, 'Tetapi Musa berkata kepadanya: "Apakah engkau begitu giat mendukung diriku? Ah, kalau seluruh umat TUHAN menjadi nabi, oleh karena TUHAN memberi Roh-Nya hinggap kepada mereka!"', 'id', 'TB'),
  ('4', 'bil', 'Bilangan', 11, 30, 'Kemudian kembalilah Musa ke tempat perkemahan, dia dan para tua-tua Israel.', 'id', 'TB'),
  ('4', 'bil', 'Bilangan', 11, 31, 'Lalu bertiuplah angin yang dari TUHAN asalnya; dibawanyalah burung-burung puyuh dari sebelah laut, dan dihamburkannya ke atas tempat perkemahan dan di sekelilingnya, kira-kira sehari perjalanan jauhnya ke segala penjuru, dan kira-kira dua hasta tingginya dari atas muka bumi.', 'id', 'TB'),
  ('4', 'bil', 'Bilangan', 11, 32, 'Lalu sepanjang hari dan sepanjang malam itu dan sepanjang hari esoknya bangkitlah bangsa itu mengumpulkan burung-burung puyuh itu?setiap orang sedikit-dikitnya mengumpulkan sepuluh homer?,kemudian mereka menyebarkannya lebar-lebar sekeliling tempat perkemahan.', 'id', 'TB'),
  ('4', 'bil', 'Bilangan', 11, 33, 'Selagi daging itu ada di mulut mereka, sebelum dikunyah, maka bangkitlah murka TUHAN terhadap bangsa itu dan TUHAN memukul bangsa itu dengan suatu tulah yang sangat besar.', 'id', 'TB'),
  ('4', 'bil', 'Bilangan', 11, 34, 'Sebab itu dinamailah tempat itu Kibrot-Taawa, karena di sanalah dikuburkan orang-orang yang bernafsu rakus.', 'id', 'TB'),
  ('4', 'bil', 'Bilangan', 11, 35, 'Dari Kibrot-Taawa berangkatlah bangsa itu ke Hazerot dan mereka tinggal di situ.', 'id', 'TB'),
  ('4', 'bil', 'Bilangan', 12, 1, 'Miryam serta Harun mengatai Musa berkenaan dengan perempuan Kush yang diambilnya, sebab memang ia telah mengambil seorang perempuan Kush.', 'id', 'TB'),
  ('4', 'bil', 'Bilangan', 12, 2, 'Kata mereka: "Sungguhkah TUHAN berfirman dengan perantaraan Musa saja? Bukankah dengan perantaraan kita juga Ia berfirman?" Dan kedengaranlah hal itu kepada TUHAN.', 'id', 'TB'),
  ('4', 'bil', 'Bilangan', 12, 3, 'Adapun Musa ialah seorang yang sangat lembut hatinya, lebih dari setiap manusia yang di atas muka bumi.', 'id', 'TB'),
  ('4', 'bil', 'Bilangan', 12, 4, 'Lalu berfirmanlah TUHAN dengan tiba-tiba kepada Musa, Harun dan Miryam: "Keluarlah kamu bertiga ke Kemah Pertemuan." Maka keluarlah mereka bertiga.', 'id', 'TB'),
  ('4', 'bil', 'Bilangan', 12, 5, 'Lalu turunlah TUHAN dalam tiang awan, dan berdiri di pintu kemah itu, lalu memanggil Harun dan Miryam; maka tampillah mereka keduanya.', 'id', 'TB'),
  ('4', 'bil', 'Bilangan', 12, 6, 'Lalu berfirmanlah Ia: "Dengarlah firman-Ku ini. Jika di antara kamu ada seorang nabi, maka Aku, TUHAN menyatakan diri-Ku kepadanya dalam penglihatan, Aku berbicara dengan dia dalam mimpi.', 'id', 'TB'),
  ('4', 'bil', 'Bilangan', 12, 7, 'Bukan demikian hamba-Ku Musa, seorang yang setia dalam segenap rumah-Ku.', 'id', 'TB'),
  ('4', 'bil', 'Bilangan', 12, 8, 'Berhadap-hadapan Aku berbicara dengan dia, terus terang, bukan dengan teka-teki, dan ia memandang rupa TUHAN. Mengapakah kamu tidak takut mengatai hamba-Ku Musa?"', 'id', 'TB'),
  ('4', 'bil', 'Bilangan', 12, 9, 'Sebab itu bangkitlah murka TUHAN terhadap mereka, lalu pergilah Ia.', 'id', 'TB'),
  ('4', 'bil', 'Bilangan', 12, 10, 'Dan ketika awan telah naik dari atas kemah, maka tampaklah Miryam kena kusta, putih seperti salju; ketika Harun berpaling kepada Miryam, maka dilihatnya, bahwa dia kena kusta!', 'id', 'TB'),
  ('4', 'bil', 'Bilangan', 12, 11, 'Lalu kata Harun kepada Musa: "Ah tuanku, janganlah kiranya timpakan kepada kami dosa ini, yang kami perbuat dalam kebodohan kami.', 'id', 'TB'),
  ('4', 'bil', 'Bilangan', 12, 12, 'Janganlah kiranya dibiarkan dia sebagai anak gugur, yang pada waktu keluar dari kandungan ibunya sudah setengah busuk dagingnya."', 'id', 'TB'),
  ('4', 'bil', 'Bilangan', 12, 13, 'Lalu berserulah Musa kepada TUHAN: "Ya Allah, sembuhkanlah kiranya dia."', 'id', 'TB'),
  ('4', 'bil', 'Bilangan', 12, 14, 'Kemudian berfirmanlah TUHAN kepada Musa: "Sekiranya ayahnya meludahi mukanya, tidakkah ia mendapat malu selama tujuh hari? Biarlah dia selama tujuh hari dikucilkan ke luar tempat perkemahan, kemudian bolehlah ia diterima kembali."', 'id', 'TB'),
  ('4', 'bil', 'Bilangan', 12, 15, 'Jadi dikucilkanlah Miryam ke luar tempat perkemahan tujuh hari lamanya, dan bangsa itu tidak berangkat sebelum Miryam diterima kembali.', 'id', 'TB'),
  ('4', 'bil', 'Bilangan', 12, 16, 'Kemudian berangkatlah mereka dari Hazerot dan berkemah di padang gurun Paran.', 'id', 'TB'),
  ('4', 'bil', 'Bilangan', 13, 1, 'TUHAN berfirman kepada Musa:', 'id', 'TB'),
  ('4', 'bil', 'Bilangan', 13, 2, '"Suruhlah beberapa orang mengintai tanah Kanaan, yang akan Kuberikan kepada orang Israel; dari setiap suku nenek moyang mereka haruslah kausuruh seorang, semuanya pemimpin-pemimpin di antara mereka."', 'id', 'TB'),
  ('4', 'bil', 'Bilangan', 13, 3, 'Lalu Musa menyuruh mereka dari padang gurun Paran, sesuai dengan titah TUHAN; semua orang itu adalah kepala-kepala di antara orang Israel.', 'id', 'TB'),
  ('4', 'bil', 'Bilangan', 13, 4, 'Dan inilah nama-nama mereka: Dari suku Ruben: Syamua bin Zakur;', 'id', 'TB'),
  ('4', 'bil', 'Bilangan', 13, 5, 'dari suku Simeon: Safat bin Hori;', 'id', 'TB'),
  ('4', 'bil', 'Bilangan', 13, 6, 'dari suku Yehuda: Kaleb bin Yefune;', 'id', 'TB'),
  ('4', 'bil', 'Bilangan', 13, 7, 'dari suku Isakhar: Yigal bin Yusuf;', 'id', 'TB'),
  ('4', 'bil', 'Bilangan', 13, 8, 'dari suku Efraim: Hosea bin Nun;', 'id', 'TB'),
  ('4', 'bil', 'Bilangan', 13, 9, 'dari suku Benyamin: Palti bin Rafu;', 'id', 'TB'),
  ('4', 'bil', 'Bilangan', 13, 10, 'dari suku Zebulon: Gadiel bin Sodi;', 'id', 'TB'),
  ('4', 'bil', 'Bilangan', 13, 11, 'dari suku Yusuf, yakni dari suku Manasye: Gadi bin Susi;', 'id', 'TB'),
  ('4', 'bil', 'Bilangan', 13, 12, 'dari suku Dan: Amiel bin Gemali;', 'id', 'TB'),
  ('4', 'bil', 'Bilangan', 13, 13, 'dari suku Asyer: Setur bin Mikhael;', 'id', 'TB'),
  ('4', 'bil', 'Bilangan', 13, 14, 'dari suku Naftali: Nahbi bin Wofsi;', 'id', 'TB'),
  ('4', 'bil', 'Bilangan', 13, 15, 'dari suku Gad: Guel bin Makhi.', 'id', 'TB'),
  ('4', 'bil', 'Bilangan', 13, 16, 'Itulah nama orang-orang yang disuruh Musa untuk mengintai negeri itu; dan Musa menamai Hosea bin Nun itu Yosua.', 'id', 'TB'),
  ('4', 'bil', 'Bilangan', 13, 17, 'Maka Musa menyuruh mereka untuk mengintai tanah Kanaan, katanya kepada mereka: "Pergilah dari sini ke Tanah Negeb dan naiklah ke pegunungan,', 'id', 'TB'),
  ('4', 'bil', 'Bilangan', 13, 18, 'dan amat-amatilah bagaimana keadaan negeri itu, apakah bangsa yang mendiaminya kuat atau lemah, apakah mereka sedikit atau banyak;', 'id', 'TB'),
  ('4', 'bil', 'Bilangan', 13, 19, 'dan bagaimana negeri yang didiaminya, apakah baik atau buruk, bagaimana kota-kota yang didiaminya, apakah mereka diam di tempat-tempat yang terbuka atau di tempat-tempat yang berkubu,', 'id', 'TB'),
  ('4', 'bil', 'Bilangan', 13, 20, 'dan bagaimana tanah itu, apakah gemuk atau kurus, apakah ada di sana pohon-pohonan atau tidak. Tabahkanlah hatimu dan bawalah sedikit dari hasil negeri itu." Waktu itu ialah musim hulu hasil anggur.', 'id', 'TB'),
  ('4', 'bil', 'Bilangan', 13, 21, 'Mereka pergi ke sana, lalu mengintai negeri itu mulai dari padang gurun Zin sampai ke Rehob, ke jalan yang menuju ke Hamat.', 'id', 'TB'),
  ('4', 'bil', 'Bilangan', 13, 22, 'Mereka berjalan melalui Tanah Negeb, lalu sampai ke Hebron; di sana ada Ahiman, Sesai dan Talmai, keturunan Enak. Hebron didirikan tujuh tahun lebih dahulu dari Soan di Mesir.', 'id', 'TB'),
  ('4', 'bil', 'Bilangan', 13, 23, 'Ketika mereka sampai ke lembah Eskol, dipotong merekalah di sana suatu cabang dengan setandan buah anggurnya, lalu berdualah mereka menggandarnya; juga mereka membawa beberapa buah delima dan buah ara.', 'id', 'TB'),
  ('4', 'bil', 'Bilangan', 13, 24, 'Tempat itu dinamai orang lembah Eskol, karena tandan buah anggur yang dipotong orang Israel di sana.', 'id', 'TB'),
  ('4', 'bil', 'Bilangan', 13, 25, 'Sesudah lewat empat puluh hari pulanglah mereka dari pengintaian negeri itu,', 'id', 'TB'),
  ('4', 'bil', 'Bilangan', 13, 26, 'dan langsung datang kepada Musa, Harun dan segenap umat Israel di Kadesh, di padang gurun Paran. Mereka membawa pulang kabar kepada keduanya dan kepada segenap umat itu dan memperlihatkan kepada sekaliannya hasil negeri itu.', 'id', 'TB'),
  ('4', 'bil', 'Bilangan', 13, 27, 'Mereka menceritakan kepadanya: "Kami sudah masuk ke negeri, ke mana kausuruh kami, dan memang negeri itu berlimpah-limpah susu dan madunya, dan inilah hasilnya.', 'id', 'TB'),
  ('4', 'bil', 'Bilangan', 13, 28, 'Hanya, bangsa yang diam di negeri itu kuat-kuat dan kota-kotanya berkubu dan sangat besar, juga keturunan Enak telah kami lihat di sana.', 'id', 'TB'),
  ('4', 'bil', 'Bilangan', 13, 29, 'Orang Amalek diam di Tanah Negeb, orang Het, orang Yebus dan orang Amori diam di pegunungan, orang Kanaan diam sepanjang laut dan sepanjang tepi sungai Yordan."', 'id', 'TB'),
  ('4', 'bil', 'Bilangan', 13, 30, 'Kemudian Kaleb mencoba menenteramkan hati bangsa itu di hadapan Musa, katanya: "Tidak! Kita akan maju dan menduduki negeri itu, sebab kita pasti akan mengalahkannya!"', 'id', 'TB'),
  ('4', 'bil', 'Bilangan', 13, 31, 'Tetapi orang-orang yang pergi ke sana bersama-sama dengan dia berkata: "Kita tidak dapat maju menyerang bangsa itu, karena mereka lebih kuat dari pada kita."', 'id', 'TB'),
  ('4', 'bil', 'Bilangan', 13, 32, 'Juga mereka menyampaikan kepada orang Israel kabar busuk tentang negeri yang diintai mereka, dengan berkata: "Negeri yang telah kami lalui untuk diintai adalah suatu negeri yang memakan penduduknya, dan semua orang yang kami lihat di sana adalah orang-orang yang tinggi-tinggi perawakannya.', 'id', 'TB'),
  ('4', 'bil', 'Bilangan', 13, 33, 'Juga kami lihat di sana orang-orang raksasa, orang Enak yang berasal dari orang-orang raksasa, dan kami lihat diri kami seperti belalang, dan demikian juga mereka terhadap kami."', 'id', 'TB'),
  ('4', 'bil', 'Bilangan', 14, 1, 'Lalu segenap umat itu mengeluarkan suara nyaring dan bangsa itu menangis pada malam itu.', 'id', 'TB'),
  ('4', 'bil', 'Bilangan', 14, 2, 'Bersungut-sungutlah semua orang Israel kepada Musa dan Harun; dan segenap umat itu berkata kepada mereka: "Ah, sekiranya kami mati di tanah Mesir, atau di padang gurun ini!', 'id', 'TB'),
  ('4', 'bil', 'Bilangan', 14, 3, 'Mengapakah TUHAN membawa kami ke negeri ini, supaya kami tewas oleh pedang, dan isteri serta anak-anak kami menjadi tawanan? Bukankah lebih baik kami pulang ke Mesir?"', 'id', 'TB'),
  ('4', 'bil', 'Bilangan', 14, 4, 'Dan mereka berkata seorang kepada yang lain: "Baiklah kita mengangkat seorang pemimpin, lalu pulang ke Mesir."', 'id', 'TB'),
  ('4', 'bil', 'Bilangan', 14, 5, 'Lalu sujudlah Musa dan Harun di depan mata seluruh jemaah Israel yang berkumpul di situ.', 'id', 'TB'),
  ('4', 'bil', 'Bilangan', 14, 6, 'Tetapi Yosua bin Nun dan Kaleb bin Yefune, yang termasuk orang-orang yang telah mengintai negeri itu, mengoyakkan pakaiannya,', 'id', 'TB'),
  ('4', 'bil', 'Bilangan', 14, 7, 'dan berkata kepada segenap umat Israel: "Negeri yang kami lalui untuk diintai itu adalah luar biasa baiknya.', 'id', 'TB'),
  ('4', 'bil', 'Bilangan', 14, 8, 'Jika TUHAN berkenan kepada kita, maka Ia akan membawa kita masuk ke negeri itu dan akan memberikannya kepada kita, suatu negeri yang berlimpah-limpah susu dan madunya.', 'id', 'TB'),
  ('4', 'bil', 'Bilangan', 14, 9, 'Hanya, janganlah memberontak kepada TUHAN, dan janganlah takut kepada bangsa negeri itu, sebab mereka akan kita telan habis. Yang melindungi mereka sudah meninggalkan mereka, sedang TUHAN menyertai kita; janganlah takut kepada mereka."', 'id', 'TB'),
  ('4', 'bil', 'Bilangan', 14, 10, 'Lalu segenap umat itu mengancam hendak melontari kedua orang itu dengan batu. Tetapi tampaklah kemuliaan TUHAN di Kemah Pertemuan kepada semua orang Israel.', 'id', 'TB'),
  ('4', 'bil', 'Bilangan', 14, 11, 'TUHAN berfirman kepada Musa: "Berapa lama lagi bangsa ini menista Aku, dan berapa lama lagi mereka tidak mau percaya kepada-Ku, sekalipun sudah ada segala tanda mujizat yang Kulakukan di tengah-tengah mereka!', 'id', 'TB'),
  ('4', 'bil', 'Bilangan', 14, 12, 'Aku akan memukul mereka dengan penyakit sampar dan melenyapkan mereka, tetapi engkau akan Kubuat menjadi bangsa yang lebih besar dan lebih kuat dari pada mereka."', 'id', 'TB'),
  ('4', 'bil', 'Bilangan', 14, 13, 'Lalu berkatalah Musa kepada TUHAN: "Jikalau hal itu kedengaran kepada orang Mesir, padahal Engkau telah menuntun bangsa ini dengan kekuatan-Mu dari tengah-tengah mereka,', 'id', 'TB'),
  ('4', 'bil', 'Bilangan', 14, 14, 'mereka akan berceritera kepada penduduk negeri ini, yang telah mendengar bahwa Engkau, TUHAN, ada di tengah-tengah bangsa ini, dan bahwa Engkau, TUHAN, menampakkan diri-Mu kepada mereka dengan berhadapan muka, waktu awan-Mu berdiri di atas mereka dan waktu Engkau berjalan mendahului mereka di dalam tiang awan pada waktu siang dan di dalam tiang api pada waktu malam.', 'id', 'TB'),
  ('4', 'bil', 'Bilangan', 14, 15, 'Jadi jikalau Engkau membunuh bangsa ini sampai habis, maka bangsa-bangsa yang mendengar kabar tentang Engkau itu nanti berkata:', 'id', 'TB'),
  ('4', 'bil', 'Bilangan', 14, 16, 'Oleh karena TUHAN tidak berkuasa membawa bangsa ini masuk ke negeri yang dijanjikan-Nya dengan bersumpah kepada mereka, maka Ia menyembelih mereka di padang gurun.', 'id', 'TB'),
  ('4', 'bil', 'Bilangan', 14, 17, 'Jadi sekarang, biarlah kiranya kekuatan TUHAN itu nyata kebesarannya, seperti yang Kaufirmankan:', 'id', 'TB'),
  ('4', 'bil', 'Bilangan', 14, 18, 'TUHAN itu berpanjangan sabar dan kasih setia-Nya berlimpah-limpah, Ia mengampuni kesalahan dan pelanggaran, tetapi sekali-kali tidak membebaskan orang yang bersalah dari hukuman, bahkan Ia membalaskan kesalahan bapa kepada anak-anaknya, kepada keturunan yang ketiga dan keempat.', 'id', 'TB'),
  ('4', 'bil', 'Bilangan', 14, 19, 'Ampunilah kiranya kesalahan bangsa ini sesuai dengan kebesaran kasih setia-Mu, seperti Engkau telah mengampuni bangsa ini mulai dari Mesir sampai ke mari."', 'id', 'TB'),
  ('4', 'bil', 'Bilangan', 14, 20, 'Berfirmanlah TUHAN: "Aku mengampuninya sesuai dengan permintaanmu.', 'id', 'TB'),
  ('4', 'bil', 'Bilangan', 14, 21, 'Hanya, demi Aku yang hidup dan kemuliaan TUHAN memenuhi seluruh bumi:', 'id', 'TB'),
  ('4', 'bil', 'Bilangan', 14, 22, 'Semua orang yang telah melihat kemuliaan-Ku dan tanda-tanda mujizat yang Kuperbuat di Mesir dan di padang gurun, namun telah sepuluh kali mencobai Aku dan tidak mau mendengarkan suara-Ku,', 'id', 'TB'),
  ('4', 'bil', 'Bilangan', 14, 23, 'pastilah tidak akan melihat negeri yang Kujanjikan dengan bersumpah kepada nenek moyang mereka! Semua yang menista Aku ini tidak akan melihatnya.', 'id', 'TB'),
  ('4', 'bil', 'Bilangan', 14, 24, 'Tetapi hamba-Ku Kaleb, karena lain jiwa yang ada padanya dan ia mengikut Aku dengan sepenuhnya, akan Kubawa masuk ke negeri yang telah dimasukinya itu, dan keturunannya akan memilikinya.', 'id', 'TB'),
  ('4', 'bil', 'Bilangan', 14, 25, 'Orang Amalek dan orang Kanaan diam di lembah. Sebab itu berpalinglah besok dan berangkatlah ke padang gurun, ke arah Laut Teberau."', 'id', 'TB'),
  ('4', 'bil', 'Bilangan', 14, 26, 'Lagi berfirmanlah TUHAN kepada Musa dan Harun:', 'id', 'TB'),
  ('4', 'bil', 'Bilangan', 14, 27, '"Berapa lama lagi umat yang jahat ini akan bersungut-sungut kepada-Ku? Segala sesuatu yang disungut-sungutkan orang Israel kepada-Ku telah Kudengar.', 'id', 'TB'),
  ('4', 'bil', 'Bilangan', 14, 28, 'Katakanlah kepada mereka: Demi Aku yang hidup, demikianlah firman TUHAN, bahwasanya seperti yang kamu katakan di hadapan-Ku, demikianlah akan Kulakukan kepadamu.', 'id', 'TB'),
  ('4', 'bil', 'Bilangan', 14, 29, 'Di padang gurun ini bangkai-bangkaimu akan berhantaran, yakni semua orang di antara kamu yang dicatat, semua tanpa terkecuali yang berumur dua puluh tahun ke atas, karena kamu telah bersungut-sungut kepada-Ku.', 'id', 'TB'),
  ('4', 'bil', 'Bilangan', 14, 30, 'Bahwasanya kamu ini tidak akan masuk ke negeri yang dengan mengangkat sumpah telah Kujanjikan akan Kuberi kamu diami, kecuali Kaleb bin Yefune dan Yosua bin Nun!', 'id', 'TB'),
  ('4', 'bil', 'Bilangan', 14, 31, 'Tentang anak-anakmu yang telah kamu katakan: Mereka akan menjadi tawanan, merekalah yang akan Kubawa masuk, supaya mereka mengenal negeri yang telah kamu hinakan itu.', 'id', 'TB'),
  ('4', 'bil', 'Bilangan', 14, 32, 'Tetapi mengenai kamu, bangkai-bangkaimu akan berhantaran di padang gurun ini,', 'id', 'TB'),
  ('4', 'bil', 'Bilangan', 14, 33, 'dan anak-anakmu akan mengembara sebagai penggembala di padang gurun empat puluh tahun lamanya dan akan menanggung akibat ketidaksetiaan, sampai bangkai-bangkaimu habis di padang gurun.', 'id', 'TB'),
  ('4', 'bil', 'Bilangan', 14, 34, 'Sesuai dengan jumlah hari yang kamu mengintai negeri itu, yakni empat puluh hari, satu hari dihitung satu tahun, jadi empat puluh tahun lamanya kamu harus menanggung akibat kesalahanmu, supaya kamu tahu rasanya, jika Aku berbalik dari padamu:', 'id', 'TB'),
  ('4', 'bil', 'Bilangan', 14, 35, 'Aku, TUHAN, yang berkata demikian. Sesungguhnya Aku akan melakukan semuanya itu kepada segenap umat yang jahat ini yang telah bersepakat melawan Aku. Di padang gurun ini mereka akan habis dan di sinilah mereka akan mati."', 'id', 'TB'),
  ('4', 'bil', 'Bilangan', 14, 36, 'Adapun orang-orang yang telah disuruh Musa untuk mengintai negeri itu, yang sudah pulang dan menyebabkan segenap umat itu bersungut-sungut kepada Musa dengan menyampaikan kabar busuk tentang negeri itu,', 'id', 'TB'),
  ('4', 'bil', 'Bilangan', 14, 37, 'orang-orang itu mati, kena tulah di hadapan TUHAN.', 'id', 'TB'),
  ('4', 'bil', 'Bilangan', 14, 38, 'Tetapi yang tinggal hidup dari orang-orang yang telah pergi mengintai negeri itu hanyalah Yosua bin Nun dan Kaleb bin Yefune.', 'id', 'TB'),
  ('4', 'bil', 'Bilangan', 14, 39, 'Setelah Musa menyampaikan perkataan ini kepada semua orang Israel, maka berkabunglah bangsa itu dengan sangat.', 'id', 'TB'),
  ('4', 'bil', 'Bilangan', 14, 40, 'Dan keesokan harinya bangunlah mereka pagi-pagi hendak naik ke puncak gunung sambil berkata: "Sekarang kita hendak maju ke negeri yang difirmankan TUHAN itu; memang kita telah berbuat dosa."', 'id', 'TB'),
  ('4', 'bil', 'Bilangan', 14, 41, 'Tetapi kata Musa: "Mengapakah kamu hendak melanggar titah TUHAN? Hal itu tidak akan berhasil.', 'id', 'TB'),
  ('4', 'bil', 'Bilangan', 14, 42, 'Janganlah maju, sebab TUHAN tidak ada di tengah-tengahmu, supaya jangan kamu dikalahkan oleh musuhmu,', 'id', 'TB'),
  ('4', 'bil', 'Bilangan', 14, 43, 'sebab orang Amalek dan orang Kanaan ada di sana di depanmu dan kamu akan tewas oleh pedang; dari sebab kamu berbalik membelakangi TUHAN, maka TUHAN tidak akan menyertai kamu."', 'id', 'TB'),
  ('4', 'bil', 'Bilangan', 14, 44, 'Meskipun demikian, mereka nekat naik ke puncak gunung itu, tetapi tabut perjanjian TUHAN dan Musa juga tidaklah meninggalkan tempat perkemahan.', 'id', 'TB'),
  ('4', 'bil', 'Bilangan', 14, 45, 'Lalu turunlah orang Amalek dan orang Kanaan yang mendiami pegunungan itu dan menyerang mereka; kemudian orang-orang itu mencerai-beraikan mereka sampai ke Horma.', 'id', 'TB'),
  ('4', 'bil', 'Bilangan', 15, 1, 'TUHAN berfirman kepada Musa:', 'id', 'TB'),
  ('4', 'bil', 'Bilangan', 15, 2, '"Berbicaralah kepada orang Israel dan katakanlah kepada mereka: Apabila kamu masuk ke negeri yang akan Kuberikan kepadamu menjadi tempat kediamanmu,', 'id', 'TB'),
  ('4', 'bil', 'Bilangan', 15, 3, 'dan kamu hendak mempersembahkan korban api-apian bagi TUHAN, dari lembu sapi atau kambing domba, baik korban bakaran atau korban sembelihan, baik untuk membayar suatu nazar khusus, atau sebagai persembahan sukarela atau pada waktu perayaan-perayaanmu, dan dengan demikian menyediakan bau yang menyenangkan bagi TUHAN,', 'id', 'TB'),
  ('4', 'bil', 'Bilangan', 15, 4, 'maka orang yang mempersembahkan persembahannya itu kepada TUHAN, haruslah mempersembahkan sebagai korban sajian sepersepuluh efa tepung yang terbaik, diolah dengan seperempat hin minyak.', 'id', 'TB'),
  ('4', 'bil', 'Bilangan', 15, 5, 'Dan beserta korban bakaran atau korban sembelihan itu engkau harus juga mempersembahkan seperempat hin anggur sebagai korban curahan, untuk setiap ekor domba yang dipersembahkan.', 'id', 'TB'),
  ('4', 'bil', 'Bilangan', 15, 6, 'Tetapi jikalau persembahanmu itu seekor domba jantan, engkau harus mempersembahkan sebagai korban sajian dua persepuluh efa tepung yang terbaik, diolah dengan sepertiga hin minyak,', 'id', 'TB'),
  ('4', 'bil', 'Bilangan', 15, 7, 'dan sebagai korban curahan haruslah kaupersembahkan sepertiga hin anggur, menjadi bau yang menyenangkan bagi TUHAN.', 'id', 'TB'),
  ('4', 'bil', 'Bilangan', 15, 8, 'Dan apabila engkau mengolah seekor lembu, sebagai korban bakaran atau sebagai korban sembelihan, baik untuk membayar suatu nazar khusus maupun sebagai korban keselamatan bagi TUHAN,', 'id', 'TB'),
  ('4', 'bil', 'Bilangan', 15, 9, 'maka beserta lembu itu haruslah dipersembahkan sebagai korban sajian tiga persepuluh efa tepung yang terbaik, diolah dengan setengah hin minyak,', 'id', 'TB'),
  ('4', 'bil', 'Bilangan', 15, 10, 'dan sebagai korban curahan haruslah kaupersembahkan setengah hin anggur. Itulah korban api-apian yang baunya menyenangkan bagi TUHAN.', 'id', 'TB'),
  ('4', 'bil', 'Bilangan', 15, 11, 'Demikianlah harus diperbuat untuk setiap ekor lembu dan untuk setiap ekor domba jantan dan untuk setiap ekor domba atau kambing.', 'id', 'TB'),
  ('4', 'bil', 'Bilangan', 15, 12, 'Berapapun jumlah hewan yang kamu olah, untuk setiap hewan itu harus kamu perbuat demikian juga.', 'id', 'TB'),
  ('4', 'bil', 'Bilangan', 15, 13, 'Setiap orang Israel asli haruslah berbuat demikian, apabila ia mempersembahkan korban api-apian yang baunya menyenangkan bagi TUHAN.', 'id', 'TB'),
  ('4', 'bil', 'Bilangan', 15, 14, 'Dan apabila seorang asing telah menetap padamu, atau seorang lain yang tinggal di antara kamu atau di antara keturunanmu kelak, hendak mempersembahkan korban api-apian yang baunya menyenangkan bagi TUHAN, maka seperti yang kamu perbuat, demikianlah harus diperbuatnya.', 'id', 'TB'),
  ('4', 'bil', 'Bilangan', 15, 15, 'Mengenai jemaah itu, haruslah ada satu ketetapan bagi kamu dan bagi orang asing yang tinggal padamu; itulah suatu ketetapan untuk selama-lamanya bagi kamu turun-temurun: kamu dan orang asing haruslah sama di hadapan TUHAN.', 'id', 'TB'),
  ('4', 'bil', 'Bilangan', 15, 16, 'Oleh karena TUHAN tidak berkuasa membawa bangsa ini masuk ke negeri yang dijanjikan-Nya dengan bersumpah kepada mereka, maka Ia menyembelih mereka di padang gurun.', 'id', 'TB'),
  ('4', 'bil', 'Bilangan', 15, 17, 'Jadi sekarang, biarlah kiranya kekuatan TUHAN itu nyata kebesarannya, seperti yang Kaufirmankan:', 'id', 'TB'),
  ('4', 'bil', 'Bilangan', 15, 18, 'TUHAN itu berpanjangan sabar dan kasih setia-Nya berlimpah-limpah, Ia mengampuni kesalahan dan pelanggaran, tetapi sekali-kali tidak membebaskan orang yang bersalah dari hukuman, bahkan Ia membalaskan kesalahan bapa kepada anak-anaknya, kepada keturunan yang ketiga dan keempat.', 'id', 'TB'),
  ('4', 'bil', 'Bilangan', 15, 19, 'Ampunilah kiranya kesalahan bangsa ini sesuai dengan kebesaran kasih setia-Mu, seperti Engkau telah mengampuni bangsa ini mulai dari Mesir sampai ke mari."', 'id', 'TB'),
  ('4', 'bil', 'Bilangan', 15, 20, 'Berfirmanlah TUHAN: "Aku mengampuninya sesuai dengan permintaanmu.', 'id', 'TB'),
  ('4', 'bil', 'Bilangan', 15, 21, 'Hanya, demi Aku yang hidup dan kemuliaan TUHAN memenuhi seluruh bumi:', 'id', 'TB'),
  ('4', 'bil', 'Bilangan', 15, 22, 'Semua orang yang telah melihat kemuliaan-Ku dan tanda-tanda mujizat yang Kuperbuat di Mesir dan di padang gurun, namun telah sepuluh kali mencobai Aku dan tidak mau mendengarkan suara-Ku,', 'id', 'TB'),
  ('4', 'bil', 'Bilangan', 15, 23, 'pastilah tidak akan melihat negeri yang Kujanjikan dengan bersumpah kepada nenek moyang mereka! Semua yang menista Aku ini tidak akan melihatnya.', 'id', 'TB'),
